INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24376, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你心里想的一个主意。", "primary_collocate": null, "pronunciation": "xiǎng fa", "ipa": "ɕiɑŋ²¹⁴ fa", "syllable_count": 2, "sentences": [{"text": "我有一个好想法。", "target_word": "想法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你对这件事有什么想法？", "target_word": "想法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法和我不一样。", "target_word": "想法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想听听你的想法。", "target_word": "想法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法很有意思。", "target_word": "想法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的想法告诉了老师。", "target_word": "想法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们有很多有意思的想法。", "target_word": "想法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板同意了我的想法。", "target_word": "想法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的想法变了，不去北京了。", "target_word": "想法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有自己的想法。", "target_word": "想法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "心里对事情的看法或主意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6750d34-8059-4248-b24c-0c46300c707b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "想法", "is_correct": true, "explanation": "正确。“好想法”指不错的主意，符合句意。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“好”修饰事物或品质，不能说“好感冒”。"}, {"text": "火灾", "is_correct": false, "explanation": "语义：火灾是灾害，不能用“好”来修饰，不能说“好火灾”。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是灾害，不能说“好地震”。"}], "explanations": {"想法": "正确。“好想法”指不错的主意，符合句意。", "感冒": "搭配：“好”修饰事物或品质，不能说“好感冒”。", "火灾": "语义：火灾是灾害，不能用“好”来修饰，不能说“好火灾”。", "地震": "语义：地震是灾害，不能说“好地震”。"}, "sentence_index": 0, "correct_answer": "想法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快就解决了这个想法。", "explanation": "这里应该用〈问题〉。“解决”的对象是问题、矛盾等，想法不能被解决。"}, {"text": "我们终于制订了一个想法。", "explanation": "这里应该用〈计划〉。“制订”搭配计划，不搭配想法。"}, {"text": "他把想法放进了箱子里。", "explanation": "想法是抽象的，不能装进箱子，应该说“放在心里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想法", "is_correct": true, "explanation": "正确。“有意思的想法”指有趣的主意，符合句意。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：“有意思”修饰有趣的事物，眼泪不能这样形容。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能用“有意思”来形容，与句意不符。"}, {"text": "疼痛", "is_correct": false, "explanation": "搭配：“有意思的”不修饰疼痛这类感受，搭配不当。"}], "explanations": {"想法": "正确。“有意思的想法”指有趣的主意，符合句意。", "眼泪": "语义：“有意思”修饰有趣的事物，眼泪不能这样形容。", "空气": "语义：空气不能用“有意思”来形容，与句意不符。", "疼痛": "搭配：“有意思的”不修饰疼痛这类感受，搭配不当。"}, "sentence_index": 6, "correct_answer": "想法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他吃了一个想法。", "explanation": "“吃”的宾语应是食物，想法是抽象的，不能吃。"}, {"text": "他在台上唱了一个想法。", "explanation": "这里应该用〈歌曲〉。“唱”的对象是歌，想法是抽象的，不能唱。"}, {"text": "我在超市买了两个想法。", "explanation": "想法不是商品，不能在超市买，这里不能用“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些想法们很有意思。", "corrected_sentence": "这些想法很有意思。", "error_description": "错误：“想法”不是指人的名词，不能加“们”。正确说法是：这些想法很有意思。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有很好想法。", "corrected_sentence": "他有很好的想法。", "error_description": "错误：修饰语“很好”与中心词“想法”之间要用“的”连接。正确说法是：他有很好的想法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
