INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24378, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "坐在就是一个人把屁股放在椅子上或地上。", "primary_collocate": null, "pronunciation": "zuò zài", "ipa": "tswo˥˩ tsai̯˥˩", "syllable_count": 2, "sentences": [{"text": "他坐在椅子上。", "target_word": "坐在", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我坐在你的左边。", "target_word": "坐在", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈坐在沙发上看书。", "target_word": "坐在", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们坐在地上玩儿。", "target_word": "坐在", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师坐在教室前面。", "target_word": "坐在", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小猫坐在桌子上。", "target_word": "坐在", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们坐在公园的长椅上聊天。", "target_word": "坐在", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐在那儿，一句话也不说。", "target_word": "坐在", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她坐在窗边，看着外面的雨。", "target_word": "坐在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我坐在最后一排，什么也没看见。", "target_word": "坐在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人坐下并停留在某个位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dd17ffc-a76b-42f7-bbad-b8985cc3d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坐在", "is_correct": true, "explanation": "正确：“他坐在椅子上”表示他坐在椅子上。"}, {"text": "游在", "is_correct": false, "explanation": "语义：游要在水中进行，椅子上不能游。"}, {"text": "飞在", "is_correct": false, "explanation": "语义：椅子上不能飞，句意荒谬。"}, {"text": "生活在", "is_correct": false, "explanation": "搭配：“生活在”要接可以居住的地方，椅子上不能用来居住。"}], "explanations": {"坐在": "正确：“他坐在椅子上”表示他坐在椅子上。", "游在": "语义：游要在水中进行，椅子上不能游。", "飞在": "语义：椅子上不能飞，句意荒谬。", "生活在": "搭配：“生活在”要接可以居住的地方，椅子上不能用来居住。"}, "sentence_index": 0, "correct_answer": "坐在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "照片坐在墙上。", "explanation": "这里应该用〈挂在〉。“坐在”只用于人或动物坐下，照片挂在墙上要说“挂在”。"}, {"text": "他坐在北京。", "explanation": "这里应该用〈住在〉。“坐在”指坐于椅子等物体上，不能表示在某地居住。"}, {"text": "花瓶坐在桌子上。", "explanation": "这里应该用〈摆在〉。“坐在”只用于人或动物坐下，花瓶等物品要说“摆在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坐在", "is_correct": true, "explanation": "正确：“我们坐在公园的长椅上聊天”描述坐着聊天的状态。"}, {"text": "跑在", "is_correct": false, "explanation": "语义：长椅上不能跑着聊天，动作与句意不符。"}, {"text": "跳在", "is_correct": false, "explanation": "语义：跳在长椅上聊天不合常理，与“聊天”的状态不符。"}, {"text": "放在", "is_correct": false, "explanation": "配价：“放在”需要带被放置的对象，此句缺少对象，不能这样用。"}], "explanations": {"坐在": "正确：“我们坐在公园的长椅上聊天”描述坐着聊天的状态。", "跑在": "语义：长椅上不能跑着聊天，动作与句意不符。", "跳在": "语义：跳在长椅上聊天不合常理，与“聊天”的状态不符。", "放在": "配价：“放在”需要带被放置的对象，此句缺少对象，不能这样用。"}, "sentence_index": 6, "correct_answer": "坐在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪坐在屋顶上。", "explanation": "这里应该用〈落在〉。“坐在”需要有坐的动作，雪落下要说“落在”。"}, {"text": "车坐在路边。", "explanation": "这里应该用〈停在〉。车辆停放不能说“坐在”，“坐在”只用于人或动物。"}, {"text": "他坐在农村。", "explanation": "这里应该用〈生活在〉。“坐在”指坐在椅子等物上，表示在某地生活要说“生活在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟坐在在床边看书。", "corrected_sentence": "我弟弟坐在床边看书。", "error_description": "错误形式：坐在在床边；正确形式：坐在床边。“在”重复了一次。“坐在”后面直接接表示处所的词语，不能再加一个“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹坐在过窗边看书。", "corrected_sentence": "妹妹坐在窗边看书。", "error_description": "错误在“过”：“过”插在介词“在”和处所词“窗边”之间，破坏了“坐在”的结构。应去掉“过”，说“妹妹坐在窗边看书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
