INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24380, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "河是流动的大水沟。", "primary_collocate": null, "pronunciation": "hé", "ipa": "xɤ˧˥", "syllable_count": 1, "sentences": [{"text": "我家旁边有一条河。", "target_word": "河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水很干净。", "target_word": "河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在河里玩水。", "target_word": "河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河有多长？", "target_word": "河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船在河上慢慢走。", "target_word": "河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，他们常在河里游泳。", "target_word": "河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥下有一条河。", "target_word": "河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河很宽，我们过不去。", "target_word": "河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，河里的冰化了。", "target_word": "河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在河里钓鱼。", "target_word": "河", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "小河", "label": "复合"}, {"form": "河流", "label": "复合"}], "register": "中性", "sense_fingerprint": "地上流动的天然水道，比小溪大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89628db-2a92-48c4-bb2a-aa8338e4bf66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24380, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "河", "is_correct": true, "explanation": "河：流动的天然水道，与句子的意思相符。"}, {"text": "喝", "is_correct": false, "explanation": "喝（hē）与河（hé）声调不同，意思是饮用。"}, {"text": "赫", "is_correct": false, "explanation": "赫（hè）与河（hé）声调不同，意思是显赫。"}, {"text": "呵", "is_correct": false, "explanation": "呵（hē）与河（hé）声调不同，意思是呵气。"}], "explanations": {"河": "河：流动的天然水道，与句子的意思相符。", "喝": "喝（hē）与河（hé）声调不同，意思是饮用。", "赫": "赫（hè）与河（hé）声调不同，意思是显赫。", "呵": "呵（hē）与河（hé）声调不同，意思是呵气。"}, "sentence_index": null, "correct_answer": "河"}, "level_3": {"options": [{"text": "河", "is_correct": true, "explanation": "河：流动的天然水道，与“一条”和“旁边”的语境相符。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：房子用量词“套”或“间”，不能用“条”。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：猫用量词“只”，不能用“条”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是高处的空间，不是可以用“一条”计量的东西。"}], "explanations": {"河": "河：流动的天然水道，与“一条”和“旁边”的语境相符。", "房子": "搭配：房子用量词“套”或“间”，不能用“条”。", "猫": "搭配：猫用量词“只”，不能用“条”。", "天空": "语义：天空是高处的空间，不是可以用“一条”计量的东西。"}, "sentence_index": 0, "correct_answer": "河"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家旁边有一只河。", "explanation": "这里应该用〈条〉。“只”多用于动物，河是长条形的水道，应该用“条”。"}, {"text": "这座城市有一座河。", "explanation": "这里应该用〈条〉。“座”用于山、桥等，河不能用“座”计量。"}, {"text": "桌子上放着一张河。", "explanation": "这里应该用〈条〉。“张”用于平面的东西，河不能用“张”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24380, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "河", "is_correct": true, "explanation": "河：流动的天然水道，与句子的意思相符。"}, {"text": "贺", "is_correct": false, "explanation": "贺（hè）与河（hé）声调不同，意思是祝贺。"}, {"text": "褐", "is_correct": false, "explanation": "褐（hè）与河（hé）声调不同，意思是粗布或褐色。"}, {"text": "德", "is_correct": false, "explanation": "德（dé）与河（hé）只差声母，声调相同，意思是道德。"}], "explanations": {"河": "河：流动的天然水道，与句子的意思相符。", "贺": "贺（hè）与河（hé）声调不同，意思是祝贺。", "褐": "褐（hè）与河（hé）声调不同，意思是粗布或褐色。", "德": "德（dé）与河（hé）只差声母，声调相同，意思是道德。"}, "sentence_index": null, "correct_answer": "河"}, "level_3": {"options": [{"text": "河", "is_correct": true, "explanation": "河：流动的天然水道，可以在桥下，与“有一条”的语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头要用量词“块”，不能用“条”。"}, {"text": "树", "is_correct": false, "explanation": "搭配：树要用量词“棵”，不能用“条”。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：夜晚是时间，不是可以用“一条”计量的地点。"}], "explanations": {"河": "河：流动的天然水道，可以在桥下，与“有一条”的语境相符。", "石头": "搭配：石头要用量词“块”，不能用“条”。", "树": "搭配：树要用量词“棵”，不能用“条”。", "夜晚": "语义：夜晚是时间，不是可以用“一条”计量的地点。"}, "sentence_index": 6, "correct_answer": "河"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的河很小，只能装一杯水。", "explanation": "这里应该用〈杯子〉。河是天然的大水道，不能用来装一杯水。"}, {"text": "这条河很可爱，我每天都抱着它睡觉。", "explanation": "这里应该用〈小狗〉。河是水道，不能当宠物抱着睡觉，应说“小狗”。"}, {"text": "河里放满了热水。", "explanation": "这里应该用〈浴缸〉。河是天然水道，不能像容器一样放满热水，应说“浴缸”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只河很长。", "corrected_sentence": "这条河很长。", "error_description": "量词错误：“河”应该用量词“条”，“只”多用于动物，不能用于河。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们过了一条很宽河。", "corrected_sentence": "我们过了一条很宽的河。", "error_description": "结构助词漏用：“很宽”修饰“河”，中间要用“的”，应说“很宽的河”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
