INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24382, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书就是用来读的，有很多页。", "primary_collocate": null, "pronunciation": "shū běn", "ipa": "ʂu pən", "syllable_count": 2, "sentences": [{"text": "书本很厚，有三百多页。", "target_word": "书本", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书本是用来读的，不是用来放着的。", "target_word": "书本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书本的第一页画着一只小猫。", "target_word": "书本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢翻开书本，闻那股纸张的味道。", "target_word": "书本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把书本翻到了第十页。", "target_word": "书本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书本掉在地上，页都弄皱了。", "target_word": "书本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌上的书本旁边放着一支笔。", "target_word": "书本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打开书本，一页一页地看。", "target_word": "书本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些书本太旧了，有的书页都掉了。", "target_word": "书本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家拿出书本，看第五页。", "target_word": "书本", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "書本", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用来阅读、有很多页的具体的书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3728d7ac-a5c9-42ec-9c46-36da5936aa49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书本", "is_correct": true, "explanation": "正确：“书本”指有很多页的书，与“很厚，有三百多页”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有页，“石头很厚，有三百多页”不成立。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服没有页，“衣服很厚，有三百多页”不成立。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机没有页码，“手机有三百多页”不符合常识。"}], "explanations": {"书本": "正确：“书本”指有很多页的书，与“很厚，有三百多页”相符。", "石头": "语义：石头没有页，“石头很厚，有三百多页”不成立。", "衣服": "语义：衣服没有页，“衣服很厚，有三百多页”不成立。", "手机": "语义：手机没有页码，“手机有三百多页”不符合常识。"}, "sentence_index": 0, "correct_answer": "书本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一张书本。", "explanation": "这里不能用〈张〉。〈张〉用于纸、桌子等平面的东西，书本应该用〈本〉或〈套〉。"}, {"text": "上课时，我把老师说的话都记在书本里。", "explanation": "这里应该用〈笔记本〉。“书本”指印好、供阅读的书，记笔记要用笔记本。"}, {"text": "书桌上放着一台书本。", "explanation": "这里不能用〈台〉。〈台〉用于机器等，书本应该用〈本〉或〈套〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书本", "is_correct": true, "explanation": "正确：“书本”指可以放在桌上的书，与“桌上……旁边放着一支笔”相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不会放在桌上，“桌上的太阳”不成立。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能放在桌上，与“桌上的”搭配不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“桌上”不能与天空搭配，“桌上的天空”说不通。"}], "explanations": {"书本": "正确：“书本”指可以放在桌上的书，与“桌上……旁边放着一支笔”相符。", "太阳": "语义：太阳不会放在桌上，“桌上的太阳”不成立。", "空气": "语义：空气不能放在桌上，与“桌上的”搭配不通。", "天空": "搭配：“桌上”不能与天空搭配，“桌上的天空”说不通。"}, "sentence_index": 6, "correct_answer": "书本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天买了一副书本。", "explanation": "这里不能用〈副〉。〈副〉用于眼镜、手套等成对的东西，书本应该用〈本〉或〈套〉。"}, {"text": "她每天都在书本上写日记。", "explanation": "这里应该用〈日记本〉。“书本”指印好、供阅读的书，写日记要用日记本。"}, {"text": "他的桌上摆着一颗书本。", "explanation": "这里不能用〈颗〉。〈颗〉用于粒状、圆形的小东西，书本应该用〈本〉或〈套〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟已经把书本看了完。", "corrected_sentence": "弟弟已经把书本看完了。", "error_description": "补语位置错误：结果补语“完”应紧跟动词，说“看完了”，不能说“看了完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些书本们都太旧了，该换了。", "corrected_sentence": "这些书本都太旧了，该换了。", "error_description": "“们”只加在指人的名词后，不能加在“书本”这类无生命的事物后表示复数，应去掉“们”，说“这些书本都太旧了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1071fff-adda-4667-bf15-73a50625d246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
