INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24384, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体随着音乐动来动去。", "primary_collocate": null, "pronunciation": "tiào wǔ", "ipa": "tʰiɑʊ̯⁵¹ u²¹⁴", "syllable_count": 2, "sentences": [{"text": "音乐一响，宝宝就跟着跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗听见音乐，开心地跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听着音乐，高兴地跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们围着桌子跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边唱歌一边跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客厅里放着音乐，我们一起跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不会跳舞，只会站着听。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿园的小朋友在教室里跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好听的歌，她忍不住跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在家里开着音乐跳舞。", "target_word": "跳舞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跳了舞", "label": "体标"}, {"form": "跳着舞", "label": "体标"}, {"form": "跳过舞", "label": "体标"}], "register": "口语", "sense_fingerprint": "动词：听着音乐，身体跟着动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '842fb074-b13a-42dd-9ece-3ecc7134eb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跳舞", "is_correct": true, "explanation": "正确：“跳舞”指身体随音乐动，与“音乐一响”和“跟着”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：音乐一响，人不会跟着睡觉，“跟着”要求随音乐做动作。"}, {"text": "静坐", "is_correct": false, "explanation": "语义：静坐是安静不动，与“跟着”随音乐而动的意思相反。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“跟着”要求随音乐做动作，音乐一响，宝宝不会跟着哭。"}], "explanations": {"跳舞": "正确：“跳舞”指身体随音乐动，与“音乐一响”和“跟着”相符。", "睡觉": "语义：音乐一响，人不会跟着睡觉，“跟着”要求随音乐做动作。", "静坐": "语义：静坐是安静不动，与“跟着”随音乐而动的意思相反。", "哭": "语义：“跟着”要求随音乐做动作，音乐一响，宝宝不会跟着哭。"}, "sentence_index": 0, "correct_answer": "跳舞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气跳舞了三十下。", "explanation": "这里应该用〈跳绳〉。跳绳按次数计，说“跳了三十下”；“跳舞”只指身体随音乐动，不按下数计。"}, {"text": "小明在沙坑里跳舞，跳了六米。", "explanation": "这里应该用〈跳远〉。跳远是按距离计成绩的比赛项目；跳舞没有距离，不能说跳了几米。"}, {"text": "他的心跳舞得很快。", "explanation": "这里应该用〈跳动〉。心脏的起伏说“跳动”，“跳舞”只指随音乐动，不能形容心脏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跳舞", "is_correct": true, "explanation": "正确：“不会跳舞，只会站着听”中，“跳舞”与“站着听”形成对比。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“不会洗澡”与常识不符，句子说的是跳舞这项技能。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“不会吃饭”与常识不符，句子说的是跳舞这项技能。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“不会睡觉”与常识不符，句子说的是跳舞这项技能。"}], "explanations": {"跳舞": "正确：“不会跳舞，只会站着听”中，“跳舞”与“站着听”形成对比。", "洗澡": "语义：“不会洗澡”与常识不符，句子说的是跳舞这项技能。", "吃饭": "语义：“不会吃饭”与常识不符，句子说的是跳舞这项技能。", "睡觉": "语义：“不会睡觉”与常识不符，句子说的是跳舞这项技能。"}, "sentence_index": 6, "correct_answer": "跳舞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他第一次从飞机上跳舞，很害怕。", "explanation": "这里应该用〈跳伞〉。跳伞是从飞机上跳下；“跳舞”只指随音乐动。"}, {"text": "她从跳台上跳舞，动作很漂亮。", "explanation": "这里应该用〈跳水〉。跳水是从跳台跳入水中的动作，“跳舞”不能这样用。"}, {"text": "他去年跳舞去了别的公司。", "explanation": "这里应该用〈跳槽〉。跳槽指换工作，“跳舞”只指随音乐动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天跳着三个小时舞。", "corrected_sentence": "我昨天跳了三个小时舞。", "error_description": "错误：说昨天已经完成的跳舞和持续的时间，“跳”后面要用“了”，不能用“着”，应说“跳了三个小时舞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一边唱一边跳舞着。", "corrected_sentence": "她一边唱一边跳着舞。", "error_description": "错误：“着”应放在“跳”后，即“跳着舞”，不能放在“舞”后面。“跳舞着”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24388, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "做错", "is_correct": true, "explanation": "正确答案。做错与做对意思相反，指做事没有做对。"}, {"text": "写字", "is_correct": false, "explanation": "写字与做对没有反义关系，不表示做事正确或错误。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫与做对没有反义关系，不表示做事正确或错误。"}, {"text": "画画", "is_correct": false, "explanation": "画画与做对没有反义关系，不表示做事正确或错误。"}], "correct_answer": "做错", "explanations": {"做错": "正确答案。做错与做对意思相反，指做事没有做对。", "写字": "写字与做对没有反义关系，不表示做事正确或错误。", "打扫": "打扫与做对没有反义关系，不表示做事正确或错误。", "画画": "画画与做对没有反义关系，不表示做事正确或错误。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24388, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "做错", "is_correct": true, "explanation": "正确答案。做错与做对意思相反，指做事出现错误。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭与做对没有反义关系，不表示做事正确或错误。"}, {"text": "散步", "is_correct": false, "explanation": "散步与做对没有反义关系，不表示做事正确或错误。"}, {"text": "洗澡", "is_correct": false, "explanation": "洗澡与做对没有反义关系，不表示做事正确或错误。"}], "correct_answer": "做错", "explanations": {"做错": "正确答案。做错与做对意思相反，指做事出现错误。", "吃饭": "吃饭与做对没有反义关系，不表示做事正确或错误。", "散步": "散步与做对没有反义关系，不表示做事正确或错误。", "洗澡": "洗澡与做对没有反义关系，不表示做事正确或错误。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24388, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做对了事情，就是没有做错。", "primary_collocate": null, "pronunciation": "zuò duì", "ipa": "tswo˥˩ twei˥˩", "syllable_count": 2, "sentences": [{"text": "他做对了这个练习，很高兴。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，我做对了八道题。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做对了，不用再改。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，做对事情的人不用怕。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太难，只有三个学生做对了。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我做对了作业，老师说我很好。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次做蛋糕就做对了。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做对了，我请你吃饭。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友把这道题做对了，老师很开心。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做对事不容易，要多想一想。", "target_word": "做对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做对了", "label": "体标"}, {"form": "做对过", "label": "体标"}], "register": "中性", "sense_fingerprint": "做事没有做错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71661477-2f15-4858-bb22-282f8f8aa695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24388, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做对", "is_correct": true, "explanation": "正确答案。做对了这个练习，表示做得正确，所以很高兴。"}, {"text": "做错", "is_correct": false, "explanation": "语义：做错了练习，与后半句很高兴的心情不合。"}, {"text": "做梦", "is_correct": false, "explanation": "语义：练习是用来做的，不能说做梦了这个练习。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱的对象一般是歌曲，不能说唱这个练习。"}], "explanations": {"做对": "正确答案。做对了这个练习，表示做得正确，所以很高兴。", "做错": "语义：做错了练习，与后半句很高兴的心情不合。", "做梦": "语义：练习是用来做的，不能说做梦了这个练习。", "唱": "搭配：唱的对象一般是歌曲，不能说唱这个练习。"}, "sentence_index": 0, "correct_answer": "做对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做对了事情的经过，大家都很佩服他。", "explanation": "这里应该用〈说对〉。事情的经过是叙述出来的，做对指做事没有做错，不能用于叙述正确与否。"}, {"text": "他在课上居然做对了一个哈欠。", "explanation": "这里应该用〈打〉。哈欠是打出来的，做对指做事没有做错，不能用于此。"}, {"text": "这场棋很难，他最后居然做对了一盘。", "explanation": "这里应该用〈赢〉。做对指做事没有做错，下棋赢了一盘要说赢，不能说做对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做对", "is_correct": true, "explanation": "正确答案。第一次做蛋糕就做对了，表示做得正确。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理是修复器物，与做蛋糕的动作不合。"}, {"text": "写", "is_correct": false, "explanation": "搭配：蛋糕不是写出来的，不能说做蛋糕就写了，句意不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译是转换语言，不能用于做蛋糕。"}], "explanations": {"做对": "正确答案。第一次做蛋糕就做对了，表示做得正确。", "修理": "语义：修理是修复器物，与做蛋糕的动作不合。", "写": "搭配：蛋糕不是写出来的，不能说做蛋糕就写了，句意不通。", "翻译": "语义：翻译是转换语言，不能用于做蛋糕。"}, "sentence_index": 6, "correct_answer": "做对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的胜负，他做对了。", "explanation": "这里应该用〈预测对〉。胜负是预测出来的，做对表示做事不出错，不用于预测。"}, {"text": "这个案子的真相，他做对了。", "explanation": "这里应该用〈推理对〉。真相是推理出来的，做对不能用于推理的结果。"}, {"text": "他把窗户做对了三次。", "explanation": "这里应该用〈擦〉。做对指做事没有做错，擦窗户要说擦，不能说做对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次作业，我做对着五道题。", "corrected_sentence": "这次作业，我做对了五道题。", "error_description": "做对表示一次完成的结果，不能与表示持续状态的着搭配，应把着改为了，说做对了五道题。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没做对了这道题。", "corrected_sentence": "我没做对这道题。", "error_description": "体标错误：否定已发生的结果用“没”，后面不能再加“了”，应说“没做对这道题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
