INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24390, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或棍子敲鼓，让鼓发出声音。", "primary_collocate": null, "pronunciation": "dǎ gǔ", "ipa": "ta˨˩˦ ku˨˩˦", "syllable_count": 2, "sentences": [{"text": "他用两根小棍子打鼓，声音很响。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台上有一个人在打鼓。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学打鼓，可是家里没有鼓。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，孩子们在屋里打鼓玩。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打鼓打得很好，大家都拍手。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么打鼓。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，村里人打鼓、唱歌。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个星期六都去音乐班打鼓。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗一听见有人打鼓，就跑过来了。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在晚上打鼓，宝宝已经睡了。", "target_word": "打鼓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打着鼓", "label": "体标"}, {"form": "打过鼓", "label": "体标"}], "register": "中性", "sense_fingerprint": "用手或棍子敲鼓发声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71661477-2f15-4858-bb22-282f8f8aa695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24390, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打鼓", "is_correct": true, "explanation": "正确答案。打鼓（dǎ gǔ）：用手或棍子敲鼓，使鼓发出声音。"}, {"text": "大鼓", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是一种鼓，也指一种说唱艺术。"}, {"text": "大股", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是数量很多的一股，如大股资金。"}, {"text": "大骨", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是较大的骨头，如大骨汤。"}], "explanations": {"打鼓": "正确答案。打鼓（dǎ gǔ）：用手或棍子敲鼓，使鼓发出声音。", "大鼓": "dà（第四声）与 dǎ（第三声）声调不同，意思是一种鼓，也指一种说唱艺术。", "大股": "dà（第四声）与 dǎ（第三声）声调不同，意思是数量很多的一股，如大股资金。", "大骨": "dà（第四声）与 dǎ（第三声）声调不同，意思是较大的骨头，如大骨汤。"}, "sentence_index": null, "correct_answer": "打鼓"}, "level_3": {"options": [{"text": "打鼓", "is_correct": true, "explanation": "正确答案。用两根小棍子敲鼓能发出响声。"}, {"text": "缝", "is_correct": false, "explanation": "语义：缝是用针线连接布料，与用小棍子发出响声的动作无关。"}, {"text": "翻", "is_correct": false, "explanation": "语义：翻是改变物体的位置或页面，不能用小棍子发出响声。"}, {"text": "削", "is_correct": false, "explanation": "搭配：削的对象是可以削的东西，不能说用两根小棍子削。"}], "explanations": {"打鼓": "正确答案。用两根小棍子敲鼓能发出响声。", "缝": "语义：缝是用针线连接布料，与用小棍子发出响声的动作无关。", "翻": "语义：翻是改变物体的位置或页面，不能用小棍子发出响声。", "削": "搭配：削的对象是可以削的东西，不能说用两根小棍子削。"}, "sentence_index": 0, "correct_answer": "打鼓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在饭店里专门打鼓，一天能端出二十盘菜。", "explanation": "这里应该用〈做菜〉。打鼓指敲鼓发声，做菜不能说打鼓。"}, {"text": "护士给他打鼓，他疼得哭了。", "explanation": "这里应该用〈打针〉。打鼓指敲鼓发声，给人注射要说打针，不能说打鼓。"}, {"text": "他去井边打鼓，把水桶装满了。", "explanation": "这里应该用〈打水〉。打鼓指敲鼓，从井里取水要说打水，不能说打鼓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打鼓", "is_correct": true, "explanation": "正确答案。过年时村里人敲鼓、唱歌，是节日里的活动。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理是修复器物，与过年的喜庆活动不相关。"}, {"text": "发抖", "is_correct": false, "explanation": "语义：发抖是身体因寒冷或害怕而颤动，不是过年时的活动，句意不通。"}, {"text": "写作业", "is_correct": false, "explanation": "搭配：写作业是学生的学习活动，不能与村里人过年的活动并列。"}], "explanations": {"打鼓": "正确答案。过年时村里人敲鼓、唱歌，是节日里的活动。", "修理": "语义：修理是修复器物，与过年的喜庆活动不相关。", "发抖": "语义：发抖是身体因寒冷或害怕而颤动，不是过年时的活动，句意不通。", "写作业": "搭配：写作业是学生的学习活动，不能与村里人过年的活动并列。"}, "sentence_index": 6, "correct_answer": "打鼓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他生气地走过去，对着弟弟的肩膀打鼓。", "explanation": "这里应该用〈拍〉。打鼓指敲鼓让鼓发声，用手轻击人身要说拍，不能说打鼓。"}, {"text": "他困得厉害，在课堂上一直打鼓。", "explanation": "这里应该用〈打哈欠〉。打鼓指敲鼓发声，困了张嘴出气要说打哈欠，不能说打鼓。"}, {"text": "他把论文拿到店里打鼓，一共打了三十份。", "explanation": "这里应该用〈打印〉。打鼓指敲鼓，把文件印出来要说打印，不能说打鼓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们下午在院子里打鼓了两个小时。", "corrected_sentence": "孩子们下午在院子里打鼓打了两个小时。", "error_description": "离合词：打鼓中“打”后要接“了”，应说「打鼓打了两个小时」，不能说「打鼓了两个小时」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放学以后，他常操场边打鼓。", "corrected_sentence": "放学以后，他常在操场边打鼓。", "error_description": "地点状语：地点前要加介词“在”，应说「在操场边打鼓」，不能说「操场边打鼓」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
