INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24398, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "开心，高兴。", "primary_collocate": null, "pronunciation": "kuài lè", "ipa": "kʰwaɪ˥˩ lɤ˥˩", "syllable_count": 2, "sentences": [{"text": "祝你生日快乐！", "target_word": "快乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们玩得很快乐。", "target_word": "快乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的笑声让大家都很快乐。", "target_word": "快乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和朋友在一起，我很快乐。", "target_word": "快乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他过着快乐的生活。", "target_word": "快乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望你每天都快乐。", "target_word": "快乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个快乐的周末。", "target_word": "快乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到你快乐，我也高兴。", "target_word": "快乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗快乐地跑来跑去。", "target_word": "快乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快乐不一定要有很多钱。", "target_word": "快乐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "快快乐乐", "label": "重叠"}, {"form": "快樂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "心里高兴，感到开心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89628db-2a92-48c4-bb2a-aa8338e4bf66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "快乐", "is_correct": true, "explanation": "快乐：心里高兴，与祝生日的语境相符。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：干净形容环境或物品整洁，不用来祝愿生日。"}, {"text": "红", "is_correct": false, "explanation": "语义：红是颜色，不能用来表示祝愿的心情。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：便宜形容价格低，不用来祝愿生日。"}], "explanations": {"快乐": "快乐：心里高兴，与祝生日的语境相符。", "干净": "搭配：干净形容环境或物品整洁，不用来祝愿生日。", "红": "语义：红是颜色，不能用来表示祝愿的心情。", "便宜": "搭配：便宜形容价格低，不用来祝愿生日。"}, "sentence_index": 0, "correct_answer": "快乐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很快乐帮你。", "explanation": "这里应该用〈高兴〉。“高兴”可以表示乐意做某事，“快乐”不能这样用。"}, {"text": "这个方案很快乐，大家都同意。", "explanation": "这里应该用〈有意思〉。快乐形容人的心情，不能用来形容计划或方案。"}, {"text": "我对这个结果很快乐。", "explanation": "这里应该用〈满意〉。对结果表示认可用“满意”，“快乐”指心情，不用来评价结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "快乐", "is_correct": true, "explanation": "快乐：心里高兴，修饰“周末”的语境可以成立。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：聪明形容人的智力，不能用来修饰周末。"}, {"text": "结实", "is_correct": false, "explanation": "语义：结实形容人或物牢固、强壮，不能用来修饰周末。"}, {"text": "圆滑", "is_correct": false, "explanation": "语义：圆滑形容待人处事灵活，不能用来修饰周末。"}], "explanations": {"快乐": "快乐：心里高兴，修饰“周末”的语境可以成立。", "聪明": "语义：聪明形容人的智力，不能用来修饰周末。", "结实": "语义：结实形容人或物牢固、强壮，不能用来修饰周末。", "圆滑": "语义：圆滑形容待人处事灵活，不能用来修饰周末。"}, "sentence_index": 6, "correct_answer": "快乐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很快乐，坐上去很舒服。", "explanation": "这里应该用〈舒服〉。快乐形容人的心情，不能用来形容椅子，应说“舒服”。"}, {"text": "他的才华很快乐，让人羡慕。", "explanation": "这里应该用〈出色〉。快乐形容人的心情，不能用来形容才华。"}, {"text": "这个假期的天气很快乐。", "explanation": "这里应该用〈晴朗〉。快乐形容人的心情，不能用来形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天很快乐了。", "corrected_sentence": "他今天很快乐。", "error_description": "“很＋快乐”作谓语描述状态时，句末不加“了”，应说“他今天很快乐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她快乐的唱着歌。", "corrected_sentence": "她快乐地唱着歌。", "error_description": "结构助词错误：修饰动词“唱”要用“地”，不能用“的”，应说“快乐地唱着歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
