INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24400, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小朋友就是年纪小的孩子。", "primary_collocate": null, "pronunciation": "xiǎo péng yǒu", "ipa": "ɕjɑʊ˨˩ pʰɤŋ˧˥ joʊ˨˩", "syllable_count": 3, "sentences": [{"text": "小朋友在教室里画画。", "target_word": "小朋友", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生对生病的小朋友很温和。", "target_word": "小朋友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我带小朋友去海边玩。", "target_word": "小朋友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店有小朋友吃的菜。", "target_word": "小朋友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友睡觉前喜欢听故事。", "target_word": "小朋友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着对小朋友说：“别哭了。”", "target_word": "小朋友", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的玩具都是给小朋友玩的。", "target_word": "小朋友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐的孩子是个很可爱的小朋友。", "target_word": "小朋友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友每天早上八点去上学。", "target_word": "小朋友", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公交车上，大家让座给带着小朋友的妈妈。", "target_word": "小朋友", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小朋友们", "label": "复数"}, {"form": "一个小朋友", "label": "量词"}, {"form": "一位小朋友", "label": "量词"}], "register": "中性", "sense_fingerprint": "年纪小的孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bc8be5-758a-4101-a27b-8c54507243b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24400, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小朋友", "is_correct": true, "explanation": "“小朋友”指年纪小的孩子，可以在教室里画画，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会画画，不可能在教室里画画，与语境矛盾。"}, {"text": "汽车", "is_correct": false, "explanation": "配价：“画画”需要有行为能力的施事，汽车不能充当这一角色。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能画画，与“在教室里画画”的语境不符。"}], "explanations": {"小朋友": "“小朋友”指年纪小的孩子，可以在教室里画画，符合句意。", "石头": "语义：石头不会画画，不可能在教室里画画，与语境矛盾。", "汽车": "配价：“画画”需要有行为能力的施事，汽车不能充当这一角色。", "冰箱": "语义：冰箱不能画画，与“在教室里画画”的语境不符。"}, "sentence_index": 0, "correct_answer": "小朋友"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位小朋友在银行工作了二十年，负责存款业务。", "explanation": "这里应该用〈柜员〉。小朋友指年纪小的孩子，不能指在银行工作二十年的柜员。"}, {"text": "小朋友每天要去图书馆查资料写论文。", "explanation": "这里应该用〈大学生〉。小朋友指年纪较小的孩子，不能指写论文的大学生。"}, {"text": "小朋友今年五十岁了，每周都主持公司会议。", "explanation": "这里应该用〈经理〉。小朋友指年纪小的孩子，不能指五十岁、主持会议的经理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小朋友", "is_correct": true, "explanation": "“小朋友”是能玩玩具的孩子，“商店里的玩具都是给小朋友玩的”符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会玩玩具，玩具不可能是给它玩的，与句意矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不会玩耍，句子说的是能玩玩具的人，与语境冲突。"}, {"text": "书包", "is_correct": false, "explanation": "配价：“玩”需要能玩耍的施事，书包不能充当这一角色。"}], "explanations": {"小朋友": "“小朋友”是能玩玩具的孩子，“商店里的玩具都是给小朋友玩的”符合语境。", "桌子": "语义：桌子不会玩玩具，玩具不可能是给它玩的，与句意矛盾。", "电脑": "语义：电脑不会玩耍，句子说的是能玩玩具的人，与语境冲突。", "书包": "配价：“玩”需要能玩耍的施事，书包不能充当这一角色。"}, "sentence_index": 6, "correct_answer": "小朋友"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公交车的小朋友每天很早就开车上班。", "explanation": "这里应该用〈司机〉。小朋友指年纪较小的孩子，不能指每天开公交车上班的司机。"}, {"text": "小朋友每天要给病人看病。", "explanation": "这里应该用〈医生〉。小朋友指年纪较小的孩子，不能指给病人看病的医生。"}, {"text": "小朋友每天带队员训练。", "explanation": "这里应该用〈教练〉。小朋友指年纪较小的孩子，不能指带队员训练的教练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三只小朋友在草地上跳绳。", "corrected_sentence": "三个小朋友在草地上跳绳。", "error_description": "量词错误：“小朋友”指人，应用量词“个”或“位”，不能用“只”。错误形式是“三只小朋友”，正确形式是“三个小朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个小朋友们在操场上踢球。", "corrected_sentence": "两个小朋友在操场上踢球。", "error_description": "词尾错误：“们”表示复数，不能与数词“两个”同时使用。错误形式是“两个小朋友们”，正确形式是“两个小朋友”，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
