INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24404, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24404, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "让人开心的事情或活动。", "primary_collocate": null, "pronunciation": "yú lè", "ipa": "y˧˥ lɤ˥˩", "syllable_count": 2, "sentences": [{"text": "打游戏是很多年轻人的娱乐。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一家人在一起玩牌，也是一种娱乐。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小镇很小，晚上没有娱乐。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸工作以后，唯一的娱乐是钓鱼。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视是奶奶每天的主要娱乐。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在山上没有网，我们自己找娱乐。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书很有意思，是我旅行时的娱乐。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生也要有自己的娱乐时间。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下班后，同事们常常一起找点娱乐。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子最需要的娱乐是和朋友玩。", "target_word": "娱乐", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "娱乐活动", "label": "复合词"}, {"form": "娱乐圈", "label": "复合词"}, {"form": "娱乐节目", "label": "复合词"}], "register": "中性", "sense_fingerprint": "让人开心的事情或活动，日常消遣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45914aa1-3807-4f84-b9f5-40c8d21dc009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "娱乐", "is_correct": true, "explanation": "“娱乐”指让人开心的事情或活动，“打游戏是很多年轻人的……”指的正是这类活动。"}, {"text": "考试", "is_correct": false, "explanation": "语义：打游戏不是考试，“很多年轻人的考试”句意不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：打游戏是消遣，不是需要完成的作业，句意相反。"}, {"text": "病症", "is_correct": false, "explanation": "语域：“病症”是医学书面用语，与口语化的日常描述不合，也与“打游戏”的语境不符。"}], "explanations": {"娱乐": "“娱乐”指让人开心的事情或活动，“打游戏是很多年轻人的……”指的正是这类活动。", "考试": "语义：打游戏不是考试，“很多年轻人的考试”句意不通。", "作业": "语义：打游戏是消遣，不是需要完成的作业，句意相反。", "病症": "语域：“病症”是医学书面用语，与口语化的日常描述不合，也与“打游戏”的语境不符。"}, "sentence_index": 0, "correct_answer": "娱乐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春节是中国人最重要的娱乐。", "explanation": "这里应该用〈节日〉。“娱乐”指让人开心的活动，不指一个固定的日子。"}, {"text": "我把娱乐装进了行李箱。", "explanation": "这里误把“娱乐”当成〈实物〉来用。“娱乐”指让人快乐放松的活动，是抽象的，不能像物品一样装进行李箱。"}, {"text": "我们常常娱乐电视，觉得很放松。", "explanation": "这里误把“娱乐”当成〈观看〉的意思来用。作动词时“娱乐”是使人快乐，其对象应是人，不能说“娱乐电视”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "娱乐", "is_correct": true, "explanation": "“娱乐”指旅行时用来消遣的让人开心的事，与“这本书很有意思”相符。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是旅行时带的物品，不是让人开心的消遣，句意不通。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：“旅行时的”后接可以消遣的东西，“地图”是指路工具，不能说“是我旅行时的地图”来表示消遣。"}, {"text": "药品", "is_correct": false, "explanation": "语义：“药品”与“很有意思”的评价矛盾，句意不通。"}], "explanations": {"娱乐": "“娱乐”指旅行时用来消遣的让人开心的事，与“这本书很有意思”相符。", "行李": "语义：行李是旅行时带的物品，不是让人开心的消遣，句意不通。", "地图": "搭配：“旅行时的”后接可以消遣的东西，“地图”是指路工具，不能说“是我旅行时的地图”来表示消遣。", "药品": "语义：“药品”与“很有意思”的评价矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "娱乐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶每天都娱乐花草，花草长得很好。", "explanation": "这里应该用〈照顾〉。作动词“娱乐”指使人快乐，不能用于花草。"}, {"text": "钓鱼是爸爸最喜欢的一只娱乐。", "explanation": "这里应该用〈种〉。“只”用于动物，“娱乐”要用“种”或“项”来计量。"}, {"text": "他把这份娱乐搬进了厨房。", "explanation": "这里误把“娱乐”当成〈实物〉来用。“娱乐”指让人快乐放松的活动，是抽象的，不能像物品一样搬进厨房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他工作以后，唯一的一块娱乐是下棋。", "corrected_sentence": "他工作以后，唯一的一种娱乐是下棋。", "error_description": "错误：量词“块”用于块状的物体，不能修饰抽象的“娱乐”。正确：“一种”，“娱乐”常用“种”或“项”来计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在假期找到了一把好玩的娱乐。", "corrected_sentence": "他在假期找到了一种好玩的娱乐。", "error_description": "错误：量词“把”用于有柄的东西，不能修饰“娱乐”。正确：“一种”，“娱乐”常用“种”或“项”来计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
