INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24406, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "道理就是事情为什么是这样的原因。", "primary_collocate": null, "pronunciation": "dào lǐ", "ipa": "tau˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想知道其中的道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师解释了月亮变圆缺的道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师慢慢讲了下雨的道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这样做一定有他的道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有告诉我这样做的道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说说其中的道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么晚上会冷？这有科学道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我讲了冬天为什么会下雪的道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟问我星星发光的道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们弄明白植物生长的道理。", "target_word": "道理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大道理", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情之所以如此的原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45914aa1-3807-4f84-b9f5-40c8d21dc009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道理", "is_correct": true, "explanation": "正确：指事情为什么如此的原因，与“想知道”相合。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”指性情，“知道其中的脾气”搭配不当。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”是实物，与“事情为什么如此”的原因不合。"}, {"text": "相貌", "is_correct": false, "explanation": "体貌：“相貌”指外貌，不能作为“想知道”的内容。"}], "explanations": {"道理": "正确：指事情为什么如此的原因，与“想知道”相合。", "脾气": "搭配：“脾气”指性情，“知道其中的脾气”搭配不当。", "鞋子": "语义：“鞋子”是实物，与“事情为什么如此”的原因不合。", "相貌": "体貌：“相貌”指外貌，不能作为“想知道”的内容。"}, "sentence_index": 0, "correct_answer": "道理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们沿着这条道理走了很久。", "explanation": "这里应该用〈道路〉。道理指事情为什么如此的原因，不能用来走。"}, {"text": "演员手里拿着一个道理当道具。", "explanation": "这里指舞台表演时用的实物。道理是抽象的原因，不能充当演员手里拿的东西。"}, {"text": "这个道理在山上修行多年。", "explanation": "这里应该用〈道士〉。道理不是人，不能修行，修行的人要用〈道士〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道理", "is_correct": true, "explanation": "正确：指解释晚上为什么会冷的科学原因。"}, {"text": "感情", "is_correct": false, "explanation": "语义：“感情”是情感，与“科学”所指的道理不合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指体型，不能与“科学”搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“科学”不能修饰“颜色”，“科学颜色”不成词组。"}], "explanations": {"道理": "正确：指解释晚上为什么会冷的科学原因。", "感情": "语义：“感情”是情感，与“科学”所指的道理不合。", "身材": "体貌：“身材”指体型，不能与“科学”搭配。", "颜色": "搭配：“科学”不能修饰“颜色”，“科学颜色”不成词组。"}, "sentence_index": 6, "correct_answer": "道理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师讲了一块道理。", "explanation": "这里应该用〈个〉。〈块〉用于块状的物体，道理应用〈个〉。"}, {"text": "他说了一张道理。", "explanation": "这里应该用〈个〉。〈张〉用于纸张、桌子等平面物，不用于道理。"}, {"text": "她写了一首道理。", "explanation": "这里应该用〈个〉。〈首〉用于诗歌、歌曲，道理应用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我终于明白着这个道理。", "corrected_sentence": "我终于明白了这个道理。", "error_description": "错误：“明白”后应用“了”表示完成，此处误用“着”。应为“明白了这个道理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他解释了雨水形成道理。", "corrected_sentence": "他解释了雨水形成的道理。", "error_description": "错误：“雨水形成”修饰“道理”时需要“的”作定语，此处缺“的”。应为“雨水形成的道理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ee657c-c3b9-4110-b3eb-6b07c64fb57f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
