INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24422, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个人出生和长大的地方，比如你住的那个村子或城市。", "primary_collocate": null, "pronunciation": "jiā xiāng", "ipa": "tɕja˥ ɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "我在一个小村子出生，那里就是我的家乡。", "target_word": "家乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京不是我的家乡，我是在上海长大的。", "target_word": "家乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的家乡是哪个城市？", "target_word": "家乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家乡离这儿很远，要坐两天火车。", "target_word": "家乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在家乡长大，上了小学和中学。", "target_word": "家乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业后，她回到家乡当老师。", "target_word": "家乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的家乡是一个有河的小城。", "target_word": "家乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常给家乡的朋友打电话。", "target_word": "家乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家乡的人都很热情。", "target_word": "家乡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想带你去看看我的家乡。", "target_word": "家乡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家乡话", "label": "复合"}, {"form": "家乡菜", "label": "复合"}, {"form": "家鄉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己出生和长大的村子或城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b159a33e-0896-4081-a4f7-985fcc4402be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24422, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "家乡", "is_correct": true, "explanation": "正确答案。家乡（jiāxiāng）指自己出生和长大的村子或城市。"}, {"text": "假象", "is_correct": false, "explanation": "jiǎxiàng 与 jiāxiāng 两个音节声调都不同，意思是表面上的假象。"}, {"text": "假想", "is_correct": false, "explanation": "jiǎxiǎng 两个音节都是第三声，与 jiāxiāng 只有声调不同，意思是假设、想象。"}, {"text": "家兄", "is_correct": false, "explanation": "xiōng 与 xiāng 声调相同，只是韵母不同（iong 与 iang）；家兄是对自己哥哥的谦称。"}], "explanations": {"家乡": "正确答案。家乡（jiāxiāng）指自己出生和长大的村子或城市。", "假象": "jiǎxiàng 与 jiāxiāng 两个音节声调都不同，意思是表面上的假象。", "假想": "jiǎxiǎng 两个音节都是第三声，与 jiāxiāng 只有声调不同，意思是假设、想象。", "家兄": "xiōng 与 xiāng 声调相同，只是韵母不同（iong 与 iang）；家兄是对自己哥哥的谦称。"}, "sentence_index": null, "correct_answer": "家乡"}, "level_3": {"options": [{"text": "家乡", "is_correct": true, "explanation": "正确：家乡指出生长大的地方，“那里就是我的家乡”语义相合。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“那里就是我的作业”说不通，“作业”不能指地方。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，不能用来指“那里”这个地方。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是通讯工具，不能指“那里”，句子不成立。"}], "explanations": {"家乡": "正确：家乡指出生长大的地方，“那里就是我的家乡”语义相合。", "作业": "语义：“那里就是我的作业”说不通，“作业”不能指地方。", "身高": "体貌：“身高”指身体的高矮，不能用来指“那里”这个地方。", "手机": "语义：“手机”是通讯工具，不能指“那里”，句子不成立。"}, "sentence_index": 0, "correct_answer": "家乡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把书放进家乡。", "explanation": "这里应该用〈书包〉。家乡指出生或长大的地方，不能用来装东西。"}, {"text": "我坐在家乡上看书。", "explanation": "这里应该用〈椅子〉。“坐在……上”需要有实际的物体，家乡不能用来坐。"}, {"text": "我把钥匙借给了家乡。", "explanation": "这里应该用〈朋友〉。“借给”的对象是人，家乡是地方，不能把东西借给它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家乡", "is_correct": true, "explanation": "正确：家乡指出生长大的地方，与“一个有河的小城”同指一处。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：“脸”是身体部位，不能说它是一个小城。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是情绪，不能是一座城市，句子说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气候状况，不能是一座城市。"}], "explanations": {"家乡": "正确：家乡指出生长大的地方，与“一个有河的小城”同指一处。", "脸": "体貌：“脸”是身体部位，不能说它是一个小城。", "心情": "语义：“心情”是情绪，不能是一座城市，句子说不通。", "天气": "语义：“天气”是气候状况，不能是一座城市。"}, "sentence_index": 6, "correct_answer": "家乡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用家乡喝水。", "explanation": "这里应该用〈杯子〉。家乡是地方，不能作为喝水的工具。"}, {"text": "我每天晚上做家乡。", "explanation": "这里应该用〈作业〉。“做”的对象可以是作业、饭菜，家乡是地方，不能这样用。"}, {"text": "我昨天吃了家乡。", "explanation": "这里应该用〈饭〉。“吃”的对象是食物，家乡是地方，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一条很特别的家乡。", "corrected_sentence": "我有一个很特别的家乡。", "error_description": "错误：“一条”；正确：“一个”。“家乡”是地方，量词用“个”，“条”用于河流、道路等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想回了家乡看看。", "corrected_sentence": "我想回家乡看看。", "error_description": "错误：“想回了家乡”；正确：“想回家乡”。“想”表示打算，后面的动作还没有完成，不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
