INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24424, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "问一个问题。", "primary_collocate": null, "pronunciation": "tí wèn", "ipa": "tʰi˧˥ wən˥˩", "syllable_count": 2, "sentences": [{"text": "老师提问了一个学生，他答对了。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课时，老师常常提问同学。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举起手，想向老师提问。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师提问：“谁知道这个字怎么读？”", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试时，经理向我提问，我有点紧张。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站起来向校长提问。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有提问我，我很高兴。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课前，老师让学生互相提问。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不敢提问，怕同学笑他。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里的记者正在向客人提问。", "target_word": "提问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提问了", "label": "体标"}, {"form": "提问过", "label": "体标"}], "register": "中性", "sense_fingerprint": "向某人问出一个具体的问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e58837-c3d8-404d-95dd-38296864162d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提问", "is_correct": true, "explanation": "正确。“老师提问了一个学生，他答对了”中，“提问”表示老师问学生问题。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”表示让人离开或赠送，与“他答对了”没有关联，无法说明学生的回答。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象通常是动物或婴儿，不能说“喂一个学生”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物品或身体，不能用于“一个学生”。"}], "explanations": {"提问": "正确。“老师提问了一个学生，他答对了”中，“提问”表示老师问学生问题。", "送": "语义：“送”表示让人离开或赠送，与“他答对了”没有关联，无法说明学生的回答。", "喂": "搭配：“喂”的对象通常是动物或婴儿，不能说“喂一个学生”。", "洗": "搭配：“洗”的对象是物品或身体，不能用于“一个学生”。"}, "sentence_index": 0, "correct_answer": "提问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在杂志上提问了一篇文章。", "explanation": "这里应该用〈发表〉。提问指提出问题，文章要说“发表”。"}, {"text": "爸爸提问了家里的电视。", "explanation": "这里应该用〈修理〉。提问不能用于东西，修理电视要说“修理”。"}, {"text": "他在会上提问了三个建议。", "explanation": "这里应该用〈提出〉。提问只用于提出疑问，建议要说“提出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提问", "is_correct": true, "explanation": "正确。“老师没有提问我，我很高兴”中，“提问”指老师没有向我提出问题。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”的对象是地方或物品，不能说“打扫我”。"}, {"text": "种", "is_correct": false, "explanation": "配价：“种”的对象是植物，不能说“种我”。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”不能直接带人作宾语，要说“和某人结婚”。"}], "explanations": {"提问": "正确。“老师没有提问我，我很高兴”中，“提问”指老师没有向我提出问题。", "打扫": "配价：“打扫”的对象是地方或物品，不能说“打扫我”。", "种": "配价：“种”的对象是植物，不能说“种我”。", "结婚": "配价：“结婚”不能直接带人作宾语，要说“和某人结婚”。"}, "sentence_index": 6, "correct_answer": "提问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府提问了一部新法律。", "explanation": "这里应该用〈颁布〉。提问不能用于法律，颁布法律要说“颁布”。"}, {"text": "老师提问了这本好书。", "explanation": "这里应该用〈推荐〉。提问不能用于书籍，推荐好书要说“推荐”。"}, {"text": "公司提问了一台新机器。", "explanation": "这里应该用〈制造〉。提问指问一个问题，制造机器要说“制造”，机器不能作提问的宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天上课时，老师没提问了我。", "corrected_sentence": "昨天上课时，老师没提问我。", "error_description": "体标错误：“没”否定已发生的动作时，动词“提问”后面不能再加“了”，应说“没提问我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下课后，同学老师提问。", "corrected_sentence": "下课后，同学向老师提问。", "error_description": "漏掉介词“向”：“老师”是提问的对象，应说“同学向老师提问”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
