INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24430, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个可以看动画片和新闻的方盒子。", "primary_collocate": null, "pronunciation": "diàn shì", "ipa": "tjɛn˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "晚上我们一家人在客厅看电视。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客厅里有一台新电视。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸正在看电视上的新闻。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢看电视里的动画片。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把电视的声音关小一点。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视坏了，今天不能看足球比赛。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天晚上都开着电视睡觉。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的电视是去年买的。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少看电视，常常看书。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在说明天的天气。", "target_word": "电视", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一台电视", "label": "量词"}, {"form": "电视机", "label": "复合"}, {"form": "电视台", "label": "复合"}, {"form": "電視", "label": "繁体"}], "register": "中性", "sense_fingerprint": "家里用来看节目、新闻和动画片的电器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '893d22fe-4f1c-4df4-bc7b-16eb250f9a8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24430, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电视", "is_correct": true, "explanation": "正确答案：电视（diàn shì），指家里用来看节目、新闻和动画片的电器。"}, {"text": "面试", "is_correct": false, "explanation": "miàn 与 diàn 声母不同（m 对 d），意思是求职或入学时的考核，不是电器。"}, {"text": "电石", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是一种化工原料。"}, {"text": "但是", "is_correct": false, "explanation": "dàn 与 diàn 韵母不同（缺少 i），意思是连词“但是”。"}], "explanations": {"电视": "正确答案：电视（diàn shì），指家里用来看节目、新闻和动画片的电器。", "面试": "miàn 与 diàn 声母不同（m 对 d），意思是求职或入学时的考核，不是电器。", "电石": "shí（第二声）与 shì（第四声）声调不同，意思是一种化工原料。", "但是": "dàn 与 diàn 韵母不同（缺少 i），意思是连词“但是”。"}, "sentence_index": null, "correct_answer": "电视"}, "level_3": {"options": [{"text": "电视", "is_correct": true, "explanation": "正确：电视是客厅里可以“看”的电器，与“看”和晚上一家人在客厅的场景相合。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里的东西，客厅里没有，也不能用来看节目。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：句中是晚上，看不到太阳，客厅也不是看太阳的地方。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“看”一般不接“冰箱”，冰箱是用来存放食物的。"}], "explanations": {"电视": "正确：电视是客厅里可以“看”的电器，与“看”和晚上一家人在客厅的场景相合。", "黑板": "语义：黑板是教室里的东西，客厅里没有，也不能用来看节目。", "太阳": "语义：句中是晚上，看不到太阳，客厅也不是看太阳的地方。", "冰箱": "搭配：“看”一般不接“冰箱”，冰箱是用来存放食物的。"}, "sentence_index": 0, "correct_answer": "电视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在电影院看电视。", "explanation": "这里应该用〈电影〉。电视是家里的电器，在电影院看的是电影，不说“在电影院看电视”。"}, {"text": "妈妈用电视给我发信息。", "explanation": "这里应该用〈手机〉。电视不能用来发信息，发信息要用手机。"}, {"text": "我用电视热饭。", "explanation": "这里应该用〈微波炉〉。电视是看节目的电器，不能用来加热食物，热饭要用微波炉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24430, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "电视", "is_correct": true, "explanation": "正确答案：电视（diàn shì），指家里用来看节目的电器。"}, {"text": "变式", "is_correct": false, "explanation": "biàn 与 diàn 声母不同（b 对 d），意思是变化后的形式。"}, {"text": "面世", "is_correct": false, "explanation": "miàn 与 diàn 声母不同（m 对 d），意思是作品等首次与公众见面。"}, {"text": "现世", "is_correct": false, "explanation": "xiàn 与 diàn 声母不同（x 对 d），意思是现在这个世界。"}], "explanations": {"电视": "正确答案：电视（diàn shì），指家里用来看节目的电器。", "变式": "biàn 与 diàn 声母不同（b 对 d），意思是变化后的形式。", "面世": "miàn 与 diàn 声母不同（m 对 d），意思是作品等首次与公众见面。", "现世": "xiàn 与 diàn 声母不同（x 对 d），意思是现在这个世界。"}, "sentence_index": null, "correct_answer": "电视"}, "level_3": {"options": [{"text": "电视", "is_correct": true, "explanation": "正确：电视是可以“开着”的电器，与“开着……睡觉”相合。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，不能“开着”用来睡觉，奶奶也不会在地铁里睡觉。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂不是家里能开着用的东西，不能“开着工厂睡觉”。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“开”一般不接“报纸”，报纸是用来看的，不说“开报纸”。"}], "explanations": {"电视": "正确：电视是可以“开着”的电器，与“开着……睡觉”相合。", "地铁": "语义：地铁是交通工具，不能“开着”用来睡觉，奶奶也不会在地铁里睡觉。", "工厂": "语义：工厂不是家里能开着用的东西，不能“开着工厂睡觉”。", "报纸": "搭配：“开”一般不接“报纸”，报纸是用来看的，不说“开报纸”。"}, "sentence_index": 6, "correct_answer": "电视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天把牛奶放进电视里。", "explanation": "这里应该用〈冰箱〉。电视是看节目的电器，不能用来放牛奶，放牛奶要用冰箱。"}, {"text": "我每天用电视洗衣服。", "explanation": "这里应该用〈洗衣机〉。电视不能用来洗衣服，洗衣服要用洗衣机。"}, {"text": "他在电视上写作业。", "explanation": "这里应该用〈电脑〉。电视不能用来写作业，写作业要用电脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书房里有一只旧电视。", "corrected_sentence": "书房里有一台旧电视。", "error_description": "“电视”的量词应为“台”，不能说“一只电视”，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家有两张电视。", "corrected_sentence": "我家有两台电视。", "error_description": "错误：“两张电视”。正确：“两台电视”。“电视”的量词是“台”，“张”多用于纸、桌子等平面的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24432, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "很少", "is_correct": true, "explanation": "“很少”与“很多”相对，是“不少”（数量大）的反义词。"}, {"text": "干净", "is_correct": false, "explanation": "与“不少”在任何义项上都没有反义或近义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“不少”在任何义项上都没有反义或近义关系。"}, {"text": "柔和", "is_correct": false, "explanation": "与“不少”在任何义项上都没有反义或近义关系。"}], "correct_answer": "很少", "explanations": {"很少": "“很少”与“很多”相对，是“不少”（数量大）的反义词。", "干净": "与“不少”在任何义项上都没有反义或近义关系。", "陡峭": "与“不少”在任何义项上都没有反义或近义关系。", "柔和": "与“不少”在任何义项上都没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24432, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "很少", "is_correct": true, "explanation": "“很少”与“很多”相对，是“不少”（数量大）的反义词。"}, {"text": "潮湿", "is_correct": false, "explanation": "与“不少”在任何义项上都没有反义或近义关系。"}, {"text": "急躁", "is_correct": false, "explanation": "与“不少”在任何义项上都没有反义或近义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "与“不少”在任何义项上都没有反义或近义关系。"}], "correct_answer": "很少", "explanations": {"很少": "“很少”与“很多”相对，是“不少”（数量大）的反义词。", "潮湿": "与“不少”在任何义项上都没有反义或近义关系。", "急躁": "与“不少”在任何义项上都没有反义或近义关系。", "辽阔": "与“不少”在任何义项上都没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24432, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很多，表示数量大。", "primary_collocate": null, "pronunciation": "bù shǎo", "ipa": "pu˥˩ ʂɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "教室里来了不少人。", "target_word": "不少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家有不少书。", "target_word": "不少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次旅行我花了不少钱。", "target_word": "不少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年夏天下了不少雨。", "target_word": "不少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市里有不少公园。", "target_word": "不少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她在中国交了不少朋友。", "target_word": "不少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路上的车不少。", "target_word": "不少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我今天买了不少水果。", "target_word": "不少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们留了不少作业。", "target_word": "不少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里的人不少，我们排了很久的队。", "target_word": "不少", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不少", "label": "原形"}], "register": "中性", "sense_fingerprint": "数量不小，相当多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22aa5821-43c2-4f1a-bd68-eccc7ce09b8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不少", "is_correct": true, "explanation": "“不少”表示数量多，可以修饰“人”，与“来了……人”相合。"}, {"text": "巨大", "is_correct": false, "explanation": "搭配：“巨大”形容体积或规模，不能修饰“人”来表示人数。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线，与来了多少人无关。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，不能用来说明人数的多少。"}], "explanations": {"不少": "“不少”表示数量多，可以修饰“人”，与“来了……人”相合。", "巨大": "搭配：“巨大”形容体积或规模，不能修饰“人”来表示人数。", "明亮": "语义：“明亮”形容光线，与来了多少人无关。", "柔软": "语义：“柔软”形容质地，不能用来说明人数的多少。"}, "sentence_index": 0, "correct_answer": "不少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里的物价不少，大家都觉得有点担心。", "explanation": "这里应该用〈高〉。“不少”只表示数量多，不能用来说物价的高低。"}, {"text": "他的个子不少，所以在篮球队很出名。", "explanation": "这里应该用〈高〉。“不少”只表示数量多，不能用来形容个子高矮，说个子高要用“高”。"}, {"text": "我的心情不少，所以今天特别开心。", "explanation": "这里应该用〈好〉。“不少”只表示数量多，心情是状态，不能用“不少”来描述，应说“心情很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不少", "is_correct": true, "explanation": "“不少”表示数量多，与“这条路上的车”相合。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来形容车。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”的主语须是能有情绪的人，车不能高兴。"}, {"text": "清醒", "is_correct": false, "explanation": "语义：“清醒”指人的意识状态，不能用于车。"}], "explanations": {"不少": "“不少”表示数量多，与“这条路上的车”相合。", "聪明": "语义：“聪明”形容人的智力，不能用来形容车。", "高兴": "搭配：“高兴”的主语须是能有情绪的人，车不能高兴。", "清醒": "语义：“清醒”指人的意识状态，不能用于车。"}, "sentence_index": 6, "correct_answer": "不少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子不少，坐上去很舒服。", "explanation": "这里应该用〈大〉。“不少”表示数量多，只用于多个事物，一把椅子不能说“不少”，说椅子的大小要用“大”。"}, {"text": "这台电脑不少，我每天都在用。", "explanation": "这里应该用〈好用〉。“不少”表示数量多，单独一台电脑要评价好坏，应说“好用”，不能用“不少”。"}, {"text": "这座房子不少，我们都很喜欢它。", "explanation": "这里应该用〈漂亮〉。“不少”表示数量多，只用于多个事物，单独一座房子要说它好看，应用“漂亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她花了很不少时间准备考试。", "corrected_sentence": "她花了不少时间准备考试。", "error_description": "错误：“不少”本身已表示数量多，前面不能再加程度副词“很”。正确说法是“花了不少时间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家商场里买东西的人太不少。", "corrected_sentence": "这家商场里买东西的人不少。", "error_description": "错误：“不少”前面不能加程度副词“太”。正确：“人不少”，直接用“不少”作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
