INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24436, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "屏幕是电视或电脑上显示画面的地方。", "primary_collocate": null, "pronunciation": "píng mù", "ipa": "pʰiŋ˧˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "电视屏幕很大，全家都能看清楚。", "target_word": "屏幕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的电脑屏幕上有很多图标。", "target_word": "屏幕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视屏幕突然黑了。", "target_word": "屏幕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要用手摸电视屏幕。", "target_word": "屏幕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他坐在电脑前，盯着屏幕看。", "target_word": "屏幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上的画面很清楚。", "target_word": "屏幕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我把电脑屏幕擦干净了。", "target_word": "屏幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议室的屏幕上放着今天的计划。", "target_word": "屏幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了一天屏幕，我的眼睛很累。", "target_word": "屏幕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电视的屏幕比我家的大。", "target_word": "屏幕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "电视屏幕", "label": "复合"}, {"form": "电脑屏幕", "label": "复合"}], "register": "中性", "sense_fingerprint": "电视、电脑上显示画面的那一块区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e58837-c3d8-404d-95dd-38296864162d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屏幕", "is_correct": true, "explanation": "“电视屏幕”是能被看清楚的部件，与“很大”相符。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看清楚”的对象是画面，不说“声音”，“全家都能看清楚”不通。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发不是显示部件，与“全家都能看清楚”不符。"}, {"text": "遥控器", "is_correct": false, "explanation": "语义：遥控器是按键，不是看的对象，与“看清楚”不符。"}], "explanations": {"屏幕": "“电视屏幕”是能被看清楚的部件，与“很大”相符。", "声音": "搭配：“看清楚”的对象是画面，不说“声音”，“全家都能看清楚”不通。", "沙发": "语义：沙发不是显示部件，与“全家都能看清楚”不符。", "遥控器": "语义：遥控器是按键，不是看的对象，与“看清楚”不符。"}, "sentence_index": 0, "correct_answer": "屏幕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈打开屏幕，让风吹进来。", "explanation": "这里应该用〈窗户〉。屏幕是显示画面的部件，不能开关来通风。"}, {"text": "他推开屏幕走了进去。", "explanation": "这里应该用〈门〉。屏幕不能推开让人进出，进出要用门。"}, {"text": "他拉开屏幕，拿出了钥匙。", "explanation": "这里应该用〈抽屉〉。屏幕不能拉开取物，取物要用抽屉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屏幕", "is_correct": true, "explanation": "“电脑屏幕”是有形的物体，可以擦干净。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“擦”的对象是有形的物体，“擦空气”搭配不当。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏是软件，不能用布擦，与“擦干净”不符。"}, {"text": "问题", "is_correct": false, "explanation": "语义：“问题”是抽象的，不能擦，与“擦干净”不符。"}], "explanations": {"屏幕": "“电脑屏幕”是有形的物体，可以擦干净。", "空气": "搭配：“擦”的对象是有形的物体，“擦空气”搭配不当。", "游戏": "语义：游戏是软件，不能用布擦，与“擦干净”不符。", "问题": "语义：“问题”是抽象的，不能擦，与“擦干净”不符。"}, "sentence_index": 6, "correct_answer": "屏幕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的电视屏幕很咸。", "explanation": "这里应该用〈汤〉。〈咸〉形容食物味道，屏幕是显示画面的部件，不能用咸来形容。"}, {"text": "我家的电视屏幕会唱歌。", "explanation": "这里应该用〈音箱〉。屏幕只显示画面，不会唱歌，会唱歌的应是音箱。"}, {"text": "他每天用屏幕刷牙。", "explanation": "这里应该用〈牙刷〉。〈刷〉搭配牙刷、碗等，屏幕不能用来刷牙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的电脑屏幕慢慢暗进去了。", "corrected_sentence": "我的电脑屏幕慢慢暗下来了。", "error_description": "补语错误：屏幕由亮变暗，应说“暗下来”，不说“暗进去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块很亮屏幕是新买的。", "corrected_sentence": "这块很亮的屏幕是新买的。", "error_description": "结构助词错误：“很亮”修饰“屏幕”，中间要加“的”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24438, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出", "is_correct": true, "explanation": "出是“进”的反义词，指从里面走到外面，与“进门”相对。"}, {"text": "跑", "is_correct": false, "explanation": "跑是快速移动的动作，与“进”没有相反关系。"}, {"text": "坐", "is_correct": false, "explanation": "坐是身体落在座位上的动作，与“进”没有相反关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑是面部表情，与“进”没有相反关系。"}], "correct_answer": "出", "explanations": {"出": "出是“进”的反义词，指从里面走到外面，与“进门”相对。", "跑": "跑是快速移动的动作，与“进”没有相反关系。", "坐": "坐是身体落在座位上的动作，与“进”没有相反关系。", "笑": "笑是面部表情，与“进”没有相反关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24438, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出", "is_correct": true, "explanation": "出是“进”的反义词，指从里面走到外面，“出了家门”即离开家。"}, {"text": "躺", "is_correct": false, "explanation": "躺是身体平卧的动作，与“进”没有相反关系。"}, {"text": "读", "is_correct": false, "explanation": "读是看文字并发出声音的动作，与“进”没有相反关系。"}, {"text": "哭", "is_correct": false, "explanation": "哭是流泪发出声音的表现，与“进”没有相反关系。"}], "correct_answer": "出", "explanations": {"出": "出是“进”的反义词，指从里面走到外面，“出了家门”即离开家。", "躺": "躺是身体平卧的动作，与“进”没有相反关系。", "读": "读是看文字并发出声音的动作，与“进”没有相反关系。", "哭": "哭是流泪发出声音的表现，与“进”没有相反关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24438, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进就是走到里面去。", "primary_collocate": null, "pronunciation": "jìn", "ipa": "tɕin⁵¹", "syllable_count": 1, "sentences": [{"text": "外面很冷，快进屋吧。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师已经进教室了。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他敲了敲门，然后进了房间。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把鞋脱了再进门。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们进咖啡店坐一会儿吧。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没进过那家饭馆。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门开着，你可以直接进。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在做饭，小孩不要进厨房。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影要开始了，大家都进电影院了。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着钥匙开门，进了家门。", "target_word": "进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进了", "label": "体标（了）"}, {"form": "进过", "label": "体标（过）"}, {"form": "进来", "label": "复合"}, {"form": "进去", "label": "复合"}, {"form": "進", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从外面走到里面去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37e3a5b6-7c2b-4c3d-9201-526e04e5c049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24438, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进", "is_correct": true, "explanation": "进 jìn：从外面走到里面去，意思是进入。"}, {"text": "金", "is_correct": false, "explanation": "金 jīn 与 jìn 声调不同（第一声），意思是金子。"}, {"text": "镜", "is_correct": false, "explanation": "镜 jìng 与 jìn 韵尾不同（-ng 与 -n），意思是镜子。"}, {"text": "信", "is_correct": false, "explanation": "信 xìn 与 jìn 声母不同（x 与 j），意思是信件。"}, {"text": "紧", "is_correct": false, "explanation": "紧 jǐn 与 jìn 声调不同（第三声），意思是拉紧、紧张。"}, {"text": "计", "is_correct": false, "explanation": "计 jì 与 jìn 少了韵尾 -n，意思是计算、计划。"}], "explanations": {"进": "进 jìn：从外面走到里面去，意思是进入。", "金": "金 jīn 与 jìn 声调不同（第一声），意思是金子。", "镜": "镜 jìng 与 jìn 韵尾不同（-ng 与 -n），意思是镜子。", "信": "信 xìn 与 jìn 声母不同（x 与 j），意思是信件。", "紧": "紧 jǐn 与 jìn 声调不同（第三声），意思是拉紧、紧张。", "计": "计 jì 与 jìn 少了韵尾 -n，意思是计算、计划。"}, "sentence_index": null, "correct_answer": "进"}, "level_3": {"options": [{"text": "进", "is_correct": true, "explanation": "进：“进屋”即走进屋内，与“外面很冷”的语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "配价：吃的宾语应是食物，不能带“屋”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱的宾语应是歌曲，不能说唱屋。"}, {"text": "跳", "is_correct": false, "explanation": "配价：跳不带处所宾语，不能说跳屋。"}], "explanations": {"进": "进：“进屋”即走进屋内，与“外面很冷”的语境相合。", "吃": "配价：吃的宾语应是食物，不能带“屋”。", "唱": "搭配：唱的宾语应是歌曲，不能说唱屋。", "跳": "配价：跳不带处所宾语，不能说跳屋。"}, "sentence_index": 0, "correct_answer": "进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一转身，又进了屋外。", "explanation": "这里应该用〈出〉。进是走到里面去，“屋外”是里面的反方向，不能说“进了屋外”。"}, {"text": "我们在河边进了一下午的步。", "explanation": "这里应该用〈散〉。进是走到里面去，不指散步；散步要说“散了一下午的步”。"}, {"text": "他们在操场上进了一场篮球，很开心。", "explanation": "这里应该用〈打〉。进是走到里面去，不指打球；打篮球要说“打了一场篮球”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24438, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "进", "is_correct": true, "explanation": "进 jìn：从外面走到里面去，意思是进入。"}, {"text": "斤", "is_correct": false, "explanation": "斤 jīn 与 jìn 声调不同（第一声），意思是重量单位斤。"}, {"text": "静", "is_correct": false, "explanation": "静 jìng 与 jìn 韵尾不同（-ng 与 -n），意思是安静。"}, {"text": "仅", "is_correct": false, "explanation": "仅 jǐn 与 jìn 声调不同（第三声），意思是只、仅仅。"}, {"text": "记", "is_correct": false, "explanation": "记 jì 与 jìn 少了韵尾 -n，意思是记住、记录。"}], "explanations": {"进": "进 jìn：从外面走到里面去，意思是进入。", "斤": "斤 jīn 与 jìn 声调不同（第一声），意思是重量单位斤。", "静": "静 jìng 与 jìn 韵尾不同（-ng 与 -n），意思是安静。", "仅": "仅 jǐn 与 jìn 声调不同（第三声），意思是只、仅仅。", "记": "记 jì 与 jìn 少了韵尾 -n，意思是记住、记录。"}, "sentence_index": null, "correct_answer": "进"}, "level_3": {"options": [{"text": "进", "is_correct": true, "explanation": "进：“直接进”即直接走进去，与“门开着”的语境相合。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿的动作，与门开着、走进去无关。"}, {"text": "摘", "is_correct": false, "explanation": "语义：摘指采下花果，与门开着、走进去无关。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是加热食物的动作，与门开着、走进去无关。"}], "explanations": {"进": "进：“直接进”即直接走进去，与“门开着”的语境相合。", "咬": "语义：咬是用牙齿的动作，与门开着、走进去无关。", "摘": "语义：摘指采下花果，与门开着、走进去无关。", "煮": "语义：煮是加热食物的动作，与门开着、走进去无关。"}, "sentence_index": 6, "correct_answer": "进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "时间进了三点，我们该吃饭了。", "explanation": "这里应该用〈到〉。进表示进入空间，不用于时间；时间到了某一点要说“到”。"}, {"text": "他进了一张照片，挂在墙上。", "explanation": "这里应该用〈拍〉。进表示进入，不指拍照；拍照要说“拍了一张照片”。"}, {"text": "妈妈给我们进了一桌好菜。", "explanation": "这里应该用〈端〉。进表示进入，不指端上菜肴；端菜要说“端了一桌好菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把碗进了冰箱。", "corrected_sentence": "妈妈把碗放进了冰箱。", "error_description": "错误：把字句中漏掉了动词“放”，直接用“进”带宾语。正确应补上“放”，说“放进了冰箱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们进了过那座古老的寺庙。", "corrected_sentence": "我们进过那座古老的寺庙。", "error_description": "错误：“进”后同时用了“了”和“过”。正确只用“过”，说“进过”，表示曾经进入过。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
