INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手做的动作，用来告诉别人事情。", "primary_collocate": null, "pronunciation": "shǒu shì", "ipa": "ʂou˨˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他做了一个手势，意思是“请安静”。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不懂这个手势是什么意思。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用手势告诉我，别出声。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向我做了一个手势，让我过去。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在很吵的地方，我们用手势说话。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的手势很清楚，大家都看懂了。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手势是说“好”。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学着爸爸的手势，笑了。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会说中文，只好用手势。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机看到那个手势，马上停了车。", "target_word": "手势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "手勢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用手的动作把事情告诉别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b159a33e-0896-4081-a4f7-985fcc4402be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24440, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手势", "is_correct": true, "explanation": "正确答案。手势（shǒushì）指手做的动作，用来告诉别人事情。"}, {"text": "收视", "is_correct": false, "explanation": "第一音节声调不同（shōu 第一声，shǒu 第三声），意思是观众收看电视节目的情况。"}, {"text": "首饰", "is_correct": false, "explanation": "第二音节由第四声变为轻声（shǒushi），意思是戴在身上的装饰品。"}, {"text": "收拾", "is_correct": false, "explanation": "两个音节的声调都不同（shōushi），意思是整理、收拾东西。"}, {"text": "收市", "is_correct": false, "explanation": "第一音节声调不同（shōushì），意思是交易市场结束营业。"}], "explanations": {"手势": "正确答案。手势（shǒushì）指手做的动作，用来告诉别人事情。", "收视": "第一音节声调不同（shōu 第一声，shǒu 第三声），意思是观众收看电视节目的情况。", "首饰": "第二音节由第四声变为轻声（shǒushi），意思是戴在身上的装饰品。", "收拾": "两个音节的声调都不同（shōushi），意思是整理、收拾东西。", "收市": "第一音节声调不同（shōushì），意思是交易市场结束营业。"}, "sentence_index": null, "correct_answer": "手势"}, "level_3": {"options": [{"text": "手势", "is_correct": true, "explanation": "正确：手势是动作，“做了一个手势”说得通，能表达“请安静”的意思。"}, {"text": "汤", "is_correct": false, "explanation": "语义：“汤”不能表示“请安静”的意思，“做了一个汤”与句义不合。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“做”不能与“名字”搭配，应说“取名字”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”是食物，不能表示“请安静”的意思。"}], "explanations": {"手势": "正确：手势是动作，“做了一个手势”说得通，能表达“请安静”的意思。", "汤": "语义：“汤”不能表示“请安静”的意思，“做了一个汤”与句义不合。", "名字": "搭配：“做”不能与“名字”搭配，应说“取名字”。", "蛋糕": "语义：“蛋糕”是食物，不能表示“请安静”的意思。"}, "sentence_index": 0, "correct_answer": "手势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他脸上挂着一个手势，很开心。", "explanation": "这里应该用〈笑容〉。笑容可以挂在脸上，“手势”是用手做的动作，不能挂在脸上。"}, {"text": "他推开手势，让我进去。", "explanation": "这里应该用〈门〉。“推开”的对象是门、窗等，手势不能被推开。"}, {"text": "他吹了个手势，叫我过去。", "explanation": "这里应该用〈口哨〉。“吹”的对象是口哨，手势是用手做的动作，不能被吹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手势", "is_correct": true, "explanation": "正确：手势可以表达“好”的意思，“这个手势是说……”说得通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不能表示“好”，句子说不通。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”是视力工具，不能表达意思，“是说‘好’”不成立。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体的高矮，不能“说”某个意思。"}], "explanations": {"手势": "正确：手势可以表达“好”的意思，“这个手势是说……”说得通。", "电脑": "语义：“电脑”不能表示“好”，句子说不通。", "眼镜": "语义：“眼镜”是视力工具，不能表达意思，“是说‘好’”不成立。", "身高": "体貌：“身高”指身体的高矮，不能“说”某个意思。"}, "sentence_index": 6, "correct_answer": "手势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机按了手势，马上停了车。", "explanation": "这里应该用〈喇叭〉。“按”搭配喇叭、按钮，手势不能被“按”。"}, {"text": "司机转动手势，马上停了车。", "explanation": "这里应该用〈方向盘〉。“转动”的对象是方向盘，手势不能被转动。"}, {"text": "司机看到那个手势亮了，马上停了车。", "explanation": "这里应该用〈灯〉。“亮”的对象是灯，手势是用手做的动作，不能亮起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机做了一根手势，让我们下车。", "corrected_sentence": "司机做了一个手势，让我们下车。", "error_description": "错误：“一根”；正确：“一个”。“根”用于细长的东西，手势用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板的手势把我马上坐下。", "corrected_sentence": "老板的手势让我马上坐下。", "error_description": "句式错误：“把”应为“让”。“坐下”是不及物动词，没有可以被“把”字句处置的对象。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba0ffcd-0732-41e3-ae79-ed1585779214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
