INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24444, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24444, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人心就是人们心里的想法和感觉。", "primary_collocate": null, "pronunciation": "rén xīn", "ipa": "ʐən˧˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "人心不同，想法也不一样。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道人心是怎么变化的。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间长了，才能看清人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人心很复杂，不容易看懂。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家常写人心的变化。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，读书可以安定人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱买不到人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间会改变人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说，这个人很会了解人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的故事能打动人心。", "target_word": "人心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人心惶惶", "label": "复合"}, {"form": "人心所向", "label": "复合"}], "register": "中性", "sense_fingerprint": "人们心里的想法和感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e58837-c3d8-404d-95dd-38296864162d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人心", "is_correct": true, "explanation": "“人心”指人们心里的想法，与“不同”“想法也不一样”搭配。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨没有想法，“想法也不一样”的主语只能是人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有想法，与句中“想法也不一样”的比较对象不符。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是身体部位，没有“想法”，不能作“想法也不一样”的比较对象。"}], "explanations": {"人心": "“人心”指人们心里的想法，与“不同”“想法也不一样”搭配。", "雨": "语义：雨没有想法，“想法也不一样”的主语只能是人。", "石头": "语义：石头没有想法，与句中“想法也不一样”的比较对象不符。", "眼睛": "语义：眼睛是身体部位，没有“想法”，不能作“想法也不一样”的比较对象。"}, "sentence_index": 0, "correct_answer": "人心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "广场上的人心很多，非常热闹。", "explanation": "这里应该用〈人群〉。人心指人们心里的想法，是抽象的，不能说“多”；聚集的人要用人群。"}, {"text": "他对小狗的人心很深。", "explanation": "这里应该用〈感情〉。人心指人们普遍的想法和感觉，不用于说对小狗的感情。"}, {"text": "我们要处理好人心关系。", "explanation": "这里应该用〈人际〉。人际指人与人之间的交往，人心指想法和感觉，不说“人心关系”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人心", "is_correct": true, "explanation": "“人心”是人们的想法和感觉，不能用钱买。"}, {"text": "大米", "is_correct": false, "explanation": "语义：大米可以用钱买，与“钱买不到”矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑可以用钱买，与“钱买不到”矛盾。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车可以用钱买，与“钱买不到”矛盾。"}], "explanations": {"人心": "“人心”是人们的想法和感觉，不能用钱买。", "大米": "语义：大米可以用钱买，与“钱买不到”矛盾。", "电脑": "语义：电脑可以用钱买，与“钱买不到”矛盾。", "汽车": "语义：汽车可以用钱买，与“钱买不到”矛盾。"}, "sentence_index": 6, "correct_answer": "人心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天喝人心。", "explanation": "这里应该用〈咖啡〉。〈喝〉搭配饮料，人心不能喝。"}, {"text": "他出门前戴上了人心。", "explanation": "这里应该用〈帽子〉。〈戴〉搭配帽子、眼镜等，人心不能戴。"}, {"text": "他在花园里摘人心。", "explanation": "这里应该用〈花〉。〈摘〉搭配花、果实等，人心不能摘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事之后，一个人心变得很复杂。", "corrected_sentence": "这件事之后，人心变得很复杂。", "error_description": "量词错误：“人心”是抽象概念，不能用个体量词“个”计数，应直接说“人心变得很复杂”，去掉“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "时间长了，人心们都变了。", "corrected_sentence": "时间长了，人心都变了。", "error_description": "“人心”是抽象的集合概念，不能加“们”表示复数，应去掉“们”，说“人心都变了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24446, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失传", "is_correct": true, "explanation": "“失传”指传统不再流传下去，与“传承”的意思相反。"}, {"text": "收割", "is_correct": false, "explanation": "与“传承”在任何义项上都没有反义或近义关系。"}, {"text": "烹饪", "is_correct": false, "explanation": "与“传承”在任何义项上都没有反义或近义关系。"}, {"text": "测量", "is_correct": false, "explanation": "与“传承”在任何义项上都没有反义或近义关系。"}], "correct_answer": "失传", "explanations": {"失传": "“失传”指传统不再流传下去，与“传承”的意思相反。", "收割": "与“传承”在任何义项上都没有反义或近义关系。", "烹饪": "与“传承”在任何义项上都没有反义或近义关系。", "测量": "与“传承”在任何义项上都没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24446, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失传", "is_correct": true, "explanation": "“失传”指传统不再流传下去，与“传承”的意思相反。"}, {"text": "装饰", "is_correct": false, "explanation": "与“传承”在任何义项上都没有反义或近义关系。"}, {"text": "翻译", "is_correct": false, "explanation": "与“传承”在任何义项上都没有反义或近义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "与“传承”在任何义项上都没有反义或近义关系。"}], "correct_answer": "失传", "explanations": {"失传": "“失传”指传统不再流传下去，与“传承”的意思相反。", "装饰": "与“传承”在任何义项上都没有反义或近义关系。", "翻译": "与“传承”在任何义项上都没有反义或近义关系。", "搬运": "与“传承”在任何义项上都没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24446, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把上一代的东西交给下一代，比如知识或习惯。", "primary_collocate": null, "pronunciation": "chuán chéng", "ipa": "ʈʂʰuan˧˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "爷爷把做面食的手艺传承给了我。", "target_word": "传承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要传承好传统文化。", "target_word": "传承", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个家族一直传承着这个习惯。", "target_word": "传承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅想把技术传承给年轻人。", "target_word": "传承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人过节的习俗一代代传承下来。", "target_word": "传承", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用唱歌的方式传承家乡的文化。", "target_word": "传承", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的老人在传承古老的故事。", "target_word": "传承", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的家风需要一代一代传承。", "target_word": "传承", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这门手艺没人传承，快消失了。", "target_word": "传承", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从父亲那里传承了医术。", "target_word": "传承", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "传承了", "label": "体标"}, {"form": "传承着", "label": "体标"}, {"form": "传承过", "label": "体标"}, {"form": "传承人", "label": "复合"}], "register": "书面", "sense_fingerprint": "把文化、技艺、习俗等一代代传下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22aa5821-43c2-4f1a-bd68-eccc7ce09b8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24446, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传承", "is_correct": true, "explanation": "“传承”指把手艺一代代交给下一代，与“给了我”相合。"}, {"text": "研究", "is_correct": false, "explanation": "配价：“研究”不能带“给……”这样的双宾语，句子不成立。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语是地点或展品，不能说“手艺给我”。"}, {"text": "生长", "is_correct": false, "explanation": "语义：“生长”指生物发育，不能用来指把手艺交给别人。"}], "explanations": {"传承": "“传承”指把手艺一代代交给下一代，与“给了我”相合。", "研究": "配价：“研究”不能带“给……”这样的双宾语，句子不成立。", "参观": "配价：“参观”的宾语是地点或展品，不能说“手艺给我”。", "生长": "语义：“生长”指生物发育，不能用来指把手艺交给别人。"}, "sentence_index": 0, "correct_answer": "传承"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这次考试的分数传承给了妈妈。", "explanation": "这里应该用〈告诉〉。“传承”的对象是文化、技艺、习俗等，考试分数只需告诉对方，不能说“传承”。"}, {"text": "学校传承了很多人才。", "explanation": "这里应该用〈培养〉。“传承”指把文化、技艺交给下一代，不指培养人才。"}, {"text": "我把旧手机传承给了弟弟。", "explanation": "这里应该用〈送给〉。“传承”的对象是文化、技艺、习俗等，把旧手机给弟弟只是一般的赠送，应说“送给”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传承", "is_correct": true, "explanation": "“传承”指把故事一代代传下去，与“古老的故事”相合。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是房屋、道路等建筑，不能用于故事。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”的对象是建筑物，不能用于故事。"}, {"text": "覆盖", "is_correct": false, "explanation": "语义：“覆盖”指盖在物体表面，与老人讲故事的语境不符。"}], "explanations": {"传承": "“传承”指把故事一代代传下去，与“古老的故事”相合。", "修建": "搭配：“修建”的对象是房屋、道路等建筑，不能用于故事。", "拆除": "搭配：“拆除”的对象是建筑物，不能用于故事。", "覆盖": "语义：“覆盖”指盖在物体表面，与老人讲故事的语境不符。"}, "sentence_index": 6, "correct_answer": "传承"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂每天传承大量的产品。", "explanation": "这里应该用〈生产〉。“传承”指把文化、技艺一代代交给后代，不指生产产品。"}, {"text": "请把这封信传承给王经理。", "explanation": "这里应该用〈交〉。“传承”指把文化、技艺一代代传下去，把一封信送到别人手里应说“交给”。"}, {"text": "我昨天在会上传承了一个通知。", "explanation": "这里应该用〈转达〉。“传承”指代代相传，一次会议上的通知要说“转达”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲把打鱼的本领传承了给我。", "corrected_sentence": "父亲把打鱼的本领传承给了我。", "error_description": "错误：“了”放错了位置。正确：“传承给了我”，“了”要放在“给”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人们把古老的歌谣一直传承下了。", "corrected_sentence": "老人们把古老的歌谣一直传承下来。", "error_description": "错误：趋向补语应为“下来”，不能说“下了”。正确：“传承下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
