INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24448, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人类文明就是所有人一起创造的好东西，比如房子、故事和规则。", "primary_collocate": null, "pronunciation": "rén lèi wén míng", "ipa": "ɻən˧˥ leɪ˥˩ wən˧˥ miŋ˧˥", "syllable_count": 4, "sentences": [{"text": "房子、故事和规则都是人类文明的一部分。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类文明是大家一起慢慢创造出来的。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习历史，能让我们了解人类文明的变化。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个民族都为人类文明做出了自己的贡献。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的桥和道路也属于人类文明。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上学习人类文明的故事。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐和画都是人类文明里很美的东西。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护环境，也是在保护人类文明。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想写一本关于人类文明的书。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有语言，就不会有人类文明。", "target_word": "人类文明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人類文明", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人类文明：大家一起创造的好东西，如房子、故事、规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86a9e316-c77e-4d87-af76-e864fd5a52f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人类文明", "is_correct": true, "explanation": "正确：人类文明是大家一起创造的好东西，房子、故事和规则都属于其中。"}, {"text": "动物", "is_correct": false, "explanation": "语义：房子、故事和规则不是动物的一部分，与“大家一起创造”的语义不合。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流里不包含房子和故事，句子语义不通。"}, {"text": "蔬菜", "is_correct": false, "explanation": "搭配：“都是……的一部分”的整体应与“房子、故事和规则”同类，蔬菜不能作其整体。"}], "explanations": {"人类文明": "正确：人类文明是大家一起创造的好东西，房子、故事和规则都属于其中。", "动物": "语义：房子、故事和规则不是动物的一部分，与“大家一起创造”的语义不合。", "河流": "语义：河流里不包含房子和故事，句子语义不通。", "蔬菜": "搭配：“都是……的一部分”的整体应与“房子、故事和规则”同类，蔬菜不能作其整体。"}, "sentence_index": 0, "correct_answer": "人类文明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每个民族都有自己的人类文明。", "explanation": "这里应该用〈文化〉。人类文明是全人类共同创造的财富，不说“每个民族有自己的人类文明”。"}, {"text": "我们要学习本国的人类文明。", "explanation": "这里应该用〈历史〉。人类文明指全人类的成果，不指一个国家的历史。"}, {"text": "学校规定，学生要遵守人类文明。", "explanation": "这里应该用〈规则〉。规则是需要遵守的具体规定，人类文明是大家一起创造的好东西的总称，不能说“遵守人类文明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人类文明", "is_correct": true, "explanation": "正确：音乐和画是人类文明中美的成果，“人类文明里”说得通。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶里不会有“很美的东西”，与音乐和画的美感不合。"}, {"text": "下水道", "is_correct": false, "explanation": "语义：下水道不是音乐和画所在的地方，语义不通。"}, {"text": "沼泽", "is_correct": false, "explanation": "搭配：沼泽多指湿地，不与“很美的东西”这样的说法搭配。"}], "explanations": {"人类文明": "正确：音乐和画是人类文明中美的成果，“人类文明里”说得通。", "垃圾桶": "语义：垃圾桶里不会有“很美的东西”，与音乐和画的美感不合。", "下水道": "语义：下水道不是音乐和画所在的地方，语义不通。", "沼泽": "搭配：沼泽多指湿地，不与“很美的东西”这样的说法搭配。"}, "sentence_index": 6, "correct_answer": "人类文明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在课堂上唱人类文明。", "explanation": "这里应该用〈歌〉。唱的对象是歌曲，人类文明是大家创造的好东西的总称，不能用来唱。"}, {"text": "他每天早上喝一杯人类文明。", "explanation": "这里应该用〈牛奶〉。能喝的是牛奶这样的饮料，人类文明是大家创造的成果的总称，不能喝。"}, {"text": "她学习人类文明设计。", "explanation": "这里应该用〈建筑〉。建筑设计是具体的工作，人类文明是大家创造的好东西的总称，不能说“人类文明设计”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该把人类文明传去下。", "corrected_sentence": "我们应该把人类文明传下去。", "error_description": "趋向补语错误：“传下去”中的补语应为“下去”，应紧跟动词“传”之后，说“传下去”，不能说“传去下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "没有工具，人类文明很难发展起去。", "corrected_sentence": "没有工具，人类文明很难发展起来。", "error_description": "趋向补语错误：“发展起来”中的补语应为“起来”，不能说“起去”，应说“发展起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2fc9aa7-9845-4983-931f-b78b00831c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
