INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地球仪上横着和竖着的线，帮助找到位置。", "primary_collocate": null, "pronunciation": "jīng wěi", "ipa": "tɕiŋ⁵⁵ weɪ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "地球仪上有很多横的和竖的经纬。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你在地球仪上找一找经纬。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟指着地球仪上的经纬问我。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球仪上的经纬像一张大网。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经纬把地球仪分成很多小格子。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师顺着地球仪上的经纬找到了北京。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，北京就在地球仪上经纬交叉的地方。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球仪上的经纬是用来找位置的。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球仪上红色的经纬很细，要看清楚。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在地球仪上数一数经纬。", "target_word": "经纬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经纬度", "label": "复合"}, {"form": "经纬线", "label": "复合"}, {"form": "經緯", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地球仪上横竖交叉的线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37e3a5b6-7c2b-4c3d-9201-526e04e5c049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24452, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "经纬", "is_correct": true, "explanation": "经纬（jīng wěi）指地球仪上横竖交叉的线，是正确答案。"}, {"text": "警卫", "is_correct": false, "explanation": "警卫（jǐng wèi）两个音节的声调都与经纬不同，意思是保卫人员。"}, {"text": "敬畏", "is_correct": false, "explanation": "敬畏（jìng wèi）两个音节的声调都与经纬不同，意思是尊敬又害怕。"}, {"text": "精美", "is_correct": false, "explanation": "精美（jīng měi）第二个音节声母是 m，与经纬的 w 不同，意思是精致美好。"}, {"text": "精微", "is_correct": false, "explanation": "精微（jīng wēi）第二个音节声调不同（wēi 第一声），意思是精细微妙。"}, {"text": "京味", "is_correct": false, "explanation": "京味（jīng wèi）第二个音节声调不同（wèi 第四声），意思是北京的风味。"}], "explanations": {"经纬": "经纬（jīng wěi）指地球仪上横竖交叉的线，是正确答案。", "警卫": "警卫（jǐng wèi）两个音节的声调都与经纬不同，意思是保卫人员。", "敬畏": "敬畏（jìng wèi）两个音节的声调都与经纬不同，意思是尊敬又害怕。", "精美": "精美（jīng měi）第二个音节声母是 m，与经纬的 w 不同，意思是精致美好。", "精微": "精微（jīng wēi）第二个音节声调不同（wēi 第一声），意思是精细微妙。", "京味": "京味（jīng wèi）第二个音节声调不同（wèi 第四声），意思是北京的风味。"}, "sentence_index": null, "correct_answer": "经纬"}, "level_3": {"options": [{"text": "经纬", "is_correct": true, "explanation": "经纬指地球仪上横竖两组线，与“横的和竖的”相符。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址是地点的文字标识，不是地球仪上的线，与“横的和竖的”不符。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“横的和竖的”修饰线条，不能用来修饰名字。"}, {"text": "年份", "is_correct": false, "explanation": "语义：年份是时间的数字，不是地球仪上横竖的线，句意说不通。"}], "explanations": {"经纬": "经纬指地球仪上横竖两组线，与“横的和竖的”相符。", "地址": "语义：地址是地点的文字标识，不是地球仪上的线，与“横的和竖的”不符。", "名字": "搭配：“横的和竖的”修饰线条，不能用来修饰名字。", "年份": "语义：年份是时间的数字，不是地球仪上横竖的线，句意说不通。"}, "sentence_index": 0, "correct_answer": "经纬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地球仪上的经纬是竖着的，从北极一直连到南极。", "explanation": "这里应该用〈经线〉。经纬指横竖两组线，只说竖着的线要用“经线”，经纬不能只指竖线。"}, {"text": "赤道是地球仪上最长的经纬，把地球分成南北两半。", "explanation": "这里应该用〈纬线〉。经纬指横竖两组线的合称，赤道只是一条横线，不能用“经纬”指单独的一条线。"}, {"text": "地轴是地球仪上贯穿南北极的经纬，地球就绕着它转。", "explanation": "这里应该用〈地轴〉。经纬指纵横交织的经线和纬线，地轴是穿过南北极的假想轴，不属于经纬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经纬", "is_correct": true, "explanation": "经纬指地球仪上横竖交叉的线，北京就在这些线交叉的地方，句意正确。"}, {"text": "国界", "is_correct": false, "explanation": "语义：国界是国与国之间的分界，北京并不在国界交叉的地方，与“北京就在……”不符。"}, {"text": "路口", "is_correct": false, "explanation": "语义：路口是道路交会的地方，地球仪上没有道路，与“地球仪上”不符。"}, {"text": "大陆", "is_correct": false, "explanation": "搭配：“大陆”不能与“交叉”搭配，不能说大陆交叉的地方。"}], "explanations": {"经纬": "经纬指地球仪上横竖交叉的线，北京就在这些线交叉的地方，句意正确。", "国界": "语义：国界是国与国之间的分界，北京并不在国界交叉的地方，与“北京就在……”不符。", "路口": "语义：路口是道路交会的地方，地球仪上没有道路，与“地球仪上”不符。", "大陆": "搭配：“大陆”不能与“交叉”搭配，不能说大陆交叉的地方。"}, "sentence_index": 6, "correct_answer": "经纬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "北京的经纬大约是北纬40度。", "explanation": "这里应该用〈纬度〉。纬度是表示位置的度数，经纬指地球仪上的线，不能说北京的经纬是一个度数。"}, {"text": "他用经纬测量了这块土地。", "explanation": "这里应该用〈经纬仪〉。经纬指线条，测量仪器要说“经纬仪”，不能直接把“经纬”当作仪器用。"}, {"text": "这个角的经纬是六十度。", "explanation": "这里应该用〈角度〉。经纬指线条，不是度数；说角的大小要用“角度”，不能用“经纬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地球仪上有很多只经纬。", "corrected_sentence": "地球仪上有很多条经纬。", "error_description": "量词错误：“只”用于动物等，经纬是线，应用量词“条”。应说“很多条经纬”，不能说“很多只经纬”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地球仪上地经纬很清楚，可以帮我们找位置。", "corrected_sentence": "地球仪上的经纬很清楚，可以帮我们找位置。", "error_description": "结构助词错误：修饰名词“经纬”的定语要用“的”，不能用“地”（“地”用于动词、形容词前作状语）。应说“地球仪上的经纬”，不能说“地球仪上地经纬”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24454, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放弃", "is_correct": true, "explanation": "正确。“放弃”指不再继续做下去，与“一直做下去、不停止”相反，是反义词。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”表示用脑子考虑问题，与“坚持”不构成反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”表示出游，与“坚持”不构成反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "“观看”表示看，与“坚持”不构成反义关系。"}], "correct_answer": "放弃", "explanations": {"放弃": "正确。“放弃”指不再继续做下去，与“一直做下去、不停止”相反，是反义词。", "思考": "“思考”表示用脑子考虑问题，与“坚持”不构成反义关系。", "旅行": "“旅行”表示出游，与“坚持”不构成反义关系。", "观看": "“观看”表示看，与“坚持”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24454, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放弃", "is_correct": true, "explanation": "正确。“放弃”指不再继续做下去，与“一直做下去、不停止”相反，是反义词。"}, {"text": "赞同", "is_correct": false, "explanation": "“赞同”表示同意，与“坚持”不构成反义关系。"}, {"text": "支持", "is_correct": false, "explanation": "“支持”表示帮助或赞成，与“坚持”不构成反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”表示探讨钻研，与“坚持”不构成反义关系。"}], "correct_answer": "放弃", "explanations": {"放弃": "正确。“放弃”指不再继续做下去，与“一直做下去、不停止”相反，是反义词。", "赞同": "“赞同”表示同意，与“坚持”不构成反义关系。", "支持": "“支持”表示帮助或赞成，与“坚持”不构成反义关系。", "研究": "“研究”表示探讨钻研，与“坚持”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24454, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一直做一件事，不停止。", "primary_collocate": null, "pronunciation": "jiān chí", "ipa": "tɕjɛn˥ ʈʂʰɨ˧˥", "syllable_count": 2, "sentences": [{"text": "他每天早上坚持跑步。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再坚持一下，马上就到了。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坚持学了三年中文。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然很累，我还是坚持走完了。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要坚持练习，你的字就会变好。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坚持写日记已经五年了。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥生病了，但他坚持上班。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没能坚持下去，所以放弃了。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷坚持着每天散步。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛很难，可是她一直坚持到最后。", "target_word": "坚持", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坚持了", "label": "体标"}, {"form": "坚持着", "label": "体标"}, {"form": "坚持过", "label": "体标"}], "register": "中性", "sense_fingerprint": "即使困难或疲劳，也持续做一件事不中断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e58837-c3d8-404d-95dd-38296864162d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24454, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坚持", "is_correct": true, "explanation": "正确答案：坚持（jiān chí），意思是一直做下去，不停止。"}, {"text": "坚实", "is_correct": false, "explanation": "shí 与 chí 声母不同（ch/sh），意思是结实可靠。"}, {"text": "监视", "is_correct": false, "explanation": "shì 与 chí 声母不同（ch/sh），声调也不同，意思是盯着看。"}, {"text": "尖刺", "is_correct": false, "explanation": "cì 与 chí 声母不同（ch/c），声调也不同，意思是尖的刺。"}], "explanations": {"坚持": "正确答案：坚持（jiān chí），意思是一直做下去，不停止。", "坚实": "shí 与 chí 声母不同（ch/sh），意思是结实可靠。", "监视": "shì 与 chí 声母不同（ch/sh），声调也不同，意思是盯着看。", "尖刺": "cì 与 chí 声母不同（ch/c），声调也不同，意思是尖的刺。"}, "sentence_index": null, "correct_answer": "坚持"}, "level_3": {"options": [{"text": "坚持", "is_correct": true, "explanation": "正确。“他每天早上坚持跑步”中，“坚持”表示每天一直做下去。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”与“每天早上”的持续含义相反。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”表示不再做，与“每天早上跑步”的习惯相矛盾。"}, {"text": "躲避", "is_correct": false, "explanation": "搭配：“躲避”的对象多是困难或危险，不能说“躲避跑步”。"}], "explanations": {"坚持": "正确。“他每天早上坚持跑步”中，“坚持”表示每天一直做下去。", "停止": "语义：“停止”与“每天早上”的持续含义相反。", "放弃": "语义：“放弃”表示不再做，与“每天早上跑步”的习惯相矛盾。", "躲避": "搭配：“躲避”的对象多是困难或危险，不能说“躲避跑步”。"}, "sentence_index": 0, "correct_answer": "坚持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个会议坚持了三个小时。", "explanation": "这里应该用〈持续〉。坚持强调人主动一直做某事，会议是进程，应说“持续”。"}, {"text": "他坚持这家公司的股票。", "explanation": "这里应该用〈持有〉。坚持不能带股票作宾语，持有股票要说“持有”。"}, {"text": "他坚持跑了一次步。", "explanation": "这里应该用〈尝试〉。坚持强调长时间不间断地做下去，只做一次应说“尝试”，不能用“坚持”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坚持", "is_correct": true, "explanation": "正确。“哥哥生病了，但他坚持上班”中，“坚持”表示尽管生病仍然持续上班。"}, {"text": "请假", "is_correct": false, "explanation": "语义：“请假”表示不去上班，与“上班”的语义矛盾。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：“辞职”表示离开工作，与“但他……上班”的转折语境冲突。"}, {"text": "休息", "is_correct": false, "explanation": "搭配：“休息”不能直接带“上班”作宾语，说“休息上班”不通。"}], "explanations": {"坚持": "正确。“哥哥生病了，但他坚持上班”中，“坚持”表示尽管生病仍然持续上班。", "请假": "语义：“请假”表示不去上班，与“上班”的语义矛盾。", "辞职": "语义：“辞职”表示离开工作，与“但他……上班”的转折语境冲突。", "休息": "搭配：“休息”不能直接带“上班”作宾语，说“休息上班”不通。"}, "sentence_index": 6, "correct_answer": "坚持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场雨坚持了一整天。", "explanation": "这里应该用〈下〉或〈持续〉。坚持指人克服困难一直做某事，下雨不是人的主动行为，应说“这场雨下了一整天”。"}, {"text": "他坚持了一本书。", "explanation": "这里应该用〈拿着〉。坚持表示一直做某件事，后面接动作，不能直接带“书”这样的东西作宾语。"}, {"text": "他坚持了一张桌子。", "explanation": "这里应该用〈搬〉。坚持表示持续做某事，不能直接带具体器物作宾语，搬桌子要说“搬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天都坚持了锻炼身体。", "corrected_sentence": "他每天都坚持锻炼身体。", "error_description": "“了”应删去：“每天都”表示习惯，“坚持”后不能加“了”，应说“坚持锻炼身体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坚持了住，没有放弃。", "corrected_sentence": "他坚持住了，没有放弃。", "error_description": "“了”放错位置：“坚持住”是动词加结果补语，“了”应放在“住”后面，说“坚持住了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
