INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24456, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "还没有，表示一件事还没发生。", "primary_collocate": null, "pronunciation": "shàng wèi", "ipa": "ʂɑŋ˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "飞机尚未起飞，请不要打开手机。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她尚未收到那封信。", "target_word": "尚未", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气尚未变冷，街上还有人穿短袖。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路尚未修好，车子过不去。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们尚未决定去哪里旅行。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师尚未到教室，学生们在聊天。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事尚未结束，不要太早高兴。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格尚未确定，请稍后再问。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他尚未找到合适的工作。", "target_word": "尚未", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座桥尚未开放，请走旁边的路。", "target_word": "尚未", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面副词，表示一件事还没有发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425e7d8f-3989-4c55-aef2-e45784558d9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24456, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尚未", "is_correct": true, "explanation": "「尚未」表示飞机还没起飞，与“请不要打开手机”的提醒相合。"}, {"text": "总是", "is_correct": false, "explanation": "语义：「总是」表示经常如此，与这一次起飞的情境不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示有时发生，与句中针对眼前情况的提醒不合。"}, {"text": "从不", "is_correct": false, "explanation": "搭配：「从不」否定习惯性动作，“飞机从不起飞”与句意相悖。"}], "explanations": {"尚未": "「尚未」表示飞机还没起飞，与“请不要打开手机”的提醒相合。", "总是": "语义：「总是」表示经常如此，与这一次起飞的情境不符。", "偶尔": "语义：「偶尔」表示有时发生，与句中针对眼前情况的提醒不合。", "从不": "搭配：「从不」否定习惯性动作，“飞机从不起飞”与句意相悖。"}, "sentence_index": 0, "correct_answer": "尚未"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥的施工正在进行，尚未在通车。", "explanation": "这里误用〈尚未〉。尚未本身表示“还没有”，后面直接接动词，不能再加「在」，应说「尚未通车」或「还没通车」。"}, {"text": "这座桥尚未是石头造的。", "explanation": "这里应该用〈一直〉。尚未只用于会发生变化的事，不能说明材料这类固有属性，应说「这座桥一直是石头造的」。"}, {"text": "这座桥我们早已尚未通行。", "explanation": "这里误用〈尚未〉。它表示还没发生，与已经发生的通行相矛盾，应说「还没通行」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24456, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尚未", "is_correct": true, "explanation": "「尚未」表示事情还没结束，与“不要太早高兴”的提醒相合。"}, {"text": "已经", "is_correct": false, "explanation": "语义：「已经结束」与“不要太早高兴”的提醒相矛盾。"}, {"text": "早已", "is_correct": false, "explanation": "语义：「早已结束」同样与“不要太早高兴”的提醒冲突。"}, {"text": "业已", "is_correct": false, "explanation": "语域：「业已」偏书面，与后句口语化的提醒不协调，且「业已结束」也与提醒相矛盾。"}], "explanations": {"尚未": "「尚未」表示事情还没结束，与“不要太早高兴”的提醒相合。", "已经": "语义：「已经结束」与“不要太早高兴”的提醒相矛盾。", "早已": "语义：「早已结束」同样与“不要太早高兴”的提醒冲突。", "业已": "语域：「业已」偏书面，与后句口语化的提醒不协调，且「业已结束」也与提醒相矛盾。"}, "sentence_index": 6, "correct_answer": "尚未"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都经过这座桥，它每次都尚未开放。", "explanation": "这里应该用〈没〉。尚未指单一的事截至目前还没发生，不能用于每次重复的情况。"}, {"text": "这座桥已经尚未开放，请走旁边的路。", "explanation": "这里误用〈尚未〉。尚未表示还没发生，与开放的状态相反，应说「还没开放」。"}, {"text": "这座桥我们早就尚未通行，请走旁边的路。", "explanation": "这里误用〈尚未〉。桥很久以前就能通行，尚未只表示还没发生，应说「还没通行」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "包裹尚未寄到了，你再等一下吧。", "corrected_sentence": "包裹尚未寄到，你再等一下吧。", "error_description": "〈尚未〉表示截至目前还没发生，不能与「了」连用表示已完成，应说「尚未寄到」或「还没寄到呢」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议时间尚未没公布，请大家耐心等待。", "corrected_sentence": "会议时间尚未公布，请大家耐心等待。", "error_description": "错误形式：“尚未没公布”；正确形式：“尚未公布”。〈尚未〉已经表示否定，不能再加〈没〉，应说「尚未公布」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
