INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24468, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西不会随便改变的样子。", "primary_collocate": null, "pronunciation": "gù dìng xìng", "ipa": "ku˥˩ tiŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这个规定有固定性，不能随便改。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢诗的固定性，每句字数一样。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的菜单没有固定性，每天都不同。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的作息缺少固定性，所以总是很累。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "词语的搭配有一定的固定性。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作没有固定性，常常换地方。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的规则很有固定性，大家都记住了。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人喜欢生活有固定性，不爱常常改变。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "成语的固定性很强，不能随便换字。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习时间要有固定性，才容易养成习惯。", "target_word": "固定性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "东西不随便改变、有固定样子的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425e7d8f-3989-4c55-aef2-e45784558d9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "固定性", "is_correct": true, "explanation": "正确：“固定性”指东西不随便改变，与“不能随便改”一致。"}, {"text": "灵活性", "is_correct": false, "explanation": "语义：“灵活性”指可以变通，与“不能随便改”相矛盾。"}, {"text": "可变性", "is_correct": false, "explanation": "语义：“可变性”指容易改变，与“不能随便改”相矛盾。"}, {"text": "节奏性", "is_correct": false, "explanation": "搭配：“节奏性”多用于音乐、动作，规定一般不说“有节奏性”。"}], "explanations": {"固定性": "正确：“固定性”指东西不随便改变，与“不能随便改”一致。", "灵活性": "语义：“灵活性”指可以变通，与“不能随便改”相矛盾。", "可变性": "语义：“可变性”指容易改变，与“不能随便改”相矛盾。", "节奏性": "搭配：“节奏性”多用于音乐、动作，规定一般不说“有节奏性”。"}, "sentence_index": 0, "correct_answer": "固定性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份合同的固定性很强，双方随时都可以修改条款。", "explanation": "这里应该用〈灵活性〉。“固定性”指东西不随便改变，与“随时都可以修改条款”相矛盾。"}, {"text": "这条裤子的固定性很好，穿起来很舒服。", "explanation": "这里应该用〈弹性〉。“固定性”指不随便变化，不用来说衣物的伸缩；“穿起来舒服”要用“弹性”。"}, {"text": "他的情绪固定性很强，一会儿高兴一会儿生气。", "explanation": "这里误用〈固定性〉。情绪的“稳定”应说「稳定性」，且“固定性”指东西不随便改变，与“一会儿高兴一会儿生气”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "固定性", "is_correct": true, "explanation": "正确：规则不变，大家才能记住，与“固定性”的意思相符。"}, {"text": "模糊性", "is_correct": false, "explanation": "语义：规则一旦“模糊”就难以记住，与“大家都记住了”矛盾。"}, {"text": "随机性", "is_correct": false, "explanation": "语义：规则“随机”就无法被记住，与后半句矛盾。"}, {"text": "文学性", "is_correct": false, "explanation": "搭配：“文学性”指文学作品的特点，游戏规则一般不说“有文学性”。"}], "explanations": {"固定性": "正确：规则不变，大家才能记住，与“固定性”的意思相符。", "模糊性": "语义：规则一旦“模糊”就难以记住，与“大家都记住了”矛盾。", "随机性": "语义：规则“随机”就无法被记住，与后半句矛盾。", "文学性": "搭配：“文学性”指文学作品的特点，游戏规则一般不说“有文学性”。"}, "sentence_index": 6, "correct_answer": "固定性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种材料的固定性很好，用几天就变了形。", "explanation": "这里误用〈固定性〉。“固定性”指东西不随便改变，与“用几天就变了形”相矛盾；说材料经久耐用应用「耐久性」。"}, {"text": "这把尺子的固定性很高，每次量出来的长度都不一样。", "explanation": "这里误用〈固定性〉。“固定性”指东西不随便改变，与“每次量出来的长度都不一样”相矛盾；测量的准确应说「精确性」。"}, {"text": "这篇文章的固定性很强，读起来很顺。", "explanation": "这里应该用〈可读性〉。“固定性”指东西不随便改变，说文章好读要用“可读性”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划地固定性很强，很难临时改动。", "corrected_sentence": "这个计划的固定性很强，很难临时改动。", "error_description": "错误形式：“地”；正确形式：“的”。〈固定性〉前的定语“这个计划”要用〈的〉连接，〈地〉用于修饰动词或形容词，应说「这个计划的固定性」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套规则有一块很强的固定性，大家都记住了。", "corrected_sentence": "这套规则有一种很强的固定性，大家都记住了。", "error_description": "量词错误：“固定性”是抽象名词，量词应用“种”，“块”用于成块的东西。正确形式是“一种很强的固定性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明显", "is_correct": true, "explanation": "反义：“明显”指容易看出，与“微妙”的细小不易察觉相对。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：形容质地，与差别的大小无关。"}, {"text": "漫长", "is_correct": false, "explanation": "无关：形容时间长，与此义无关。"}, {"text": "热闹", "is_correct": false, "explanation": "无关：形容场面喧闹，与此义无关。"}], "correct_answer": "明显", "explanations": {"明显": "反义：“明显”指容易看出，与“微妙”的细小不易察觉相对。", "柔软": "无关：形容质地，与差别的大小无关。", "漫长": "无关：形容时间长，与此义无关。", "热闹": "无关：形容场面喧闹，与此义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "显著", "is_correct": true, "explanation": "反义：“显著”指变化、差别非常明显，与“微妙”的细小不易察觉相对。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：形容温度低，与此义无关。"}, {"text": "陡峭", "is_correct": false, "explanation": "无关：形容地势，与此义无关。"}, {"text": "年轻", "is_correct": false, "explanation": "无关：形容年龄小，与变化的细小程度无关。"}], "correct_answer": "显著", "explanations": {"显著": "反义：“显著”指变化、差别非常明显，与“微妙”的细小不易察觉相对。", "寒冷": "无关：形容温度低，与此义无关。", "陡峭": "无关：形容地势，与此义无关。", "年轻": "无关：形容年龄小，与变化的细小程度无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很小很小，不容易看出来。", "primary_collocate": null, "pronunciation": "wēi miào", "ipa": "weɪ˥ miɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这两种颜色只有微妙的差别。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两首歌的节奏有微妙的区别。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两张照片的差别很微妙，我看不出来。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气有了微妙的变化。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个词的意思差别很微妙。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的声音里有微妙的不同。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光变化得很微妙，没人注意到。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个差别太微妙了，大家都没发现。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，空气里有一种微妙的变化。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走路的样子有些微妙的变化，只有妈妈看出来了。", "target_word": "微妙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "微妙地", "label": "状语形式"}], "register": "书面", "sense_fingerprint": "差别、变化极小而不易察觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd85b7b25-3bf8-4da1-af69-47b35a3d9947') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微妙", "is_correct": true, "explanation": "正确：“微妙”指差别很小、不易察觉，符合句意。"}, {"text": "热情", "is_correct": false, "explanation": "语义：热情形容人的态度，不能修饰颜色的差别。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：清脆多形容声音，不说颜色有清脆的差别。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：辽阔形容空间范围，不能修饰差别。"}], "explanations": {"微妙": "正确：“微妙”指差别很小、不易察觉，符合句意。", "热情": "语义：热情形容人的态度，不能修饰颜色的差别。", "清脆": "搭配：清脆多形容声音，不说颜色有清脆的差别。", "辽阔": "搭配：辽阔形容空间范围，不能修饰差别。"}, "sentence_index": 0, "correct_answer": "微妙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他只受了微妙的伤，很快就好了。", "explanation": "这里应该用〈轻微〉。微妙指差别或变化细小、不易察觉，不用来说伤势。"}, {"text": "这座山很微妙，又高又大。", "explanation": "这里应该用〈巨大〉。微妙指很小、不易察觉，不用来形容山的大小。"}, {"text": "这次的变化很微妙，大家都看得出来。", "explanation": "这里应该用〈明显〉。微妙指变化细小、不易察觉，与“大家都看得出来”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微妙", "is_correct": true, "explanation": "正确：“微妙”指变化细小，与“没人注意到”相符。"}, {"text": "显著", "is_correct": false, "explanation": "语义：显著指很明显，与“没人注意到”矛盾。"}, {"text": "剧烈", "is_correct": false, "explanation": "语义：剧烈指变化很猛烈，与“没人注意到”矛盾。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：明亮形容光线，不用来描述变化的程度。"}], "explanations": {"微妙": "正确：“微妙”指变化细小，与“没人注意到”相符。", "显著": "语义：显著指很明显，与“没人注意到”矛盾。", "剧烈": "语义：剧烈指变化很猛烈，与“没人注意到”矛盾。", "明亮": "搭配：明亮形容光线，不用来描述变化的程度。"}, "sentence_index": 6, "correct_answer": "微妙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这颗沙子很微妙，吹一吹就走了。", "explanation": "这里应该用〈细小〉。微妙用于差别和变化，不用来形容沙子的大小。"}, {"text": "这台机器的做工很微妙，零件都很整齐。", "explanation": "这里应该用〈精细〉。微妙用于差别和变化，不用来形容做工。"}, {"text": "他的鞋很微妙，穿了三年都没破。", "explanation": "这里应该用〈结实〉。微妙用于差别、变化，不用来形容鞋子的质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两种布料的差别很微妙地，我分不清。", "corrected_sentence": "这两种布料的差别很微妙，我分不清。", "error_description": "多加了“地”：“微妙”在此作谓语，后面不加“地”，应为“很微妙”，不说“很微妙地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两块石头的颜色有一点微妙地差别。", "corrected_sentence": "两块石头的颜色有一点微妙的差别。", "error_description": "的地混用：“微妙”修饰名词“差别”，应用“的”，不能用“地”。正确为“一点微妙的差别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
