INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24472, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24472, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大人告诉小孩不能做错事的话。", "primary_collocate": null, "pronunciation": "xùn jiè", "ipa": "ɕyn˥˩ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈的训诫，我一直记在心里。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不听爷爷的训诫，又去河边玩了。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸对弟弟说了一段严厉的训诫。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把家长的训诫当成了耳边风。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，奶奶常常给我们讲做人的训诫。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完爸爸的训诫，女儿哭着认了错。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的训诫让孩子明白了要诚实。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟低着头，听妈妈的训诫。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候常挨父亲的训诫。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些训诫，我小时候不太懂。", "target_word": "训诫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "家长或长辈对孩子说的、教他们不要做错事的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37e3a5b6-7c2b-4c3d-9201-526e04e5c049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "训诫", "is_correct": true, "explanation": "训诫：长辈对孩子讲的不许做错事的话，与“妈妈的”和“记在心里”相合。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是记录费用的单子，不是教导的话，不能“记在心里”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是家长说的话，“妈妈的天气”与“记在心里”都不相合。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是导电的线材，不是可以“记在心里”的话，与“妈妈的”搭配也不通。"}], "explanations": {"训诫": "训诫：长辈对孩子讲的不许做错事的话，与“妈妈的”和“记在心里”相合。", "账单": "语义：账单是记录费用的单子，不是教导的话，不能“记在心里”。", "天气": "语义：天气是自然现象，不是家长说的话，“妈妈的天气”与“记在心里”都不相合。", "电线": "语义：电线是导电的线材，不是可以“记在心里”的话，与“妈妈的”搭配也不通。"}, "sentence_index": 0, "correct_answer": "训诫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只狗经过训诫，已经会坐下了。", "explanation": "这里应该用〈训练〉。训诫指长辈对晚辈的告诫，不用于训练动物；训练动物要说“训练”。"}, {"text": "这所大学的训诫专业非常热门。", "explanation": "这里的“训诫”不是学科名称，它指长辈对晚辈的告诫；学科应说“教育学”之类的专业名称。"}, {"text": "他给了我一把训诫。", "explanation": "这里误把“训诫”当成有柄器具一类可以计数的东西。训诫是一番话语，应说“一番训诫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "训诫", "is_correct": true, "explanation": "训诫：长辈的告诫，与“老人”和“让孩子明白了要诚实”相合。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是外形特征，不能让孩子明白做人的道理。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是做菜的方法，与讲道理、让孩子明白诚实无关。"}, {"text": "鞭炮", "is_correct": false, "explanation": "语义：鞭炮是燃放的爆竹，与讲道理、让孩子明白诚实无关。"}], "explanations": {"训诫": "训诫：长辈的告诫，与“老人”和“让孩子明白了要诚实”相合。", "身高": "体貌：身高是外形特征，不能让孩子明白做人的道理。", "食谱": "语义：食谱是做菜的方法，与讲道理、让孩子明白诚实无关。", "鞭炮": "语义：鞭炮是燃放的爆竹，与讲道理、让孩子明白诚实无关。"}, "sentence_index": 6, "correct_answer": "训诫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的训诫很好吃。", "explanation": "这里应该用〈菜〉。训诫是长辈告诫晚辈的话，不是食物，不能说“好吃”。"}, {"text": "双方签订了一份训诫。", "explanation": "这里应该用〈合同〉。训诫是长辈对晚辈的告诫，不是双方签订的文件。"}, {"text": "他给我讲了一块训诫。", "explanation": "这里误把训诫当成成块的东西来计量。训诫是一番话语，应说“一番训诫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶给我讲了一只训诫。", "corrected_sentence": "奶奶给我讲了一番训诫。", "error_description": "错误：量词“只”用于动物或个体物件，不能修饰训诫。正确应用量词“番”，说“一番训诫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听了父亲的一件训诫。", "corrected_sentence": "他听了父亲的一段训诫。", "error_description": "错误：量词“件”用于物件或事情，不能修饰训诫。正确应用量词“段”，说“一段训诫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
