INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "仪式是一种特别的活动，大家按一定的方式做事情。", "primary_collocate": null, "pronunciation": "yí shì", "ipa": "i˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "毕业仪式在大礼堂举行。", "target_word": "仪式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校明天有升旗仪式。", "target_word": "仪式", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在教堂结婚，仪式很简单。", "target_word": "仪式", "complexity_tier": "T3", "furigana": "tāmen zài jiàotáng jiéhūn, yíshì hěn jiǎndān", "sentence_source": "generated"}, {"text": "开学仪式上，校长讲了话。", "target_word": "仪式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个仪式很特别，大家都穿白衣服。", "target_word": "仪式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年的时候，我们有一个小仪式。", "target_word": "仪式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她参加了朋友的结婚仪式。", "target_word": "仪式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "仪式开始前，大家安静地坐着。", "target_word": "仪式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年春天，村里都有祭祖的仪式。", "target_word": "仪式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毕业仪式结束后，我们一起照了相。", "target_word": "仪式", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个仪式", "label": "量词"}, {"form": "一场仪式", "label": "量词"}, {"form": "仪式感", "label": "复合"}], "register": "中性", "sense_fingerprint": "按一定程序举行的庆祝或纪念活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c158727a-e2ac-46d3-b271-c699b7ec501e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24476, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仪式", "is_correct": true, "explanation": "仪式（yí shì）：按一定程序举行的活动，即听到的词。"}, {"text": "遗失", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，“遗失”意思是丢失。"}, {"text": "以示", "is_correct": false, "explanation": "yǐ（第三声）与 yí（第二声）声调不同，“以示”意思是表示给人看。"}, {"text": "一世", "is_correct": false, "explanation": "yī（第一声）与 yí（第二声）声调不同，“一世”意思是一生、一代。"}, {"text": "议事", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，“议事”意思是商议事情。"}], "explanations": {"仪式": "仪式（yí shì）：按一定程序举行的活动，即听到的词。", "遗失": "shì（第四声）与 shī（第一声）声调不同，“遗失”意思是丢失。", "以示": "yǐ（第三声）与 yí（第二声）声调不同，“以示”意思是表示给人看。", "一世": "yī（第一声）与 yí（第二声）声调不同，“一世”意思是一生、一代。", "议事": "yì（第四声）与 yí（第二声）声调不同，“议事”意思是商议事情。"}, "sentence_index": null, "correct_answer": "仪式"}, "level_3": {"options": [{"text": "仪式", "is_correct": true, "explanation": "仪式：毕业仪式在大礼堂举行，符合句意。"}, {"text": "论文", "is_correct": false, "explanation": "语义：“论文”是书面作品，不能在大礼堂“举行”。"}, {"text": "照片", "is_correct": false, "explanation": "语义：“照片”是图片，不是可以举行的活动。"}, {"text": "证书", "is_correct": false, "explanation": "搭配：“证书”是颁发的证件，不能说“在大礼堂举行”。"}], "explanations": {"仪式": "仪式：毕业仪式在大礼堂举行，符合句意。", "论文": "语义：“论文”是书面作品，不能在大礼堂“举行”。", "照片": "语义：“照片”是图片，不是可以举行的活动。", "证书": "搭配：“证书”是颁发的证件，不能说“在大礼堂举行”。"}, "sentence_index": 0, "correct_answer": "仪式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台仪式坏了，需要请人来修理。", "explanation": "这里应该用〈仪器〉。仪式指按程序举行的活动，机器要用“仪器”，不能说“仪式坏了”。"}, {"text": "医生用仪式检查病人的身体。", "explanation": "这里应该用〈仪器〉。仪式指按程序举行的活动，检查身体要用“仪器”。"}, {"text": "她走路时仪式很端庄，说话也很轻。", "explanation": "这里应该用〈仪态〉。仪式指按程序举行的活动，形容走路的样子要用“仪态”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24476, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仪式", "is_correct": true, "explanation": "仪式：朋友的结婚仪式，她参加了，符合句意。"}, {"text": "戒指", "is_correct": false, "explanation": "语义：“戒指”是戴在手上的东西，不是活动，不能说“参加了结婚戒指”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”是食物，不是活动，不能说“参加了结婚蛋糕”。"}, {"text": "手续", "is_correct": false, "explanation": "搭配：“手续”要说“办”，不说“参加手续”。"}], "explanations": {"仪式": "仪式：朋友的结婚仪式，她参加了，符合句意。", "戒指": "语义：“戒指”是戴在手上的东西，不是活动，不能说“参加了结婚戒指”。", "蛋糕": "语义：“蛋糕”是食物，不是活动，不能说“参加了结婚蛋糕”。", "手续": "搭配：“手续”要说“办”，不说“参加手续”。"}, "sentence_index": 6, "correct_answer": "仪式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他仪式堂堂，很受同学欢迎。", "explanation": "这里应该用〈仪表〉。仪式指按程序举行的活动，形容外貌要用“仪表”，如“仪表堂堂”。"}, {"text": "他很会修理仪式，每天都在工作室忙。", "explanation": "这里应该用〈仪器〉。仪式指按程序举行的活动，修理的是“仪器”，不能说“修理仪式”。"}, {"text": "这篇文章的仪式很简单。", "explanation": "这里应该用〈形式〉。仪式指按程序举行的活动，文章的结构要用“形式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校举行了一张隆重的仪式。", "corrected_sentence": "学校举行了一场隆重的仪式。", "error_description": "“仪式”的量词应用“场”。“张”用于纸张、桌子等平面物件，不能修饰仪式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们参加了一个很正式毕业仪式。", "corrected_sentence": "我们参加了一个很正式的毕业仪式。", "error_description": "形容词“正式”修饰“仪式”时中间要加“的”，漏掉“的”就不成立，应写作“很正式的毕业仪式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd75a825-1ba1-4d13-af2f-d6021369ff4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
