INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24478, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "篝火是人们在户外用木头烧的火。", "primary_collocate": null, "pronunciation": "gōu huǒ", "ipa": "kou˥ xuɔ˨˩˦", "syllable_count": 2, "sentences": [{"text": "冬天的夜里，大家坐在篝火旁取暖。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要在树林里点篝火，太危险了。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们围着篝火跳舞。", "target_word": "篝火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们捡了很多木头来烧篝火。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "篝火在黑夜里亮着。", "target_word": "篝火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把湿木头放进篝火里，火就小了。", "target_word": "篝火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篝火上烤着鱼，味道很香。", "target_word": "篝火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下大了，篝火慢慢灭了。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行时，我第一次看到真的篝火。", "target_word": "篝火", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "篝火边的人越来越多。", "target_word": "篝火", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆", "label": "量词"}], "register": "中性", "sense_fingerprint": "人们在户外用木头烧的火", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '425e7d8f-3989-4c55-aef2-e45784558d9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "篝火", "is_correct": true, "explanation": "正确：“坐在篝火旁取暖”，篝火是取暖的热源，与句意相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是制冷的，不能用来取暖，与“取暖”矛盾。"}, {"text": "电扇", "is_correct": false, "explanation": "语义：电扇送风降温，与“取暖”的目的相反。"}, {"text": "凉风", "is_correct": false, "explanation": "搭配：“旁”前应接具体的处所或物体，“凉风”不能作“旁”的对象，且凉风不能取暖。"}], "explanations": {"篝火": "正确：“坐在篝火旁取暖”，篝火是取暖的热源，与句意相合。", "冰箱": "语义：冰箱是制冷的，不能用来取暖，与“取暖”矛盾。", "电扇": "语义：电扇送风降温，与“取暖”的目的相反。", "凉风": "搭配：“旁”前应接具体的处所或物体，“凉风”不能作“旁”的对象，且凉风不能取暖。"}, "sentence_index": 0, "correct_answer": "篝火"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他举着篝火走夜路，照亮了前面的山路。", "explanation": "这里应该用〈火把〉。篝火是堆在地上的火，不能举着走路；手持照明要用火把。"}, {"text": "农家的灶台里塞满了篝火。", "explanation": "这里应该用〈柴火〉。篝火是户外堆起来的火，灶台里放的是柴火。"}, {"text": "屋里的篝火烧得很旺，大家都围在它旁边。", "explanation": "这里应该用〈火炉〉。篝火是户外堆起来的火，室内取暖要用火炉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "篝火", "is_correct": true, "explanation": "正确：“篝火上烤着鱼”，鱼在火上烤，与“味道很香”一致。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能用来烤鱼，“书包上烤着鱼”与句意矛盾。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“上”前应接能承载东西的面，“天空”不能承载烤着的鱼。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨水会浇灭火，不能在雨中烤鱼，与“烤着鱼，味道很香”矛盾。"}], "explanations": {"篝火": "正确：“篝火上烤着鱼”，鱼在火上烤，与“味道很香”一致。", "书包": "语义：书包不能用来烤鱼，“书包上烤着鱼”与句意矛盾。", "天空": "搭配：“上”前应接能承载东西的面，“天空”不能承载烤着的鱼。", "雨": "语义：雨水会浇灭火，不能在雨中烤鱼，与“烤着鱼，味道很香”矛盾。"}, "sentence_index": 6, "correct_answer": "篝火"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜空中的篝火越来越多。", "explanation": "这里应该用〈烟花〉。篝火是堆在地上燃烧的火，不会出现在夜空中。"}, {"text": "树上挂的篝火越来越多。", "explanation": "这里应该用〈灯笼〉。篝火是堆在地面的火，不能挂在树上。"}, {"text": "桌上的篝火越来越少。", "explanation": "这里应该用〈蜡烛〉。篝火是户外堆木柴燃烧的火，不能放在桌上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "篝火还烧了，大家都舍不得走。", "corrected_sentence": "篝火还烧着，大家都舍不得走。", "error_description": "动态助词错误：表示火仍在燃烧应用“烧着”，“烧了”表示已经烧过、结束，与“还”和“舍不得走”不搭。正确形式是“篝火还烧着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里他在一根篝火旁边坐了很久。", "corrected_sentence": "夜里他在一堆篝火旁边坐了很久。", "error_description": "量词错误：“篝火”的量词应为“堆”，“根”用于细长的东西。正确形式是“一堆篝火”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '420412d2-f96e-4dec-83f0-1d549ca3478a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
