INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "睡觉时心里想的事情。", "primary_collocate": null, "pronunciation": "mèng", "ipa": "məŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我昨天晚上做了一个长梦。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡着了，梦里还在笑。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我常常忘记自己的梦。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梦里有很多我不认识的人。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个梦让我一晚上没睡好。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上醒来，梦还在我脑子里。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给朋友讲了我的梦。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上都做一个很长的梦。", "target_word": "梦", "complexity_tier": "T3", "furigana": "tā měi tiān wǎnshang dōu zuò yí ge hěn cháng de mèng", "sentence_source": "generated"}, {"text": "这个梦太怪了，我把它写了下来。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梦里下着大雨，我很冷。", "target_word": "梦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夢", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "做梦", "label": "复合"}, {"form": "梦境", "label": "复合"}], "register": "中性", "sense_fingerprint": "睡觉时心里想到、看到的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba9a7b9-9fdc-48f2-ac56-de532a27db8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24488, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "梦", "is_correct": true, "explanation": "梦（mèng）是本题目标词，指睡觉时心里想到、看到的事情。"}, {"text": "猛", "is_correct": false, "explanation": "猛（měng，第三声）与 mèng（第四声）声调不同，意思是凶猛。"}, {"text": "闷", "is_correct": false, "explanation": "闷（mèn）与 mèng 只差韵尾（en 与 eng），意思是闷热。"}, {"text": "蒙", "is_correct": false, "explanation": "蒙（méng，第二声）与 mèng 声调不同，意思是蒙住。"}, {"text": "萌", "is_correct": false, "explanation": "萌（méng，第二声）与 mèng 声调不同，意思是萌芽。"}], "explanations": {"梦": "梦（mèng）是本题目标词，指睡觉时心里想到、看到的事情。", "猛": "猛（měng，第三声）与 mèng（第四声）声调不同，意思是凶猛。", "闷": "闷（mèn）与 mèng 只差韵尾（en 与 eng），意思是闷热。", "蒙": "蒙（méng，第二声）与 mèng 声调不同，意思是蒙住。", "萌": "萌（méng，第二声）与 mèng 声调不同，意思是萌芽。"}, "sentence_index": null, "correct_answer": "梦"}, "level_3": {"options": [{"text": "梦", "is_correct": true, "explanation": "梦与“做了一个长”搭配，指睡觉时出现的一连串心理活动。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“做”不能带“天气”，“做了一个长天气”不成立。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“做”不能带“河流”，这样的说法不存在。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“做了一个长桌子”与“昨天晚上”睡觉的语境不合，句意不通。"}], "explanations": {"梦": "梦与“做了一个长”搭配，指睡觉时出现的一连串心理活动。", "天气": "搭配：“做”不能带“天气”，“做了一个长天气”不成立。", "河流": "搭配：“做”不能带“河流”，这样的说法不存在。", "桌子": "搭配：“做了一个长桌子”与“昨天晚上”睡觉的语境不合，句意不通。"}, "sentence_index": 0, "correct_answer": "梦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对小时候的事还有很多梦。", "explanation": "这里应该用〈回忆〉。梦指睡觉时的心理活动，不能用来指对往事的记忆。"}, {"text": "这个梦下周三召开。", "explanation": "这里应该用〈会议〉。梦指睡觉时心里想的事情，不能作为下周三召开的会议。"}, {"text": "这本日记梦了我的生活。", "explanation": "这里应该用〈记录〉。梦是睡觉时的心理活动，不能用来指对生活的记录。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24488, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "梦", "is_correct": true, "explanation": "梦（mèng）是本题目标词，指睡觉时心里想到、看到的事情。"}, {"text": "盟", "is_correct": false, "explanation": "盟（méng，第二声）与 mèng 声调不同，意思是结盟。"}, {"text": "懵", "is_correct": false, "explanation": "懵（měng，第三声）与 mèng 声调不同，意思是糊涂。"}, {"text": "锰", "is_correct": false, "explanation": "锰（měng，第三声）与 mèng 声调不同，是一种金属元素。"}, {"text": "焖", "is_correct": false, "explanation": "焖（mèn）与 mèng 只差韵尾（en 与 eng），意思是用小火慢煮。"}], "explanations": {"梦": "梦（mèng）是本题目标词，指睡觉时心里想到、看到的事情。", "盟": "盟（méng，第二声）与 mèng 声调不同，意思是结盟。", "懵": "懵（měng，第三声）与 mèng 声调不同，意思是糊涂。", "锰": "锰（měng，第三声）与 mèng 声调不同，是一种金属元素。", "焖": "焖（mèn）与 mèng 只差韵尾（en 与 eng），意思是用小火慢煮。"}, "sentence_index": null, "correct_answer": "梦"}, "level_3": {"options": [{"text": "梦", "is_correct": true, "explanation": "梦可以讲给朋友听，指睡觉时出现的心理活动，与“我的”搭配。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：“牛奶”不是可以讲述的内容，“讲了我的牛奶”说不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“讲”不能带“眼睛”作宾语，句子不成立。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不是可以讲给别人的内容，与“讲了”不合。"}], "explanations": {"梦": "梦可以讲给朋友听，指睡觉时出现的心理活动，与“我的”搭配。", "牛奶": "语义：“牛奶”不是可以讲述的内容，“讲了我的牛奶”说不通。", "眼睛": "搭配：“讲”不能带“眼睛”作宾语，句子不成立。", "空气": "语义：“空气”不是可以讲给别人的内容，与“讲了”不合。"}, "sentence_index": 6, "correct_answer": "梦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校的梦很严格。", "explanation": "这里应该用〈规定〉。梦指睡觉时的心理活动，不能用来形容制度的严格。"}, {"text": "他每月的梦是五千元。", "explanation": "这里应该用〈工资〉。梦不能表示每月的金额，工资才指领取的钱数。"}, {"text": "这张票的梦是一百元。", "explanation": "这里应该用〈票价〉。梦不能用来表示价格，买票所付的钱数要用票价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我前天晚上做了一只很长的梦。", "corrected_sentence": "我前天晚上做了一场很长的梦。", "error_description": "量词错误：“梦”前不能用量词“只”，应改为“场”或“个”。正确说法是“我前天晚上做了一场很长的梦”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候做了一本很长的梦。", "corrected_sentence": "我小时候做了一个很长的梦。", "error_description": "量词错误：「梦」不能用量词「本」，应改为「个」或「场」，正确为「我小时候做了一个很长的梦」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
