INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24490, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一件事情从头讲到尾。", "primary_collocate": null, "pronunciation": "xù shù", "ipa": "ɕy˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶慢慢叙述着年轻时的故事。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把比赛的经过从头叙述了一遍。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你详细叙述一下昨天的事。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明叙述完，老师点了点头。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信叙述了他在国外的生活。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者叙述了地震那天的情况。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用很短的话叙述了整个过程。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸叙述当年的旅行时，特别高兴。", "target_word": "叙述", "complexity_tier": "T3", "furigana": "xù shù", "sentence_source": "generated"}, {"text": "他无法叙述当时发生的一切。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游叙述了这座古城的历史。", "target_word": "叙述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "叙述了", "label": "体标"}, {"form": "叙述着", "label": "体标"}, {"form": "叙述过", "label": "体标"}, {"form": "敘述", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把一件事从头讲到尾", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba9a7b9-9fdc-48f2-ac56-de532a27db8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24490, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "叙述", "is_correct": true, "explanation": "正确：叙述指把一件事从头讲到尾。"}, {"text": "虚数", "is_correct": false, "explanation": "声调：xū（第一声）与 xù（第四声）声调不同，意思是虚数。"}, {"text": "续书", "is_correct": false, "explanation": "声调：shū（第一声）与 shù（第四声）声调不同，意思是续书。"}, {"text": "玉树", "is_correct": false, "explanation": "声母：yù 与 xù 声母不同，意思是玉树（青海地名）。"}], "explanations": {"叙述": "正确：叙述指把一件事从头讲到尾。", "虚数": "声调：xū（第一声）与 xù（第四声）声调不同，意思是虚数。", "续书": "声调：shū（第一声）与 shù（第四声）声调不同，意思是续书。", "玉树": "声母：yù 与 xù 声母不同，意思是玉树（青海地名）。"}, "sentence_index": null, "correct_answer": "叙述"}, "level_3": {"options": [{"text": "叙述", "is_correct": true, "explanation": "正确：“叙述”指把故事从头讲到尾，与“慢慢……年轻时的故事”相合。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”的宾语应是场所或物品，不能接“故事”。"}, {"text": "播种", "is_correct": false, "explanation": "语义：“播种”指撒种子，与讲述故事无关。"}, {"text": "熨烫", "is_correct": false, "explanation": "语义：“熨烫”指用熨斗把衣物烫平，与讲故事不合。"}], "explanations": {"叙述": "正确：“叙述”指把故事从头讲到尾，与“慢慢……年轻时的故事”相合。", "打扫": "配价：“打扫”的宾语应是场所或物品，不能接“故事”。", "播种": "语义：“播种”指撒种子，与讲述故事无关。", "熨烫": "语义：“熨烫”指用熨斗把衣物烫平，与讲故事不合。"}, "sentence_index": 0, "correct_answer": "叙述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用一个词叙述了那个人的样子。", "explanation": "这里应该用〈形容〉。叙述是讲事件经过，描绘人的样子要用〈形容〉。"}, {"text": "老师叙述了三十个数字的和。", "explanation": "这里应该用〈计算〉。叙述是讲事件经过，求数字的和要用〈计算〉。"}, {"text": "他叙述了这张地图的比例尺。", "explanation": "这里应该用〈绘制〉。叙述是讲事件经过，画出地图的比例尺要用〈绘制〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24490, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "叙述", "is_correct": true, "explanation": "正确：叙述指把一件事从头讲到尾。"}, {"text": "素数", "is_correct": false, "explanation": "声母：sù 与 xù 声母不同，意思是素数（只能被1和自身整除的数）。"}, {"text": "蓄水", "is_correct": false, "explanation": "韵母和声调：shuǐ（第三声）与 shù（第四声）不同，意思是蓄水（储存水）。"}, {"text": "路数", "is_correct": false, "explanation": "声母：lù 与 xù 声母不同，意思是路数（做事的路子）。"}], "explanations": {"叙述": "正确：叙述指把一件事从头讲到尾。", "素数": "声母：sù 与 xù 声母不同，意思是素数（只能被1和自身整除的数）。", "蓄水": "韵母和声调：shuǐ（第三声）与 shù（第四声）不同，意思是蓄水（储存水）。", "路数": "声母：lù 与 xù 声母不同，意思是路数（做事的路子）。"}, "sentence_index": null, "correct_answer": "叙述"}, "level_3": {"options": [{"text": "叙述", "is_correct": true, "explanation": "正确：“叙述”指讲述事情的经过，与“很短的话”和“整个过程”相合。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”不能接“过程”这类抽象对象，与“很短的话”也不搭。"}, {"text": "缝补", "is_correct": false, "explanation": "语义：“缝补”指用针线修补衣物，与“很短的话”不合。"}, {"text": "灌溉", "is_correct": false, "explanation": "语义：“灌溉”指给田地浇水，与讲述过程无关。"}], "explanations": {"叙述": "正确：“叙述”指讲述事情的经过，与“很短的话”和“整个过程”相合。", "清洗": "搭配：“清洗”不能接“过程”这类抽象对象，与“很短的话”也不搭。", "缝补": "语义：“缝补”指用针线修补衣物，与“很短的话”不合。", "灌溉": "语义：“灌溉”指给田地浇水，与讲述过程无关。"}, "sentence_index": 6, "correct_answer": "叙述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生叙述了病人的心跳。", "explanation": "这里应该用〈检查〉。叙述是讲事件的经过，查看身体状况要用〈检查〉。"}, {"text": "我们叙述了这次展览的门票价格。", "explanation": "这里应该用〈公布〉。叙述是讲事件经过，公布门票价格要用〈公布〉。"}, {"text": "他用乐器叙述了一座山的高度。", "explanation": "这里应该用〈测量〉。叙述是讲事件经过，量出山的高度要用〈测量〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小王叙述着过这件事。", "corrected_sentence": "小王叙述过这件事。", "error_description": "错误：“叙述着过”，“着”与“过”不能同用；正确为“叙述过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他叙述过那次旅行过。", "corrected_sentence": "他叙述过那次旅行。", "error_description": "错误：句末多出一个“过”，体标“过”只用一次，应删去末尾的“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
