INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24492, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地貌就是地球表面的样子，有高山、平地等。", "primary_collocate": null, "pronunciation": "dì mào", "ipa": "ti˥˩ mau˥˩", "syllable_count": 2, "sentences": [{"text": "我们学校附近的地貌很平，没有山。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的地貌有高山，也有平地。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸喜欢拍照，也爱看不同的地貌。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方多雨，所以那里的地貌和北方不一样。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的颜色能告诉我们地貌是高还是低。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪山和湖让这里的地貌特别美。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去看看西藏的高原地貌。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车走了一天，窗外的地貌一直在变。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们画出这里的地貌。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山很高的地方，地貌和海边完全不同。", "target_word": "地貌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "地貌学", "label": "复合"}], "register": "中性", "sense_fingerprint": "地球表面的样子（高山、平地等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd77a6e-512b-404b-8c8e-391df7f0437e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是大气的状况，不是地面的形状，不能说“很平”。"}, {"text": "地貌", "is_correct": true, "explanation": "地貌：地表的样子，可以说“很平”，与“没有山”的描述相符。"}, {"text": "八卦", "is_correct": false, "explanation": "语义：“八卦”指八卦图或流言，不能用来形容地面的样子，说“很平”不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书籍，不是地表的样子，不能说“很平”。"}], "explanations": {"天气": "语义：天气是大气的状况，不是地面的形状，不能说“很平”。", "地貌": "地貌：地表的样子，可以说“很平”，与“没有山”的描述相符。", "八卦": "语义：“八卦”指八卦图或流言，不能用来形容地面的样子，说“很平”不通。", "课本": "语义：课本是书籍，不是地表的样子，不能说“很平”。"}, "sentence_index": 0, "correct_answer": "地貌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里地貌很热，夏天经常下雨。", "explanation": "这里应该用〈天气〉。地貌指地表的样子，不能用“热”来形容；说冷热要用〈天气〉。"}, {"text": "南方的地貌很湿润，雨水很多。", "explanation": "这里应该用〈气候〉。“湿润”形容的是气候，地貌不能潮湿；说干湿要用〈气候〉。"}, {"text": "请把你家的地貌告诉我，我明天给你寄信。", "explanation": "这里应该用〈地址〉。寄信需要地址；地貌是地表的样子，不是寄送的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是可以去看的景物，“去看看西藏的高原作业”不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不是地表的景物，不能用来“去看看”高原。"}, {"text": "地貌", "is_correct": true, "explanation": "地貌：地表的样子，可以去看，与西藏高原的语境相符。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法不是可以去看的实体，与“去看看西藏的高原”矛盾。"}], "explanations": {"作业": "语义：作业是学习任务，不是可以去看的景物，“去看看西藏的高原作业”不通。", "电脑": "语义：电脑是机器，不是地表的景物，不能用来“去看看”高原。", "地貌": "地貌：地表的样子，可以去看，与西藏高原的语境相符。", "语法": "语义：语法不是可以去看的实体，与“去看看西藏的高原”矛盾。"}, "sentence_index": 6, "correct_answer": "地貌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里地貌很湿，下雨后很滑。", "explanation": "这里应该用〈地面〉。地面可以湿、可以滑；地貌是地表形态的类型，不说潮湿。"}, {"text": "这家店位于市中心的黄金地貌。", "explanation": "这里应该用〈地段〉。地段指位置，可以说“黄金地段”；地貌不指商业位置。"}, {"text": "这位老人的地貌很慈祥。", "explanation": "这里应该用〈面貌〉。地貌指地表形态，不指人的样子；形容人的神态要用〈面貌〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只地貌在南方很少见。", "corrected_sentence": "那种地貌在南方很少见。", "error_description": "“地貌”前的量词错误：“只”用于动物等个体，应改为“种”，即“那种地貌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一带的地貌们很平坦。", "corrected_sentence": "这一带的地貌很平坦。", "error_description": "“地貌”后多加了“们”：“们”只用于指人的复数，地貌是事物，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24494, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24494, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "神话是古代人编的故事，里面有神仙和英雄。", "primary_collocate": null, "pronunciation": "shén huà", "ipa": "ʂən˧˥ xua˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶晚上给我讲了一个神话。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话里有神仙，也有英雄。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个神话是古代人编的故事。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢嫦娥奔月这个神话。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话不是真的，但是很好听。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在图书馆借了一本讲神话的书。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是一个中国神话。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话里的神仙都有特别的本事。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我很爱看神话，常常看到很晚。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，神话能让我们了解古代人的想法。", "target_word": "神话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "则", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "神话故事", "label": "复合"}, {"form": "神話", "label": "繁体"}], "register": "中性", "sense_fingerprint": "古代人编的、有神仙和英雄的故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd77a6e-512b-404b-8c8e-391df7f0437e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24494, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "神话", "is_correct": true, "explanation": "正确答案，shén huà，指古代人编的、有神仙和英雄的故事。"}, {"text": "深化", "is_correct": false, "explanation": "shēn（第一声）与 shén（第二声）声调不同，意思是“深化”。"}, {"text": "文化", "is_correct": false, "explanation": "wén（第二声）与 shén（第二声）声母不同（w／sh），声调相同，意思是“文化”。"}, {"text": "真话", "is_correct": false, "explanation": "zhēn（第一声）与 shén（第二声）声母不同（zh／sh），声调也不同，意思是“真话”。"}, {"text": "生化", "is_correct": false, "explanation": "shēng（第一声）与 shén（第二声）韵母不同（eng／en），声调也不同，意思是“生化”。"}], "explanations": {"神话": "正确答案，shén huà，指古代人编的、有神仙和英雄的故事。", "深化": "shēn（第一声）与 shén（第二声）声调不同，意思是“深化”。", "文化": "wén（第二声）与 shén（第二声）声母不同（w／sh），声调相同，意思是“文化”。", "真话": "zhēn（第一声）与 shén（第二声）声母不同（zh／sh），声调也不同，意思是“真话”。", "生化": "shēng（第一声）与 shén（第二声）韵母不同（eng／en），声调也不同，意思是“生化”。"}, "sentence_index": null, "correct_answer": "神话"}, "level_3": {"options": [{"text": "神话", "is_correct": true, "explanation": "正确。“讲了一个”后接的是故事，神话是神仙、英雄的故事，符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“讲”的宾语是故事、话语，冰箱不能被讲述。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是记账凭证，不是可以讲述的故事，与“晚上讲给我听”的语境不符。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“讲”不能以电脑作宾语，电脑不能被讲述。"}], "explanations": {"神话": "正确。“讲了一个”后接的是故事，神话是神仙、英雄的故事，符合语境。", "冰箱": "搭配：“讲”的宾语是故事、话语，冰箱不能被讲述。", "账单": "语义：账单是记账凭证，不是可以讲述的故事，与“晚上讲给我听”的语境不符。", "电脑": "搭配：“讲”不能以电脑作宾语，电脑不能被讲述。"}, "sentence_index": 0, "correct_answer": "神话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段神话记录了北宋时期的一场战争。", "explanation": "这里应该用〈历史〉。神话是神仙、英雄的虚构故事，不用来记录真实发生的战争。"}, {"text": "我最喜欢读居里夫人的神话。", "explanation": "这里应该用〈传记〉。神话写的是神仙、英雄的虚构故事，不写真实人物的生平。"}, {"text": "这个神话是记者昨天在超市门口拍到的真事。", "explanation": "这里应该用〈新闻〉。神话是古代人编的神仙、英雄故事，记者拍到的真实事情应说新闻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神话", "is_correct": true, "explanation": "正确。电影讲的是一个中国神话，指中国的神仙、英雄故事，符合语境。"}, {"text": "美食", "is_correct": false, "explanation": "语义：美食不是能被电影讲述的故事情节，与“中国神话”的语境不合。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学不是电影讲述的故事题材，与“中国”的神话语境不符。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“讲的是”后接的是故事、事件等内容，沙发不能作为电影讲述的对象。"}], "explanations": {"神话": "正确。电影讲的是一个中国神话，指中国的神仙、英雄故事，符合语境。", "美食": "语义：美食不是能被电影讲述的故事情节，与“中国神话”的语境不合。", "数学": "语义：数学不是电影讲述的故事题材，与“中国”的神话语境不符。", "沙发": "搭配：“讲的是”后接的是故事、事件等内容，沙发不能作为电影讲述的对象。"}, "sentence_index": 6, "correct_answer": "神话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本神话的主人公是一个爱吃糖的小女孩。", "explanation": "这里应该用〈童话〉。神话写神仙、英雄的故事，写小女孩爱吃糖这类日常童趣的应说童话。"}, {"text": "这则神话里，狐狸骗走了乌鸦嘴里的肉。", "explanation": "这里应该用〈寓言〉。神话写神仙、英雄的事；借动物讲道理的故事是寓言，不能称作“这则神话”。"}, {"text": "这部神话讲的是一位侠客远走江湖的故事。", "explanation": "这里应该用〈传奇〉。神话以神仙和神化英雄为主，写侠客闯荡江湖的故事应说传奇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候常听爸爸讲一座神话。", "corrected_sentence": "我小时候常听爸爸讲一个神话。", "error_description": "“座”是用于山、楼房等大型固定物的量词，不能修饰神话；应改为“一个神话”，“个”是通用量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些神话们都很有名。", "corrected_sentence": "这些神话都很有名。", "error_description": "“们”只能加在指人的名词后面，神话不能说“神话们”；应去掉“们”，直接说“这些神话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '243f270e-2ec7-4b1d-9777-84ef906cd645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
