INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24496, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个东西和另一个东西对应起来。", "primary_collocate": null, "pronunciation": "yìng shè", "ipa": "iŋ˥˩ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这张图把每个名字映射到一个号码。", "target_word": "映射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把左边的数映射到右边。", "target_word": "映射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表格把城市映射到国家。", "target_word": "映射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序会把每个词映射成一个数字。", "target_word": "映射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表把每个学生映射到一个座位。", "target_word": "映射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左边的点映射到右边的点。", "target_word": "映射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑能把网址映射到正确的页面。", "target_word": "映射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个函数把一个数映射成另一个数。", "target_word": "映射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把每个字母映射到一个数字。", "target_word": "映射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把两张表里的名字一一映射了。", "target_word": "映射", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "映射了", "label": "体标"}, {"form": "映射过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把一个集合里的东西一一对应到另一个集合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c53470-eab2-4aaa-a8c7-536b79bbc5b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "映射", "is_correct": true, "explanation": "映射表示一个集合的每个成员对应到另一个集合，符合「把名字对应到号码」的语境。"}, {"text": "拼写", "is_correct": false, "explanation": "语义：拼写的对象是字词的字形，不能把名字拼写到一个号码上。"}, {"text": "赋予", "is_correct": false, "explanation": "配价：赋予要说「把某物赋予某人」，这里把「号码」当成了接受者，关系颠倒了。"}, {"text": "颁发", "is_correct": false, "explanation": "语义：颁发指发给证书、奖状等，号码不能作为颁发的对象。"}], "explanations": {"映射": "映射表示一个集合的每个成员对应到另一个集合，符合「把名字对应到号码」的语境。", "拼写": "语义：拼写的对象是字词的字形，不能把名字拼写到一个号码上。", "赋予": "配价：赋予要说「把某物赋予某人」，这里把「号码」当成了接受者，关系颠倒了。", "颁发": "语义：颁发指发给证书、奖状等，号码不能作为颁发的对象。"}, "sentence_index": 0, "correct_answer": "映射"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一边吃饭，一边映射了手机上的新闻。", "explanation": "这里应该用〈看〉。映射指两组事物之间的对应关系，不表示阅读新闻。"}, {"text": "妈妈把饺子映射到了餐桌上。", "explanation": "这里应该用〈端〉。映射指两组事物之间的对应关系，不表示把东西拿到某处。"}, {"text": "他把那段话映射给我听。", "explanation": "这里应该用〈讲〉。映射指两组事物之间的对应关系，不表示把话说给别人听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "映射", "is_correct": true, "explanation": "映射表示把网址一一对应到页面，符合「网址对应到正确页面」的语境。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除是去掉某物，网址不能被删除到页面上。"}, {"text": "访问", "is_correct": false, "explanation": "配价：访问后直接接宾语，不能用「访问到」来引出目的地。"}, {"text": "关闭", "is_correct": false, "explanation": "搭配：关闭是把东西关掉，不能说「关闭到正确的页面」。"}], "explanations": {"映射": "映射表示把网址一一对应到页面，符合「网址对应到正确页面」的语境。", "删除": "语义：删除是去掉某物，网址不能被删除到页面上。", "访问": "配价：访问后直接接宾语，不能用「访问到」来引出目的地。", "关闭": "搭配：关闭是把东西关掉，不能说「关闭到正确的页面」。"}, "sentence_index": 6, "correct_answer": "映射"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把那只杯子映射了一下，杯子就干净了。", "explanation": "这里应该用〈洗〉。映射表示对应关系，不表示清洗东西。"}, {"text": "他终于映射了那个问题的意思。", "explanation": "这里应该用〈理解〉。映射是对应关系，不用来表示人领会了一个问题的意思。"}, {"text": "老师把作业一份份映射了一遍，给每份都打了分。", "explanation": "这里应该用〈批改〉。映射是对应关系，不表示逐份审阅并打分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个程序把每个文件映射了到一个地址。", "corrected_sentence": "这个程序把每个文件映射到一个地址。", "error_description": "错误形式：映射了到。正确形式：映射到。补语「到」应紧跟在动词「映射」后面，「了」不能插在二者之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个软件能把颜色映射数字。", "corrected_sentence": "这个软件能把颜色映射到数字。", "error_description": "缺少补语“到”：“映射”后要用“到”引出对应的对象，应说“映射到数字”，不能直接接宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
