INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24502, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "宇宙观就是一个人对宇宙是什么样子的想法。", "primary_collocate": null, "pronunciation": "yǔ zhòu guān", "ipa": "y˨˩ ʈʂoʊ˥˩ kwan˥", "syllable_count": 3, "sentences": [{"text": "我的宇宙观很简单：宇宙没有边。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的宇宙观是，星星都是别的太阳。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的宇宙观是什么样的？", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我的宇宙观是天圆地方。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷给我讲了他的宇宙观。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了那部太空电影，我的宇宙观变了。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子有很特别的宇宙观。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的宇宙观里有很多神话故事。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了太空照片，我的宇宙观拓宽了。", "target_word": "宇宙观", "complexity_tier": "T3", "furigana": "yǔ zhòu guān", "sentence_source": "generated"}, {"text": "他用画画告诉大家自己的宇宙观。", "target_word": "宇宙观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种宇宙观", "label": "量词"}, {"form": "宇宙觀", "label": "繁体"}], "register": "书面", "sense_fingerprint": "一个人对宇宙样子的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba9a7b9-9fdc-48f2-ac56-de532a27db8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宇宙观", "is_correct": true, "explanation": "正确：“宇宙观”是对宇宙的看法，与后面“宇宙没有边”的说明相合。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：“食谱”指做菜的菜单，与后面“宇宙没有边”的说明不合。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：“嗓音”是人的声音特征，不能用来表达“宇宙没有边”这样的看法。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“很简单”不能用来形容“年龄”，与前后语意不合。"}], "explanations": {"宇宙观": "正确：“宇宙观”是对宇宙的看法，与后面“宇宙没有边”的说明相合。", "食谱": "语义：“食谱”指做菜的菜单，与后面“宇宙没有边”的说明不合。", "嗓音": "语义：“嗓音”是人的声音特征，不能用来表达“宇宙没有边”这样的看法。", "年龄": "搭配：“很简单”不能用来形容“年龄”，与前后语意不合。"}, "sentence_index": 0, "correct_answer": "宇宙观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的宇宙观是每天早上吃两个鸡蛋。", "explanation": "这里应该用〈习惯〉。宇宙观是对宇宙样子的想法，每天吃什么是生活习惯。"}, {"text": "周末我们去宇宙观参观。", "explanation": "这里把宇宙观当成了可以参观的地方，但它指对宇宙的根本看法，不是场所。"}, {"text": "他的宇宙观很乐观，做事很认真。", "explanation": "这里应该用〈人生观〉。宇宙观讲对宇宙的看法，谈对做事和生活的态度要说〈人生观〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宇宙观", "is_correct": true, "explanation": "正确：“宇宙观”指对宇宙的看法，与“很特别的”搭配并符合句意。"}, {"text": "跑步", "is_correct": false, "explanation": "词性：“跑步”是动词，不能受“很特别的”修饰作“有”的宾语。"}, {"text": "睡觉", "is_correct": false, "explanation": "词性：“睡觉”是动词，“有很特别的睡觉”不成立。"}, {"text": "洗澡", "is_correct": false, "explanation": "词性：“洗澡”是动词，不能作“有很特别的”的宾语。"}], "explanations": {"宇宙观": "正确：“宇宙观”指对宇宙的看法，与“很特别的”搭配并符合句意。", "跑步": "词性：“跑步”是动词，不能受“很特别的”修饰作“有”的宾语。", "睡觉": "词性：“睡觉”是动词，“有很特别的睡觉”不成立。", "洗澡": "词性：“洗澡”是动词，不能作“有很特别的”的宾语。"}, "sentence_index": 6, "correct_answer": "宇宙观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这件事的宇宙观很明确。", "explanation": "这里应该用〈观点〉。宇宙观是对宇宙的根本看法，不能用于一件具体事情的看法。"}, {"text": "他的宇宙观是：多做好事，不要怕难。", "explanation": "这里应该用〈信念〉。宇宙观讲对宇宙的看法，做好事的信条应说〈信念〉。"}, {"text": "这家饭店的宇宙观是又快又便宜。", "explanation": "这里应该用〈特点〉。宇宙观是对宇宙样子的想法，饭店的长处要说〈特点〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一条宇宙观，很简单。", "corrected_sentence": "他有一种宇宙观，很简单。", "error_description": "错误：量词“条”。宇宙观是抽象的看法，应用“种”计量，不能用“条”；正确为“一种宇宙观”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一本很独特的宇宙观。", "corrected_sentence": "她有一种很独特的宇宙观。", "error_description": "错误：量词“本”。宇宙观是抽象的看法，应用“种”计量，不能用“本”；正确为“一种很独特的宇宙观”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4a5fcee-f4e5-4f67-a4ff-0a3963ce9c65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
