INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24508, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以前发生的事。", "primary_collocate": null, "pronunciation": "wǎng shì", "ipa": "wɑŋ˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他喝着茶，慢慢讲起往事。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "提到往事，母亲的眼睛红了。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "往事已经过去，不要太难过。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老同学聚在一起，说起了小时候的往事。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首老歌让我想起很多往事。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把往事写成了一篇短文。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常给孩子们讲战争年代的往事。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "往事如烟，他早就忘了。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着旧房子，往事又回到心头。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不谈往事，只说今后的事。", "target_word": "往事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "以前发生过的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec729467-87b7-4d35-8a65-9a769ea1d165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24508, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "往事", "is_correct": true, "explanation": "往事（wǎng shì）指以前发生的事，即目标词。"}, {"text": "王室", "is_correct": false, "explanation": "wáng（第二声）与 wǎng（第三声）声调不同，意思是王家的家族。"}, {"text": "忘事", "is_correct": false, "explanation": "wàng（第四声）与 wǎng（第三声）声调不同，意思是忘记事情。"}, {"text": "晚市", "is_correct": false, "explanation": "wǎn 与 wǎng 的韵母不同（an 与 ang），意思是晚上营业的市场。"}], "explanations": {"往事": "往事（wǎng shì）指以前发生的事，即目标词。", "王室": "wáng（第二声）与 wǎng（第三声）声调不同，意思是王家的家族。", "忘事": "wàng（第四声）与 wǎng（第三声）声调不同，意思是忘记事情。", "晚市": "wǎn 与 wǎng 的韵母不同（an 与 ang），意思是晚上营业的市场。"}, "sentence_index": null, "correct_answer": "往事"}, "level_3": {"options": [{"text": "往事", "is_correct": true, "explanation": "往事指以前发生的事，可以“讲起”，符合句意。"}, {"text": "发票", "is_correct": false, "explanation": "搭配：“讲起”多指讲故事或回忆，不说“讲起发票”。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：“慢慢讲起”的对象应是故事或经历，不能是账单。"}, {"text": "螺丝", "is_correct": false, "explanation": "搭配：螺丝是零件，不是可以“慢慢讲起”的话题，与叙述往事的语境不符。"}], "explanations": {"往事": "往事指以前发生的事，可以“讲起”，符合句意。", "发票": "搭配：“讲起”多指讲故事或回忆，不说“讲起发票”。", "账单": "搭配：“慢慢讲起”的对象应是故事或经历，不能是账单。", "螺丝": "搭配：螺丝是零件，不是可以“慢慢讲起”的话题，与叙述往事的语境不符。"}, "sentence_index": 0, "correct_answer": "往事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他讲了一张往事。", "explanation": "这里应该用〈段〉。往事用“段”或“件”计量，“张”用于纸张、桌子等扁平物品。"}, {"text": "我们制定了明年的往事计划。", "explanation": "这里应该用〈未来〉。往事指以前发生的事，不能用来修饰尚未发生的计划。"}, {"text": "他吃了一顿往事。", "explanation": "这里应该用〈饭〉。“吃”的对象应是食物，往事不能被吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "往事", "is_correct": true, "explanation": "往事指以前发生的事，“战争年代的往事”指那个时代的事，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "语义：战争年代没有手机，“战争年代的手机”与时代不符。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：战争年代还没有电脑，“战争年代的电脑”与时代不符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是身体的数据，不能讲给孩子听，与“往事”无关。"}], "explanations": {"往事": "往事指以前发生的事，“战争年代的往事”指那个时代的事，符合句意。", "手机": "语义：战争年代没有手机，“战争年代的手机”与时代不符。", "电脑": "语义：战争年代还没有电脑，“战争年代的电脑”与时代不符。", "身高": "语义：身高是身体的数据，不能讲给孩子听，与“往事”无关。"}, "sentence_index": 6, "correct_answer": "往事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明年我要去实现很多往事。", "explanation": "这里应该用〈愿望〉。往事指以前发生的事，已经过去，不能“去实现”。"}, {"text": "那位老人是我的往事，每天陪我散步。", "explanation": "这里应该用〈朋友〉。往事指已经过去的事，不指可以陪伴的人。"}, {"text": "他喝了一杯往事，觉得很苦。", "explanation": "这里应该用〈茶〉。“喝”的对象应是饮品，往事不能被喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跟我讲了一本往事。", "corrected_sentence": "他跟我讲了一段往事。", "error_description": "“往事”指一件件事情，应用量词“段”，“本”只用于书籍，说“一本往事”是量词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷常给孩子们讲那些往事们。", "corrected_sentence": "爷爷常给孩子们讲那些往事。", "error_description": "“往事”是抽象名词，前面已有“那些”表示复数，不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
