INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24510, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时空就是时间和空间，我们说一个事情发生在什么时候、什么地方。", "primary_collocate": null, "pronunciation": "shí kōng", "ipa": "ʂɨ˧˥ kʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这部小说的时空很独特，读起来很新鲜。", "target_word": "时空", "complexity_tier": "T3", "furigana": "shí kōng", "sentence_source": "generated"}, {"text": "这部小说不断切换时空，读起来很有意思。", "target_word": "时空", "complexity_tier": "T3", "furigana": "shí kōng", "sentence_source": "generated"}, {"text": "这件事发生的时空很特别。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史课上，老师先讲当时的时空。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们生活在同一个时空里。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了还原真相，警察反复核对事件的时空。", "target_word": "时空", "complexity_tier": "T3", "furigana": "shí kōng", "sentence_source": "generated"}, {"text": "这部小说把时空定在一百年前的一座小城。", "target_word": "时空", "complexity_tier": "T3", "furigana": "shí kōng", "sentence_source": "generated"}, {"text": "时空不同，故事也不同。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问，时空是什么意思？", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的人穿越了时空。", "target_word": "时空", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "时空观", "label": "复合"}], "register": "书面", "sense_fingerprint": "事情发生的时候和地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '344206f6-976f-4874-8f0d-c04e78e16151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24510, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时空", "is_correct": true, "explanation": "正确：时空 shí kōng，指事情发生的时候和地方。"}, {"text": "失控", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，kòng（第四声）与 kōng（第一声）声调不同，意思是失去控制。"}, {"text": "时钟", "is_correct": false, "explanation": "zhōng 与 kōng 只有声母不同（zh 与 k），意思是计时的钟表。"}, {"text": "石工", "is_correct": false, "explanation": "gōng 与 kōng 只有声母不同（g 与 k），意思是石匠。"}, {"text": "实控", "is_correct": false, "explanation": "kòng（第四声）与 kōng（第一声）声调不同，意思是实际控制。"}], "explanations": {"时空": "正确：时空 shí kōng，指事情发生的时候和地方。", "失控": "shī（第一声）与 shí（第二声）声调不同，kòng（第四声）与 kōng（第一声）声调不同，意思是失去控制。", "时钟": "zhōng 与 kōng 只有声母不同（zh 与 k），意思是计时的钟表。", "石工": "gōng 与 kōng 只有声母不同（g 与 k），意思是石匠。", "实控": "kòng（第四声）与 kōng（第一声）声调不同，意思是实际控制。"}, "sentence_index": null, "correct_answer": "时空"}, "level_3": {"options": [{"text": "时空", "is_correct": true, "explanation": "正确：“这部小说的时空”指故事发生的时候和地方，符合语境。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是数字指标，不能用来形容小说的特点。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重用于人或动物，不能用来形容一部小说。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“很独特”一般不修饰“音量”，读起来不通。"}], "explanations": {"时空": "正确：“这部小说的时空”指故事发生的时候和地方，符合语境。", "价格": "语义：价格是数字指标，不能用来形容小说的特点。", "体重": "体貌：体重用于人或动物，不能用来形容一部小说。", "音量": "搭配：“很独特”一般不修饰“音量”，读起来不通。"}, "sentence_index": 0, "correct_answer": "时空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们约好的时空是明天早上。", "explanation": "这里应该用〈时间〉。时空指时间和地点的合称，只说时刻时应用“时间”。"}, {"text": "这个小村的时空很偏僻，很少有人来。", "explanation": "这里应该用〈地点〉。时空指事情发生的时候和地方，只说位置偏僻时应用地点。"}, {"text": "这个房间的时空很大，可以放三张床。", "explanation": "这里应该用〈空间〉。时空指时间和空间的合称，只说房间大小时应用“空间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时空", "is_correct": true, "explanation": "正确：“把时空定在”表示确定故事发生的时候和地方，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能被“定在”某个时间和地点。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”不能与“定在一百年前”构成合理搭配。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道与故事发生的时间和地点无关。"}], "explanations": {"时空": "正确：“把时空定在”表示确定故事发生的时候和地方，符合语境。", "颜色": "语义：颜色不能被“定在”某个时间和地点。", "体积": "搭配：“体积”不能与“定在一百年前”构成合理搭配。", "味道": "语义：味道与故事发生的时间和地点无关。"}, "sentence_index": 6, "correct_answer": "时空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们等了那段时空很久，还是没有结果。", "explanation": "这里应该用〈时间〉。时空指事情发生的时候和地方，只表示一段时长时应用“时间”。"}, {"text": "这所学校的时空很好，学生很喜欢。", "explanation": "这里应该用〈环境〉。时空不用来评价一个地方的好坏。"}, {"text": "这个时空很干净，大家都愿意来。", "explanation": "这里应该用〈场所〉。时空指时候和地方的整体，不用来描述场所干净与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部小说有一座奇特的时空。", "corrected_sentence": "这部小说有一个奇特的时空。", "error_description": "量词错误：“时空”应用量词“个”，不能用“座”（多用于山、城等大型物体）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们回到了很时空。", "corrected_sentence": "他们回到了当年的时空。", "error_description": "副词错误：「很」不能修饰名词「时空」，“回到了很时空”错误，应改为“回到了当年的时空”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
