INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24512, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "听别人说话的人。", "primary_collocate": null, "pronunciation": "tīng zhě", "ipa": "tʰiŋ˥ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "她很会说话，也是个耐心的听者。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台下的听者越来越多。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "讲课的人应该关心听者的感受。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱说话，却是最好的听者。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听者听不懂时，说者要讲慢一点。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台收到了许多听者的来信。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对朋友来说，我只是个安静的听者。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听者们都很喜欢这个故事。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子需要一位愿意倾听的听者。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "讲完故事，听者提了几个问题。", "target_word": "听者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聽者", "label": "繁体"}], "register": "书面", "sense_fingerprint": "听别人说话的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec729467-87b7-4d35-8a65-9a769ea1d165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24512, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听者", "is_correct": true, "explanation": "听者指听别人说话的人。“也”表示她除了会说，还能耐心地听，符合句意。"}, {"text": "沉默者", "is_correct": false, "explanation": "语义：“很会说话”与“沉默者”相反，句意矛盾。"}, {"text": "木偶", "is_correct": false, "explanation": "搭配：“耐心”形容有心理状态的人，不能修饰木偶。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像既不会说话，也没有耐心，与句意冲突。"}], "explanations": {"听者": "听者指听别人说话的人。“也”表示她除了会说，还能耐心地听，符合句意。", "沉默者": "语义：“很会说话”与“沉默者”相反，句意矛盾。", "木偶": "搭配：“耐心”形容有心理状态的人，不能修饰木偶。", "雕像": "语义：雕像既不会说话，也没有耐心，与句意冲突。"}, "sentence_index": 0, "correct_answer": "听者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "景点里的听者很多，大家都在拍照。", "explanation": "这里应该用〈游客〉。听者指听别人说话的人，逛景点的人应说游客。"}, {"text": "这辆公交车上的听者很多，大家都在看手机。", "explanation": "这里应该用〈乘客〉。听者指听别人说话的人，乘坐公交车的人应说乘客。"}, {"text": "这部电影的听者很多，票都卖光了。", "explanation": "这里应该用〈观众〉。听者指听别人说话的人，看电影的人应说观众。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听者", "is_correct": true, "explanation": "听者指听别人说话的人，“只是个安静的听者”说明我不多说话、只是倾听，符合句意。"}, {"text": "喧哗者", "is_correct": false, "explanation": "语义：“喧哗者”指大声吵闹的人，与“安静”相矛盾。"}, {"text": "鼓手", "is_correct": false, "explanation": "语义：鼓手常打出响亮的节奏，与“安静”相反。"}, {"text": "闹事者", "is_correct": false, "explanation": "搭配：“安静的”描述性情或状态，“闹事者”指挑起事端的人，两者搭配不当。"}], "explanations": {"听者": "听者指听别人说话的人，“只是个安静的听者”说明我不多说话、只是倾听，符合句意。", "喧哗者": "语义：“喧哗者”指大声吵闹的人，与“安静”相矛盾。", "鼓手": "语义：鼓手常打出响亮的节奏，与“安静”相反。", "闹事者": "搭配：“安静的”描述性情或状态，“闹事者”指挑起事端的人，两者搭配不当。"}, "sentence_index": 6, "correct_answer": "听者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院里的听者越来越多，大家都在排队。", "explanation": "这里应该用〈病人〉。听者指听别人说话的人，就医的人应说病人。"}, {"text": "街上的听者一个接一个地走过，都在赶路。", "explanation": "这里应该用〈行人〉。听者指听别人说话的人，在街上走路的人应说行人。"}, {"text": "球场里的听者个个激动，一直在大声呐喊。", "explanation": "这里应该用〈球迷〉。听者指听别人说话的人，在球场呐喊助威的人应说球迷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只认真的听者。", "corrected_sentence": "他是一位认真的听者。", "error_description": "量词错误：“听者”指人，应用量词“位”或“个”，不能用“只”。正确说法是“一位认真的听者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是一位很耐心听者。", "corrected_sentence": "她是一位很耐心的听者。", "error_description": "漏掉“的”：“很耐心的”是修饰“听者”的定语，二者之间要用“的”，应说“很耐心的听者”，不能说“很耐心听者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24514, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24514, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24514, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "话说出来就有神奇的力量。", "primary_collocate": null, "pronunciation": "yán líng", "ipa": "jɛn˧˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "古人相信言灵，所以不随便说坏话。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，好话有言灵，说出来就会成真。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本古代传说中也有言灵的说法。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他相信言灵，每天早上都对自己说“我可以”。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人觉得过年要说吉利话，因为有言灵。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怕言灵应验，所以不敢说不好的话。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个传说讲的是言灵怎样改变一个人的命运。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我不懂什么是言灵，只觉得话很重要。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，言灵的意思是话说出来就有力量。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人觉得言灵只是迷信，有人却深信不疑。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "言靈", "label": "繁体"}], "register": "书面", "sense_fingerprint": "相信说出口的话会成真的神奇力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec729467-87b7-4d35-8a65-9a769ea1d165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言灵", "is_correct": true, "explanation": "“言灵”指话语的神秘力量，正是古人“不随便说坏话”的原因，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与说话无关，不能成为“不随便说坏话”的理由。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头与说话没有关系，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“相信”后面接的是信念或观念，“桌子”不能作为相信的内容。"}], "explanations": {"言灵": "“言灵”指话语的神秘力量，正是古人“不随便说坏话”的原因，符合句意。", "颜色": "语义：颜色与说话无关，不能成为“不随便说坏话”的理由。", "石头": "语义：石头与说话没有关系，句意不通。", "桌子": "配价：“相信”后面接的是信念或观念，“桌子”不能作为相信的内容。"}, "sentence_index": 0, "correct_answer": "言灵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这句言灵教我们要诚实。", "explanation": "这里应该用〈格言〉。言灵指话语本身的神秘力量，有教育意义的句子应说格言。"}, {"text": "远处传来一阵奇怪的言灵，把大家都吓醒了。", "explanation": "这里应该用〈声音〉。言灵指话语的神秘力量，不是耳朵能听见的声音。"}, {"text": "她从包里拿出一个言灵，送给了孩子。", "explanation": "这里应该用〈礼物〉。言灵指话语的神秘力量，不是可以拿出来送人的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言灵", "is_correct": true, "explanation": "“言灵”指话语的神秘力量，“传说讲的是言灵怎样改变命运”符合句意。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间词，不能作为“改变一个人命运”的主体，句意不通。"}, {"text": "标点", "is_correct": false, "explanation": "语义：“标点”是书写符号，不能改变人的命运，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“改变一个人的命运”需要有作用力的主体，“窗户”不能作为主语。"}], "explanations": {"言灵": "“言灵”指话语的神秘力量，“传说讲的是言灵怎样改变命运”符合句意。", "星期": "语义：“星期”是时间词，不能作为“改变一个人命运”的主体，句意不通。", "标点": "语义：“标点”是书写符号，不能改变人的命运，句意不通。", "窗户": "搭配：“改变一个人的命运”需要有作用力的主体，“窗户”不能作为主语。"}, "sentence_index": 6, "correct_answer": "言灵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村子里突然出现了一个言灵，吓坏了大家。", "explanation": "这里应该用〈妖怪〉。言灵指话语的神秘力量，不是会行动的生物。"}, {"text": "人们向言灵祈求平安。", "explanation": "这里应该用〈神明〉。言灵指话语的神秘力量，不是有意志的神明，不能向它祈求。"}, {"text": "他小心地保管着这件言灵。", "explanation": "这里应该用〈宝物〉。言灵是话语的力量，不是可以保管的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她给言灵很感兴趣。", "corrected_sentence": "她对言灵很感兴趣。", "error_description": "介词错误：表示对某事物有兴趣，要用“对……感兴趣”，应说“对言灵很感兴趣”，不能用“给”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书中有一段很神秘言灵描写。", "corrected_sentence": "书中有一段很神秘的言灵描写。", "error_description": "漏掉“的”：“很神秘”修饰“言灵描写”时中间要加“的”。正确说法是“很神秘的言灵描写”，漏掉“的”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64f8093b-b9e7-4f42-aa8e-26716626d0e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失去", "is_correct": true, "explanation": "正确：“失去”与“获得”是反义词，指不再拥有想要的东西。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”与“获得”的任何义项都没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”与“获得”没有反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "无关：“观看”与“获得”没有反义关系。"}], "correct_answer": "失去", "explanations": {"失去": "正确：“失去”与“获得”是反义词，指不再拥有想要的东西。", "思考": "无关：“思考”与“获得”的任何义项都没有反义关系。", "散步": "无关：“散步”与“获得”没有反义关系。", "观看": "无关：“观看”与“获得”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失去", "is_correct": true, "explanation": "正确：“失去”与“获得”是反义词，指不再拥有想要的东西。"}, {"text": "跑步", "is_correct": false, "explanation": "无关：“跑步”与“获得”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：“睡觉”与“获得”没有反义关系。"}, {"text": "煮饭", "is_correct": false, "explanation": "无关：“煮饭”与“获得”没有反义关系。"}], "correct_answer": "失去", "explanations": {"失去": "正确：“失去”与“获得”是反义词，指不再拥有想要的东西。", "跑步": "无关：“跑步”与“获得”没有反义关系。", "睡觉": "无关：“睡觉”与“获得”没有反义关系。", "煮饭": "无关：“煮饭”与“获得”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得到想要的东西。", "primary_collocate": null, "pronunciation": "huò dé", "ipa": "xu̯ɔ˥˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他一直想获得那份工作。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王努力学习，想获得好成绩。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望获得一次去中国的机会。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了获得他的信任，她做了很多事。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位选手凭借努力获得了金牌。", "target_word": "获得", "complexity_tier": "T3", "furigana": "zhè wèi xuǎnshǒu píngjiè nǔlì huòdé le jīnpái", "sentence_source": "generated"}, {"text": "他很想获得老师的同意。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她终于获得了想要的书。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想获得比赛的第一名。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想获得更多的时间学中文。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等了很久，终于获得了那张票。", "target_word": "获得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "獲得", "label": "繁体"}, {"form": "获得了", "label": "体标"}, {"form": "获得过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "经过努力或等待得到自己想要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '666c4209-724f-4fd6-b02e-7caaa973cf90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "获得", "is_correct": true, "explanation": "正确：“想获得”表示希望得到，与“那份工作”搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃那份工作”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱那份工作”。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，后面不能直接带宾语“那份工作”。"}], "explanations": {"获得": "正确：“想获得”表示希望得到，与“那份工作”搭配自然。", "吃": "搭配：“吃”的对象是食物，不能说“吃那份工作”。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱那份工作”。", "笑": "配价：“笑”是不及物动词，后面不能直接带宾语“那份工作”。"}, "sentence_index": 0, "correct_answer": "获得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天获得了一场误会。", "explanation": "这里应该用〈发生〉。“误会”是意外发生的事，“获得”只用于得到想要的东西。"}, {"text": "他昨天获得了感冒。", "explanation": "这里应该用〈患上〉。“获得”指得到想要的东西，不能用来说染上疾病，要说“患上感冒”。"}, {"text": "他昨天获得了一顿批评。", "explanation": "这里应该用〈挨〉。“获得”指得到想要的东西，“批评”是不想要的事，应说“挨一顿批评”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "获得", "is_correct": true, "explanation": "正确：“终于获得了”表示经过等待后终于得到想要的书。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说“喝想要的书”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带宾语“想要的书”。"}, {"text": "吞", "is_correct": false, "explanation": "搭配：“吞”多用于食物或药物，不能说“吞想要的书”。"}], "explanations": {"获得": "正确：“终于获得了”表示经过等待后终于得到想要的书。", "喝": "搭配：“喝”的对象是饮品，不能说“喝想要的书”。", "哭": "配价：“哭”是不及物动词，不能带宾语“想要的书”。", "吞": "搭配：“吞”多用于食物或药物，不能说“吞想要的书”。"}, "sentence_index": 6, "correct_answer": "获得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从楼梯上获得了一跤。", "explanation": "这里应该用〈摔〉。“摔一跤”是意外遭遇，“获得”只用于想要的东西。"}, {"text": "这场大火之后，村子获得了一片废墟。", "explanation": "这里应该用〈留下〉。“废墟”是大火留下的结果，“获得”只用于得到想要的东西。"}, {"text": "他这次获得了一场大麻烦。", "explanation": "这里应该用〈惹〉。“惹”指引来不好的事，“获得”只用于想要的好东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们想获得了更多的支持。", "corrected_sentence": "我们想获得更多的支持。", "error_description": "错误形式：“想获得了”。“想”表示意愿、指向未来，不能与表示完成的“了”连用；正确形式为“想获得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于获得着成功。", "corrected_sentence": "他们终于获得了成功。", "error_description": "错误形式：“终于获得着”。“终于”表示动作最终完成，与表示持续的“着”相矛盾；正确形式为“终于获得了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "散步", "is_correct": false, "explanation": "与“确认”无反义关系：“散步”指慢慢走路，与确认的意思无关。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“确认”无反义关系：“唱歌”是发声歌唱，与核实、肯定事实无关。"}, {"text": "旅行", "is_correct": false, "explanation": "与“确认”无反义关系：“旅行”指到外地游览，与确认的意思不相对。"}, {"text": "否认", "is_correct": true, "explanation": "反义：“否认”表示不承认、不肯定，与“确认”意思相对。"}], "correct_answer": "否认", "explanations": {"散步": "与“确认”无反义关系：“散步”指慢慢走路，与确认的意思无关。", "唱歌": "与“确认”无反义关系：“唱歌”是发声歌唱，与核实、肯定事实无关。", "旅行": "与“确认”无反义关系：“旅行”指到外地游览，与确认的意思不相对。", "否认": "反义：“否认”表示不承认、不肯定，与“确认”意思相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跑步", "is_correct": false, "explanation": "与“确认”无反义关系：“跑步”指快速跑动，与确认的意思无关。"}, {"text": "游泳", "is_correct": false, "explanation": "与“确认”无反义关系：“游泳”指在水中活动，与确认的意思不相对。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“确认”无反义关系：“睡觉”指休息入睡，与核实、肯定事实无关。"}, {"text": "否认", "is_correct": true, "explanation": "反义：“否认”表示不承认、不肯定，与“确认”意思相对。"}], "correct_answer": "否认", "explanations": {"跑步": "与“确认”无反义关系：“跑步”指快速跑动，与确认的意思无关。", "游泳": "与“确认”无反义关系：“游泳”指在水中活动，与确认的意思不相对。", "睡觉": "与“确认”无反义关系：“睡觉”指休息入睡，与核实、肯定事实无关。", "否认": "反义：“否认”表示不承认、不肯定，与“确认”意思相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示肯定、确定，没有疑问。", "primary_collocate": null, "pronunciation": "què rèn", "ipa": "tɕʰɥe˥˩ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "请你再确认一下时间。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生确认他没有生病。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经确认了明天的飞机票。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "订房间以后，酒店会给你打电话确认。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们确认一下名字对不对。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不太确定，想再确认一次。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察确认了那个人的身份。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先确认地址，再寄东西。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经确认今天会来，我们不用再等了。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给朋友发了短信，请他确认收到了。", "target_word": "确认", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "确认了", "label": "体标"}, {"form": "确认过", "label": "体标"}, {"form": "确认书", "label": "复合"}, {"form": "確認", "label": "繁体"}], "register": "中性", "sense_fingerprint": "确认：把情况弄清楚并肯定、确定下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25d347d6-cd46-4fd0-a1a8-e1f8b84db37e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "确认", "is_correct": true, "explanation": "正确：“请你再确认一下时间”中，“确认”表示核对并肯定，符合句意。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：“庆祝”后接节日、胜利等，不能接“时间”。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”后接食物、饮品，不能接“时间”。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：请人“再忘记一下时间”没有意义，与句子的请求不合。"}], "explanations": {"确认": "正确：“请你再确认一下时间”中，“确认”表示核对并肯定，符合句意。", "庆祝": "搭配：“庆祝”后接节日、胜利等，不能接“时间”。", "品尝": "搭配：“品尝”后接食物、饮品，不能接“时间”。", "忘记": "语义：请人“再忘记一下时间”没有意义，与句子的请求不合。"}, "sentence_index": 0, "correct_answer": "确认"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在学校确认了一个好朋友。", "explanation": "这里应该用〈认识〉。确认是把事情弄清楚并肯定下来，结识人要用认识。"}, {"text": "我在超市确认了一个西瓜。", "explanation": "这里应该用〈挑选〉。确认不用于挑选物品，选西瓜要用挑选。"}, {"text": "妈妈每天确认生病的爷爷。", "explanation": "这里应该用〈照顾〉。确认是核实、肯定事实，照料病人要用照顾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "确认", "is_correct": true, "explanation": "正确：“警察确认了那个人的身份”中，“确认”表示核实并肯定，符合句意。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”后接场所、展览等，不能接“身份”。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植指栽培植物，与警察核实人的身份无关。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞是身体的动作，与核实身份无关，句子不通。"}], "explanations": {"确认": "正确：“警察确认了那个人的身份”中，“确认”表示核实并肯定，符合句意。", "参观": "搭配：“参观”后接场所、展览等，不能接“身份”。", "种植": "语义：种植指栽培植物，与警察核实人的身份无关。", "跳舞": "语义：跳舞是身体的动作，与核实身份无关，句子不通。"}, "sentence_index": 6, "correct_answer": "确认"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我给朋友确认了一本书。", "explanation": "这里应该用〈寄〉。确认是核实、肯定，给朋友寄东西要用寄。"}, {"text": "妈妈确认了很多衣服。", "explanation": "这里应该用〈洗〉。确认不用于清洗衣物，洗衣服要用洗。"}, {"text": "我确认了一杯牛奶。", "explanation": "这里应该用〈喝〉。确认指肯定事实，喝牛奶要用喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你打电话确认了航班。", "corrected_sentence": "请你打电话确认一下航班。", "error_description": "体标错误：祈使句“请你……”不能带表示完成的“了”，应把“了”改为“一下”，正确说法是「请你打电话确认一下航班」，“一下”表示稍微确认一下。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经确认过这个订单过。", "corrected_sentence": "我已经确认过这个订单了。", "error_description": "体标错误：“过”表示动作的经历，只用一次，放在动词“确认”后；句末表示完成的应是“了”，不能用“过”。应把句末的“过”改为“了”，正确说法是「我已经确认过这个订单了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6a508f-426a-42aa-b89b-6dcb0bf909c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
