INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24522, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "故事里发生的事情。", "primary_collocate": null, "pronunciation": "qíng jié", "ipa": "tɕʰiŋ˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这个电视剧的情节很有意思，我天天都看。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里有一个情节让我特别难忘。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部动画片的情节很简单，小孩也看得懂。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影最后的情节谁也想不到。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢情节紧张的故事。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书里的情节讲给朋友听。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的情节有点儿奇怪。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完电影，我还记得里面的情节。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者在书里写了很多有趣的情节。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的情节像一部电影。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "段", "label": "量词"}, {"form": "情節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小说、电影等故事里发生的事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b69fe6f-45ff-4aa8-b887-4f71b2511eeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24522, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "门票", "is_correct": false, "explanation": "语义：门票是凭证，不是可以“有意思”的内容，电视剧的门票有意思说不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是钱数，不能有“有意思”的特点，“这个电视剧的价格很有意思”说不通。"}, {"text": "情节", "is_correct": true, "explanation": "正确：“这个电视剧的情节很有意思”指剧中事件的发展，“有意思”与之搭配，合理。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体征，电视剧不能有身高，句子不成立。"}], "explanations": {"门票": "语义：门票是凭证，不是可以“有意思”的内容，电视剧的门票有意思说不通。", "价格": "语义：价格是钱数，不能有“有意思”的特点，“这个电视剧的价格很有意思”说不通。", "情节": "正确：“这个电视剧的情节很有意思”指剧中事件的发展，“有意思”与之搭配，合理。", "身高": "体貌：身高是人的体征，电视剧不能有身高，句子不成立。"}, "sentence_index": 0, "correct_answer": "情节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部纪录片记录了蚂蚁的生长情节。", "explanation": "这里应该用〈过程〉。“过程”指事物发展变化的阶段，自然现象说“生长过程”；“情节”只用于故事或影视作品中的事件。"}, {"text": "他们之间的情节很深，多年都没有变。", "explanation": "这里应该用〈情谊〉。“情谊”指朋友、亲人之间的感情，可以说“情谊很深”；“情节”指故事中发生的事件，不能用来形容感情的深浅。"}, {"text": "这部电影有一颗精彩的情节。", "explanation": "这里应该用“段”或“个”。“颗”用于圆粒状的东西，不能用来计量“情节”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "车费", "is_correct": false, "explanation": "语义：车费是乘车的钱，与故事无关，“这个故事的车费有点儿奇怪”说不通。"}, {"text": "情节", "is_correct": true, "explanation": "正确：“这个故事的情节有点儿奇怪”指故事中的事件有些怪异，搭配自然。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人的体征，不能用于故事，句子没有合理的意思。"}, {"text": "门牌", "is_correct": false, "explanation": "语义：门牌是房屋的标识，不是故事的组成部分，“这个故事的门牌”不成立。"}], "explanations": {"车费": "语义：车费是乘车的钱，与故事无关，“这个故事的车费有点儿奇怪”说不通。", "情节": "正确：“这个故事的情节有点儿奇怪”指故事中的事件有些怪异，搭配自然。", "体重": "体貌：体重是人的体征，不能用于故事，句子没有合理的意思。", "门牌": "语义：门牌是房屋的标识，不是故事的组成部分，“这个故事的门牌”不成立。"}, "sentence_index": 6, "correct_answer": "情节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部动画的情节很漂亮。", "explanation": "这里应该用〈画面〉。“漂亮”形容外观和画面，“情节”不用“漂亮”来形容。"}, {"text": "这首歌的情节很好听。", "explanation": "这里应该用〈音乐〉。“好听”形容声音，“情节”不能用“好听”来形容。"}, {"text": "这个游戏有一台精彩的情节。", "explanation": "这里应该用“段”或“个”。“台”用于机器等物品，不能用来计量“情节”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影的一枚情节让我猜了很久。", "corrected_sentence": "这部电影的情节让我猜了很久。", "error_description": "错误在“一枚情节”。“枚”用于硬币、奖章等小件，不能用来计量“情节”；应说“一段”或“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部剧的一对情节很紧凑，观众一直在猜。", "corrected_sentence": "这部剧的情节很紧凑，观众一直在猜。", "error_description": "错误在“一对情节”。“对”用于成双成对的东西，不能用来计量“情节”；去掉数量词即可，说“这部剧的情节很紧凑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
