INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24528, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事物一直存在，没有消失。", "primary_collocate": null, "pronunciation": "cún xù", "ipa": "tsʰwən˧˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "这座古城存续了上千年。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老习惯在村里一直存续着。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家学校已经存续了很多年。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有保护环境，生命才能存续。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日在我们家乡存续至今。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水干了，这片湿地很难存续。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家族的故事靠口口相传存续下来。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小剧团还在存续吗？", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们希望这家老店能长久存续。", "target_word": "存续", "complexity_tier": "T3", "furigana": "cún xù", "sentence_source": "generated"}, {"text": "这种传统存续了几百年。", "target_word": "存续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "存续了", "label": "体标"}, {"form": "存续着", "label": "体标"}, {"form": "存续期", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物一直存在下去，没有消失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '344206f6-976f-4874-8f0d-c04e78e16151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存续", "is_correct": true, "explanation": "正确：“存续了上千年”指古城持续存在，符合语境。"}, {"text": "旅行", "is_correct": false, "explanation": "语义：古城不会旅行，“旅行”的主语必须是人。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：古城不会咳嗽，这个动作与建筑无关。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”要求有生命的主体，不能以古城作主语。"}], "explanations": {"存续": "正确：“存续了上千年”指古城持续存在，符合语境。", "旅行": "语义：古城不会旅行，“旅行”的主语必须是人。", "咳嗽": "语义：古城不会咳嗽，这个动作与建筑无关。", "游泳": "配价：“游泳”要求有生命的主体，不能以古城作主语。"}, "sentence_index": 0, "correct_answer": "存续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场演出因为停电存续了。", "explanation": "这里应该用〈中断〉。存续表示持续存在、没有中断，与“中断”意思相反。"}, {"text": "他每周存续一次。", "explanation": "这里应该用〈进行〉。存续表示事物持续存在，不能表示动作的次数。"}, {"text": "他的计划在一夜之间存续了。", "explanation": "这里应该用〈破灭〉。存续表示持续存在，不表示事物一下子消失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存续", "is_correct": true, "explanation": "正确：“靠口口相传存续下来”指故事持续保存下来，符合语境。"}, {"text": "出版", "is_correct": false, "explanation": "语义：口口相传是口头传播，与“出版”无关。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修与口头流传的故事无关，说不通。"}, {"text": "销售", "is_correct": false, "explanation": "搭配：“销售”指交易，不能与“口口相传”搭配。"}], "explanations": {"存续": "正确：“靠口口相传存续下来”指故事持续保存下来，符合语境。", "出版": "语义：口口相传是口头传播，与“出版”无关。", "装修": "语义：装修与口头流传的故事无关，说不通。", "销售": "搭配：“销售”指交易，不能与“口口相传”搭配。"}, "sentence_index": 6, "correct_answer": "存续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯突然存续了。", "explanation": "这里应该用〈熄灭〉。存续表示事物持续存在，不能表示光亮突然消失。"}, {"text": "他每月存续两次。", "explanation": "这里应该用〈进行〉。存续表示持续存在，不能表示动作的次数。"}, {"text": "这个节目的录制在中途存续了。", "explanation": "这里应该用〈中断〉。存续表示持续存在、没有中断，与“中断”意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种手艺在村里存续出来了。", "corrected_sentence": "这种手艺在村里存续下来了。", "error_description": "补语错误：表示事物延续保存下来应说“存续下来”，“出来”表示由内向外，不能与“存续”搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小剧团至今存续了着。", "corrected_sentence": "这个小剧团至今存续着。", "error_description": "体标错误：“了”与“着”不能连用，“存续了着”错误，删去“了”，应说“至今存续着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
