INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24530, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "打仗，就是两个国家或一群人打架。", "primary_collocate": null, "pronunciation": "zhàn", "ipa": "ʈʂan˥˩", "syllable_count": 1, "sentences": [{"text": "这一战，两个国家打得很凶。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们赢了那一战，大家都很高兴。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷说，那一战他一点也不怕。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是他参加的第一战。", "target_word": "战", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那一战很苦，可是我们没有走。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一战输了，我们明天再来。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们问爷爷那一战是怎么打的。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一战是为了水才打的。", "target_word": "战", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都不想再有这样的一战。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那一战以后，小城安静了很多。", "target_word": "战", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "战争", "label": "复合"}, {"form": "战斗", "label": "复合"}, {"form": "戰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个国家或一群人打仗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b69fe6f-45ff-4aa8-b887-4f71b2511eeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24530, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "战", "is_correct": true, "explanation": "正确答案：听到的是“战”，意思是打仗。"}, {"text": "占", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，“占”是占据的意思。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，“展”是展开的意思。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 zhàn 声母不同（z 与 zh），“赞”是赞美的意思。"}, {"text": "镇", "is_correct": false, "explanation": "zhèn（第四声）与 zhàn 只差韵母（en 与 an），“镇”是城镇的意思。"}], "explanations": {"战": "正确答案：听到的是“战”，意思是打仗。", "占": "zhān（第一声）与 zhàn（第四声）声调不同，“占”是占据的意思。", "展": "zhǎn（第三声）与 zhàn（第四声）声调不同，“展”是展开的意思。", "赞": "zàn 与 zhàn 声母不同（z 与 zh），“赞”是赞美的意思。", "镇": "zhèn（第四声）与 zhàn 只差韵母（en 与 an），“镇”是城镇的意思。"}, "sentence_index": null, "correct_answer": "战"}, "level_3": {"options": [{"text": "战", "is_correct": true, "explanation": "正确：“这一战”指两个国家之间的这场战斗，与“打得很凶”相符。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“这一饭”指一顿饭，与两个国家打仗的语境矛盾。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：“一”后面的量词应是“双”，且鞋与“打得很凶”的语境无关。"}, {"text": "瓶", "is_correct": false, "explanation": "语义：瓶子与两个国家打仗的语境没有关系，句意不通。"}], "explanations": {"战": "正确：“这一战”指两个国家之间的这场战斗，与“打得很凶”相符。", "饭": "语义：“这一饭”指一顿饭，与两个国家打仗的语境矛盾。", "鞋": "搭配：“一”后面的量词应是“双”，且鞋与“打得很凶”的语境无关。", "瓶": "语义：瓶子与两个国家打仗的语境没有关系，句意不通。"}, "sentence_index": 0, "correct_answer": "战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他犯了一次战，很后悔。", "explanation": "这里应该用〈错误〉。〈战〉指打仗，不能说“犯”。"}, {"text": "他是一位著名的战。", "explanation": "这里应该用〈将军〉。〈战〉指战斗，不指人，不能说“一位著名的战”。"}, {"text": "他把书包战在桌子上。", "explanation": "这里应该用〈放〉。〈战〉是打仗的意思，不能表示把东西摆在某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24530, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "战", "is_correct": true, "explanation": "正确答案：听到的是“战”，意思是打仗。"}, {"text": "沾", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，“沾”是沾上、浸湿的意思。"}, {"text": "盏", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，“盏”是量词，指灯。"}, {"text": "掌", "is_correct": false, "explanation": "zhǎng 与 zhàn 韵母与声调都不同（ang 与 an），“掌”是手掌的意思。"}, {"text": "暂", "is_correct": false, "explanation": "zàn 与 zhàn 声母不同（z 与 zh），“暂”是暂时的意思。"}], "explanations": {"战": "正确答案：听到的是“战”，意思是打仗。", "沾": "zhān（第一声）与 zhàn（第四声）声调不同，“沾”是沾上、浸湿的意思。", "盏": "zhǎn（第三声）与 zhàn（第四声）声调不同，“盏”是量词，指灯。", "掌": "zhǎng 与 zhàn 韵母与声调都不同（ang 与 an），“掌”是手掌的意思。", "暂": "zàn 与 zhàn 声母不同（z 与 zh），“暂”是暂时的意思。"}, "sentence_index": null, "correct_answer": "战"}, "level_3": {"options": [{"text": "战", "is_correct": true, "explanation": "正确：“那一战是怎么打的”问的是那场战斗的经过，符合语境。"}, {"text": "湖", "is_correct": false, "explanation": "语义：湖不是可以“打”的事件，“那一湖是怎么打的”句意不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能被“打”，与“怎么打的”的语境不符。"}, {"text": "琴", "is_correct": false, "explanation": "搭配：琴应用量词“把”或“架”，不能说“那一琴”。"}], "explanations": {"战": "正确：“那一战是怎么打的”问的是那场战斗的经过，符合语境。", "湖": "语义：湖不是可以“打”的事件，“那一湖是怎么打的”句意不通。", "书": "语义：书不能被“打”，与“怎么打的”的语境不符。", "琴": "搭配：琴应用量词“把”或“架”，不能说“那一琴”。"}, "sentence_index": 6, "correct_answer": "战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们吃了战，就出发了。", "explanation": "这里应该用〈午饭〉。〈战〉指打仗，不能用“吃”。"}, {"text": "这一战很好听。", "explanation": "这里应该用〈乐曲〉。“好听”形容声音或音乐，战斗不能“好听”。"}, {"text": "请把战关上。", "explanation": "这里应该用〈门〉。〈战〉指打仗，不是可以“关上”的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在那一个战中失去了很多朋友。", "corrected_sentence": "他们在那一战中失去了很多朋友。", "error_description": "量词错误：〈战〉表示一次战斗时直接说〈那一战〉，中间不加量词〈个〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷常常说起一那战。", "corrected_sentence": "爷爷常常说起那一战。", "error_description": "语序错误：应说〈那一战〉，〈那〉要放在〈一〉前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
