INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24532, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "一件事，中间不停，一直连着。", "primary_collocate": null, "pronunciation": "lián xù xìng", "ipa": "ljɛn˧˥ ɕy˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "跑步要有连续性，每天跑才有用。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电视剧的连续性很强，每天晚上都有新的一集。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事缺少连续性，今天学，明天就不学了。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场大雨打断了比赛的连续性。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看书时老有人叫我，阅读的连续性就差了。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部纪录片的画面连续性很好，看起来很流畅。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写作文要注意句子之间的连续性。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条公路的连续性很好，中间没有红绿灯。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作的连续性不能断，所以我们轮流休息。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话没有连续性，前一句和后一句不一样。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連續性", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "中间不停、一直连着的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b69fe6f-45ff-4aa8-b887-4f71b2511eeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，跑步不具有颜色，“跑步要有颜色”不通。"}, {"text": "连续性", "is_correct": true, "explanation": "“连续性”指中间不停、一直连着，“跑步要有连续性”符合句意。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，跑步不具有重量，与句意不符。"}, {"text": "甜味", "is_correct": false, "explanation": "语义：“甜味”指味道，跑步没有味道，“跑步要有甜味”句意不通。"}], "explanations": {"颜色": "语义：“颜色”指色彩，跑步不具有颜色，“跑步要有颜色”不通。", "连续性": "“连续性”指中间不停、一直连着，“跑步要有连续性”符合句意。", "重量": "语义：“重量”指物体的轻重，跑步不具有重量，与句意不符。", "甜味": "语义：“甜味”指味道，跑步没有味道，“跑步要有甜味”句意不通。"}, "sentence_index": 0, "correct_answer": "连续性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶酒的连续性很高，口感很醇。", "explanation": "这里应该用〈纯度〉。连续性指中间不停、一直连着，酒的纯净程度要说纯度。"}, {"text": "这座雕像的连续性很好，人们都很喜欢它。", "explanation": "这里应该用〈艺术性〉。连续性指不间断，雕像的艺术价值应说艺术性。"}, {"text": "这张照片的连续性很高，细节很清楚。", "explanation": "这里应该用〈清晰度〉。连续性指不间断，照片细节清楚要说清晰度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硬度", "is_correct": false, "explanation": "搭配：“硬度”用于材料、物体，句子之间不能说硬度。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指外形，句子之间的联系不能说成形状，句意不通。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”指物体所占的空间，不能说句子之间的体积。"}, {"text": "连续性", "is_correct": true, "explanation": "“连续性”指前后不间断地连着，“写作文要注意句子之间的连续性”符合句意。"}], "explanations": {"硬度": "搭配：“硬度”用于材料、物体，句子之间不能说硬度。", "形状": "语义：“形状”指外形，句子之间的联系不能说成形状，句意不通。", "体积": "搭配：“体积”指物体所占的空间，不能说句子之间的体积。", "连续性": "“连续性”指前后不间断地连着，“写作文要注意句子之间的连续性”符合句意。"}, "sentence_index": 6, "correct_answer": "连续性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水的连续性很高，看得清杯底。", "explanation": "这里应该用〈透明度〉。连续性指不间断，水清澈到能看清杯底要说透明度。"}, {"text": "这间屋子的连续性很高，有点闷。", "explanation": "这里应该用〈湿度〉。连续性指不间断，空气潮湿、发闷要说湿度。"}, {"text": "这辆车的连续性很快，几分钟就到了。", "explanation": "这里应该用〈速度〉。连续性指不间断，车跑得快要说速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条生产线必须连续性。", "corrected_sentence": "这条生产线必须有连续性。", "error_description": "缺少动词：“连续性”作宾语需要动词“有”；正确为“必须有连续性”，“必须连续性”缺少动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说的话不有连续性，每句都跳来跳去。", "corrected_sentence": "他说的话没有连续性，每句都跳来跳去。", "error_description": "否定词错误：“有”应用“没有”否定，不能用“不”；“不有连续性”错误，正确为“没有连续性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
