INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了别人或重要的东西，自己失去生命或重要的东西。", "primary_collocate": null, "pronunciation": "xī shēng", "ipa": "ɕi˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他为了救孩子，牺牲了自己的生命。", "target_word": "牺牲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察为了保护大家，不怕牺牲。", "target_word": "牺牲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈牺牲了很多休息时间来照顾我。", "target_word": "牺牲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了国家，很多战士牺牲了。", "target_word": "牺牲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想牺牲家人的时间去工作。", "target_word": "牺牲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她牺牲睡觉的时间练习唱歌。", "target_word": "牺牲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不要牺牲健康来换钱。", "target_word": "牺牲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让弟弟上学，哥哥牺牲了自己的机会。", "target_word": "牺牲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位医生为了病人，牺牲过很多假期。", "target_word": "牺牲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能为了玩儿，牺牲学习的时间。", "target_word": "牺牲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "牺牲了", "label": "体标"}, {"form": "牺牲过", "label": "体标"}, {"form": "牺牲品", "label": "复合"}], "register": "中性", "sense_fingerprint": "为了别人或更重要的事，自己放弃或失去生命、时间等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37088c36-b988-4c59-bd87-98a844545e6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "牺牲", "is_correct": true, "explanation": "正确。牺牲指为了别人或重要的东西付出自己的生命，符合句意。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：「逃避」指躲开，与「为了救孩子而付出生命」的意思相反。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是护住自己，与“为了救孩子”付出生命的意思相反。"}, {"text": "花费", "is_correct": false, "explanation": "搭配：“花费”用于时间、钱财，不用于生命。"}], "explanations": {"牺牲": "正确。牺牲指为了别人或重要的东西付出自己的生命，符合句意。", "逃避": "语义：「逃避」指躲开，与「为了救孩子而付出生命」的意思相反。", "保护": "语义：“保护”是护住自己，与“为了救孩子”付出生命的意思相反。", "花费": "搭配：“花费”用于时间、钱财，不用于生命。"}, "sentence_index": 0, "correct_answer": "牺牲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在地震中牺牲了父母。", "explanation": "这里应该用〈失去〉。牺牲指为了别人或重要事业主动付出，意外中失去亲人不能用牺牲。"}, {"text": "他因病牺牲了。", "explanation": "这里应该用〈去世〉。牺牲指为了别人主动付出生命，因病去世不属于这种情况。"}, {"text": "他在考试中牺牲了，结果没及格。", "explanation": "这里应该用〈发挥失常〉。牺牲指为了别人或重要事业主动付出，考试没考好不是这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牺牲", "is_correct": true, "explanation": "正确。“不要牺牲健康来换钱”表示不要为了钱付出健康，符合句意。"}, {"text": "增进", "is_correct": false, "explanation": "语义：“增进”是使之更好，与“来换钱”所说的付出相反。"}, {"text": "珍惜", "is_correct": false, "explanation": "语义：“珍惜”与用健康去换钱的语境相悖，句意不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”多用于拒绝别人的邀请或要求，不说拒绝健康。"}], "explanations": {"牺牲": "正确。“不要牺牲健康来换钱”表示不要为了钱付出健康，符合句意。", "增进": "语义：“增进”是使之更好，与“来换钱”所说的付出相反。", "珍惜": "语义：“珍惜”与用健康去换钱的语境相悖，句意不通。", "拒绝": "搭配：“拒绝”多用于拒绝别人的邀请或要求，不说拒绝健康。"}, "sentence_index": 6, "correct_answer": "牺牲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "长期熬夜会牺牲身体。", "explanation": "这里应该用〈损害〉。牺牲指为了更重要的目标主动付出，熬夜造成的伤害要说损害。"}, {"text": "他牺牲了妻子，独自离开了家。", "explanation": "这里应该用〈抛弃〉。牺牲指为了他人或重要事业付出，遗弃妻子不能用牺牲。"}, {"text": "我不小心牺牲了那把钥匙。", "explanation": "这里应该用〈丢掉〉。牺牲指主动付出以成全更重要的事，不小心弄丢东西不能用牺牲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她为了照顾生病的妈妈，牺牲的了自己的工作。", "corrected_sentence": "她为了照顾生病的妈妈，牺牲了自己的工作。", "error_description": "“牺牲”后面多加了“的”，写成“牺牲的了”。正确应为“牺牲了”，去掉多余的“的”，即“牺牲了自己的工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父亲为了养家，把很多个人爱好牺牲。", "corrected_sentence": "父亲为了养家，把很多个人爱好牺牲了。", "error_description": "错在「牺牲」后面少了「了」。「把」字句的动词不能单独结尾，要带上其他成分，这里表示完成，应说「把很多个人爱好牺牲了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c50bd334-c686-46a1-afbf-96454ace0fd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怯懦", "is_correct": true, "explanation": "正确。“怯懦”与“勇气”相反，指遇事胆小、缺乏勇气。"}, {"text": "秩序", "is_correct": false, "explanation": "与“勇气”无反义关系，“秩序”指有条理的正常状态。"}, {"text": "责任", "is_correct": false, "explanation": "与“勇气”无反义关系，“责任”指应当承担的义务。"}, {"text": "友谊", "is_correct": false, "explanation": "与“勇气”无反义关系，“友谊”指朋友之间的感情。"}], "correct_answer": "怯懦", "explanations": {"怯懦": "正确。“怯懦”与“勇气”相反，指遇事胆小、缺乏勇气。", "秩序": "与“勇气”无反义关系，“秩序”指有条理的正常状态。", "责任": "与“勇气”无反义关系，“责任”指应当承担的义务。", "友谊": "与“勇气”无反义关系，“友谊”指朋友之间的感情。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "怯懦", "is_correct": true, "explanation": "正确。“怯懦”与“勇气”相反，指遇事胆小、缺乏勇气。"}, {"text": "桌子", "is_correct": false, "explanation": "与“勇气”无反义关系，“桌子”是家具。"}, {"text": "河流", "is_correct": false, "explanation": "与“勇气”无反义关系，“河流”是自然地理事物。"}, {"text": "节日", "is_correct": false, "explanation": "与“勇气”无反义关系，“节日”指特定的庆祝日子。"}], "correct_answer": "怯懦", "explanations": {"怯懦": "正确。“怯懦”与“勇气”相反，指遇事胆小、缺乏勇气。", "桌子": "与“勇气”无反义关系，“桌子”是家具。", "河流": "与“勇气”无反义关系，“河流”是自然地理事物。", "节日": "与“勇气”无反义关系，“节日”指特定的庆祝日子。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "敢于去做害怕或困难的事的胆量。", "primary_collocate": null, "pronunciation": "yǒng qì", "ipa": "jʊŋ˨˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "小明打针时没有哭，真有勇气。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她有勇气一个人睡觉。", "target_word": "勇气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟不怕黑，他很有勇气。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友鼓起勇气，跳进了水里。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，我今天很有勇气。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他第一次骑车摔倒，也没有哭，真有勇气。", "target_word": "勇气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩有勇气去看大狗。", "target_word": "勇气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师夸小红有勇气，因为她敢一个人上台。", "target_word": "勇气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想有勇气一个人去上学。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他需要勇气，才敢上台唱歌。", "target_word": "勇气", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股勇气", "label": "量词"}, {"form": "勇氣", "label": "繁体"}], "register": "通用", "sense_fingerprint": "小孩做害怕的事时不哭、胆子大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182b4525-1f74-4af1-84a7-3fc5eae249e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "勇气", "is_correct": true, "explanation": "正确。yǒng qì，指做害怕的事时不哭、胆子大。"}, {"text": "涌起", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，意思是“涌起”，指冒出、升起。"}, {"text": "用气", "is_correct": false, "explanation": "用气（yòngqì）：yòng 第四声与 yǒng 第三声声调不同，意思是运用气息。"}, {"text": "拥起", "is_correct": false, "explanation": "拥起（yōngqǐ）：yōng 第一声、qǐ 第三声，与 yǒngqì 声调不同，意思是簇拥而起。"}], "explanations": {"勇气": "正确。yǒng qì，指做害怕的事时不哭、胆子大。", "涌起": "qǐ（第三声）与 qì（第四声）声调不同，意思是“涌起”，指冒出、升起。", "用气": "用气（yòngqì）：yòng 第四声与 yǒng 第三声声调不同，意思是运用气息。", "拥起": "拥起（yōngqǐ）：yōng 第一声、qǐ 第三声，与 yǒngqì 声调不同，意思是簇拥而起。"}, "sentence_index": null, "correct_answer": "勇气"}, "level_3": {"options": [{"text": "勇气", "is_correct": true, "explanation": "正确。句中夸小明打针不哭，这里应是“勇气”。"}, {"text": "力气", "is_correct": false, "explanation": "语义：“力气”指体力，与打针时不哭所体现的胆量不同。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：句中说“没有哭”，又说“真有”，不能用“眼泪”作为被夸赞的品质。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“真有”后接“体温”不能表示赞扬，与这种评价不搭配。"}], "explanations": {"勇气": "正确。句中夸小明打针不哭，这里应是“勇气”。", "力气": "语义：“力气”指体力，与打针时不哭所体现的胆量不同。", "眼泪": "语义：句中说“没有哭”，又说“真有”，不能用“眼泪”作为被夸赞的品质。", "体温": "搭配：“真有”后接“体温”不能表示赞扬，与这种评价不搭配。"}, "sentence_index": 0, "correct_answer": "勇气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈很有勇气，一遍遍地陪我练习写字。", "explanation": "这里应该用〈耐心〉。勇气指敢做害怕的事的胆量，反复陪伴练习要说“耐心”，不说“很有勇气”。"}, {"text": "弟弟勇气大，一个人能扛起箱子。", "explanation": "这里应该用〈力气〉。扛箱子靠体力，勇气不能说明体力。"}, {"text": "他今天勇气很好，考试时猜中了好几道题。", "explanation": "这里应该用〈运气〉。猜中题目靠运气，勇气指敢做害怕的事的胆量，不能说“勇气很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勇气", "is_correct": true, "explanation": "正确。“有勇气”后接“去看大狗”，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装书的用品，不能与“去看大狗”的胆量搭配。"}, {"text": "尾巴", "is_correct": false, "explanation": "语义：“尾巴”是身体部位，句中无法用它表示去看大狗的条件。"}, {"text": "帽子", "is_correct": false, "explanation": "搭配：“有帽子”可说，但“去看大狗”需要的是胆量，不能用帽子代替。"}], "explanations": {"勇气": "正确。“有勇气”后接“去看大狗”，符合句意。", "书包": "语义：“书包”是装书的用品，不能与“去看大狗”的胆量搭配。", "尾巴": "语义：“尾巴”是身体部位，句中无法用它表示去看大狗的条件。", "帽子": "搭配：“有帽子”可说，但“去看大狗”需要的是胆量，不能用帽子代替。"}, "sentence_index": 6, "correct_answer": "勇气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他数学勇气很好，每次都考第一。", "explanation": "这里应该用〈成绩〉。勇气不能描述学科水平，数学好要说“成绩好”。"}, {"text": "他的勇气写得很漂亮。", "explanation": "这里应该用〈字〉。勇气是精神品质，不能用来说字写得好。"}, {"text": "他勇气很好，从来不跟别人吵架。", "explanation": "这里应该用〈脾气〉。性情温和、不轻易与人争吵要说“脾气好”，勇气指敢做害怕的事，不能用来形容性情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小宝拿出一个勇气，自己走进了医院。", "corrected_sentence": "小宝拿出一股勇气，自己走进了医院。", "error_description": "量词错误：“勇气”的量词是“股”，应说“一股勇气”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于鼓上勇气，自己去看医生。", "corrected_sentence": "他终于鼓起勇气，自己去看医生。", "error_description": "补语错误：“鼓”后的趋向补语应为“起”，说“鼓起勇气”，不能说“鼓上勇气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
