INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24538, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "比周围高出来，容易看见。", "primary_collocate": null, "pronunciation": "tū chū", "ipa": "tʰu˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他的鼻子很突出。", "target_word": "突出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座山有一块突出的大石头。", "target_word": "突出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红色在白墙上很突出。", "target_word": "突出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个字写得不够突出，看不清。", "target_word": "突出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她穿黄衣服，在人群中特别突出。", "target_word": "突出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边有一块突出的岩石。", "target_word": "突出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "标题要大一点，才够突出。", "target_word": "突出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那栋高楼在城市里非常突出。", "target_word": "突出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上的红灯很突出，晚上一眼就能看到。", "target_word": "突出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的眼睛有点突出。", "target_word": "突出", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "突出", "label": "原形"}], "register": "中性", "sense_fingerprint": "高出周围或与周围不同而显眼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22aa5821-43c2-4f1a-bd68-eccc7ce09b8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24538, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "突出", "is_correct": true, "explanation": "“突出”形容鼻子高高凸起，与“很”及“鼻子”相合。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，不能用来形容鼻子。"}, {"text": "鲜艳", "is_correct": false, "explanation": "语义：“鲜艳”形容颜色，与鼻子的形状不相关。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音或口感，不能用来形容鼻子。"}], "explanations": {"突出": "“突出”形容鼻子高高凸起，与“很”及“鼻子”相合。", "嘹亮": "搭配：“嘹亮”形容声音，不能用来形容鼻子。", "鲜艳": "语义：“鲜艳”形容颜色，与鼻子的形状不相关。", "清脆": "搭配：“清脆”形容声音或口感，不能用来形容鼻子。"}, "sentence_index": 0, "correct_answer": "突出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心情很突出，大家都没有注意到。", "explanation": "这里应该用〈明显〉。“突出”指形状高出或在某方面显眼，形容心情的显露要说“明显”。"}, {"text": "这座楼的价格很突出，所以我们没有买。", "explanation": "这里应该用〈贵〉。“突出”指显眼或高出，不能用来描述价格的高低。"}, {"text": "今天的天气很突出，我们都出去玩了。", "explanation": "这里应该用〈好〉。“突出”指高出周围或显眼，不用于描述天气，天气适合出去玩应说“很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "突出", "is_correct": true, "explanation": "“突出”形容标题醒目、显眼，与“才够”相合。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：“甜美”形容味道、声音或外貌，不能用来说标题的醒目程度。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，与标题无关。"}, {"text": "湿润", "is_correct": false, "explanation": "搭配：“湿润”形容物体含水或空气，不能用来说标题。"}], "explanations": {"突出": "“突出”形容标题醒目、显眼，与“才够”相合。", "甜美": "语义：“甜美”形容味道、声音或外貌，不能用来说标题的醒目程度。", "寒冷": "语义：“寒冷”形容温度，与标题无关。", "湿润": "搭配：“湿润”形容物体含水或空气，不能用来说标题。"}, "sentence_index": 6, "correct_answer": "突出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯咖啡的味道很突出，我喝了很多。", "explanation": "这里应该用〈好〉。“突出”指高出周围或显眼，不用来称赞味道好喝，应说“味道很好”。"}, {"text": "他很突出地喝了三杯水。", "explanation": "这里应该用〈一口气〉。“突出”表示显眼，不能修饰“喝”这样的日常动作，喝得快要说“一口气”。"}, {"text": "他在教室里突出地来回走，一句话也不说。", "explanation": "这里应该用〈不停〉。“突出”作状语只表示显眼地表现，不能描述“来回走”这样的动作，应说“不停地来回走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的鼻子上有一块突出疤。", "corrected_sentence": "他的鼻子上有一块突出的疤。", "error_description": "错误：双音节形容词“突出”作定语修饰名词时，后面要加“的”。正确：“突出的疤”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一对突出得耳朵。", "corrected_sentence": "他有一对突出的耳朵。", "error_description": "错误：“突出”修饰名词时要用“的”，不能用“得”。正确：“突出的耳朵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
