INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时节就是一年里的某个时候，比如春天、夏天。", "primary_collocate": null, "pronunciation": "shí jié", "ipa": "ʂɻ̩˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "春天是播种的时节。", "target_word": "时节", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "七月是荔枝上市的时节。", "target_word": "时节", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个时节，北方已经下雪了。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每年这个时节，我们都去海边玩。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "樱花盛开的时节，公园里人很多。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了落叶的时节，路上铺满黄叶。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天是最适合爬山的时节。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "梅雨时节，衣服总是干不了。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她最喜欢春暖花开的时节。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暑假正是游泳的最好时节。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "時節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "时节：一年里的某个时候，如春天、夏天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182b4525-1f74-4af1-84a7-3fc5eae249e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24542, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时节", "is_correct": true, "explanation": "时节（shí jié）指一年里的某个时候，是本题的目标词。"}, {"text": "十戒", "is_correct": false, "explanation": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是十条戒律。"}, {"text": "石阶", "is_correct": false, "explanation": "第二音节 jiē（第一声）与 jié（第二声）只差声调，意思是台阶。"}, {"text": "世界", "is_correct": false, "explanation": "两个音节都只差声调：shì（第四声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是世界。"}, {"text": "十级", "is_correct": false, "explanation": "第二音节 jí 与 jié 声调相同，韵母不同（i 与 ie），意思是十级。"}], "explanations": {"时节": "时节（shí jié）指一年里的某个时候，是本题的目标词。", "十戒": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是十条戒律。", "石阶": "第二音节 jiē（第一声）与 jié（第二声）只差声调，意思是台阶。", "世界": "两个音节都只差声调：shì（第四声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是世界。", "十级": "第二音节 jí 与 jié 声调相同，韵母不同（i 与 ie），意思是十级。"}, "sentence_index": null, "correct_answer": "时节"}, "level_3": {"options": [{"text": "时节", "is_correct": true, "explanation": "正确：“时节”指一年中的某个时候，符合“春天是播种的……”的语境。"}, {"text": "田地", "is_correct": false, "explanation": "语义：“田地”指土地，不表示时间，“春天是播种的田地”不成立。"}, {"text": "工具", "is_correct": false, "explanation": "语义：“工具”指器物，不表示一年中的某个时候。"}, {"text": "农具", "is_correct": false, "explanation": "语义：“农具”指耕作用的器具，不表示时间，“春天是播种的农具”不成立。"}], "explanations": {"时节": "正确：“时节”指一年中的某个时候，符合“春天是播种的……”的语境。", "田地": "语义：“田地”指土地，不表示时间，“春天是播种的田地”不成立。", "工具": "语义：“工具”指器物，不表示一年中的某个时候。", "农具": "语义：“农具”指耕作用的器具，不表示时间，“春天是播种的农具”不成立。"}, "sentence_index": 0, "correct_answer": "时节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上七点的时节起床。", "explanation": "这里应该用〈时候〉。时节指一年里的某段时候，不能指每天的某个钟点。"}, {"text": "火车到站的时节是下午三点。", "explanation": "这里应该用〈时刻〉。时节指一年中的某段时候，不指具体的某个钟点。"}, {"text": "我们定好的时节是下周三。", "explanation": "这里应该用〈日期〉。时节指一年里的某个时候，不指某一天；约定具体哪一天要说“日期”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24542, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时节", "is_correct": true, "explanation": "时节（shí jié）指一年里的某个时候，是本题的目标词。"}, {"text": "十届", "is_correct": false, "explanation": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是第十届。"}, {"text": "诗界", "is_correct": false, "explanation": "两个音节都只差声调：shī（第一声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是诗歌界。"}, {"text": "失节", "is_correct": false, "explanation": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是丧失节操。"}, {"text": "诗节", "is_correct": false, "explanation": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是诗歌的段落。"}], "explanations": {"时节": "时节（shí jié）指一年里的某个时候，是本题的目标词。", "十届": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是第十届。", "诗界": "两个音节都只差声调：shī（第一声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是诗歌界。", "失节": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是丧失节操。", "诗节": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是诗歌的段落。"}, "sentence_index": null, "correct_answer": "时节"}, "level_3": {"options": [{"text": "时节", "is_correct": true, "explanation": "正确：“时节”指一年中适合做某事的时候，与“最适合爬山”相合。"}, {"text": "人群", "is_correct": false, "explanation": "语义：“人群”指人，不指时间，“最适合爬山的人群”不成立。"}, {"text": "对象", "is_correct": false, "explanation": "语义：“对象”指所针对的人或事物，不表示季节，“最适合爬山的对象”不成立。"}, {"text": "工具", "is_correct": false, "explanation": "语义：“工具”指器物，不表示时间，“最适合爬山的工具”与“秋天是”不搭。"}], "explanations": {"时节": "正确：“时节”指一年中适合做某事的时候，与“最适合爬山”相合。", "人群": "语义：“人群”指人，不指时间，“最适合爬山的人群”不成立。", "对象": "语义：“对象”指所针对的人或事物，不表示季节，“最适合爬山的对象”不成立。", "工具": "语义：“工具”指器物，不表示时间，“最适合爬山的工具”与“秋天是”不搭。"}, "sentence_index": 6, "correct_answer": "时节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司第三时节的利润增加了。", "explanation": "这里应该用〈季度〉。时节不与“第三”这样的序数搭配来表示第几个季度。"}, {"text": "这项工作要花很多时节。", "explanation": "这里应该用〈时间〉。时节指一年中的某段时候，不能像时间那样用“很多”来计量时长。"}, {"text": "秦朝时节修建了长城的一部分。", "explanation": "这里应该用〈时期〉。历史阶段要说时期，时节多指一年中的某段时候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只适合游泳的时节。", "corrected_sentence": "这是一个适合游泳的时节。", "error_description": "量词错误：“时节”前应用“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在秋天的时节上，天气慢慢变凉。", "corrected_sentence": "在秋天的时节里，天气慢慢变凉。", "error_description": "方位词错误：“时节”是时间段，表示范围内应用“里”，“时节上”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
