INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24546, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事实就是真的发生过的事情。", "primary_collocate": null, "pronunciation": "shì shí", "ipa": "ʂʐ̩˥˩ ʂʐ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这是一个事实，大家都知道。", "target_word": "事实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事实是，他昨天没有来学校。", "target_word": "事实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写新闻要写事实，不能乱写。", "target_word": "事实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做决定前，先把事实弄清楚。", "target_word": "事实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的不是事实，只是他自己想的。", "target_word": "事实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的事实很快就查清楚了。", "target_word": "事实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先看清事实，再做决定。", "target_word": "事实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事实证明，早点睡觉对身体好。", "target_word": "事实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察已经把事实告诉了他。", "target_word": "事实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想接受这个事实。", "target_word": "事实", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个事实", "label": "量词"}], "register": "中性", "sense_fingerprint": "事实：真实发生的事情，与想法、说法相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce010c66-d877-4df7-8147-8f6d54c7cf13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24546, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事实", "is_correct": true, "explanation": "正确答案，即「事实」，shì shí。"}, {"text": "时事", "is_correct": false, "explanation": "两个音节声调都与「事实」不同（shíshì），意思是当前的时政新闻。"}, {"text": "世事", "is_correct": false, "explanation": "第二个音节声调不同（shì 第四声），意思是社会上的事情。"}, {"text": "试试", "is_correct": false, "explanation": "第二个音节轻声，与「事实」的第二声 shí 不同，意思是尝试一下。"}, {"text": "实事", "is_correct": false, "explanation": "两个音节声调都与「事实」不同，意思是实际的事情。"}], "explanations": {"事实": "正确答案，即「事实」，shì shí。", "时事": "两个音节声调都与「事实」不同（shíshì），意思是当前的时政新闻。", "世事": "第二个音节声调不同（shì 第四声），意思是社会上的事情。", "试试": "第二个音节轻声，与「事实」的第二声 shí 不同，意思是尝试一下。", "实事": "两个音节声调都与「事实」不同，意思是实际的事情。"}, "sentence_index": null, "correct_answer": "事实"}, "level_3": {"options": [{"text": "事实", "is_correct": true, "explanation": "正确。「事实」指真实发生的情况，句中“大家都知道”与之相符。"}, {"text": "尺寸", "is_correct": false, "explanation": "语义：「尺寸」指大小，不能作为“大家都知道的情况”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」指色彩，与“这是一个……，大家都知道”的说法不相符。"}, {"text": "空气", "is_correct": false, "explanation": "量词与语义：「空气」是不可数的物质名词，不能说「一个空气」，「大家都知道」也不成立。"}], "explanations": {"事实": "正确。「事实」指真实发生的情况，句中“大家都知道”与之相符。", "尺寸": "语义：「尺寸」指大小，不能作为“大家都知道的情况”。", "颜色": "语义：「颜色」指色彩，与“这是一个……，大家都知道”的说法不相符。", "空气": "量词与语义：「空气」是不可数的物质名词，不能说「一个空气」，「大家都知道」也不成立。"}, "sentence_index": 0, "correct_answer": "事实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他又撒了一个事实，大家都不相信。", "explanation": "这里应该用〈谎言〉。撒的是谎，「事实」指真实发生的情况，不能用「撒」。"}, {"text": "他昨晚做了一个事实，醒来后吓了一跳。", "explanation": "这里应该用〈梦〉。「做」的对象是梦，「事实」指真实发生的情况，不能被“做”。"}, {"text": "他这次考试得了一个事实，大家都很惊讶。", "explanation": "这里应该用〈奖〉。「得」的对象是奖项、病等，「事实」不能被“得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24546, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "事实", "is_correct": true, "explanation": "正确答案，即「事实」，shì shí。"}, {"text": "失实", "is_correct": false, "explanation": "第一个音节是阴平 shī，与「事实」的去声 shì 不同，意思是与实际不符。"}, {"text": "时时", "is_correct": false, "explanation": "第一个音节是阳平 shí，与「事实」的去声 shì 不同，意思是经常。"}, {"text": "实施", "is_correct": false, "explanation": "第二个音节是阴平 shī，与「事实」的阳平 shí 不同，意思是施行。"}, {"text": "四时", "is_correct": false, "explanation": "第一个音节声母是 s，与「事实」的 sh 不同，意思是四季。"}], "explanations": {"事实": "正确答案，即「事实」，shì shí。", "失实": "第一个音节是阴平 shī，与「事实」的去声 shì 不同，意思是与实际不符。", "时时": "第一个音节是阳平 shí，与「事实」的去声 shì 不同，意思是经常。", "实施": "第二个音节是阴平 shī，与「事实」的阳平 shí 不同，意思是施行。", "四时": "第一个音节声母是 s，与「事实」的 sh 不同，意思是四季。"}, "sentence_index": null, "correct_answer": "事实"}, "level_3": {"options": [{"text": "事实", "is_correct": true, "explanation": "正确。句中“看清……再做决定”需要一个可以看清的情况，应填「事实」。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：「窗户」是具体物，不是需要“看清”再决定的情况。"}, {"text": "天空", "is_correct": false, "explanation": "语义：「天空」与做决定的情况无关，“看清天空再做决定”说不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：「看清」的对象是可见的情况或物，「声音」不可看，「看清声音」不成立。"}], "explanations": {"事实": "正确。句中“看清……再做决定”需要一个可以看清的情况，应填「事实」。", "窗户": "语义：「窗户」是具体物，不是需要“看清”再决定的情况。", "天空": "语义：「天空」与做决定的情况无关，“看清天空再做决定”说不通。", "声音": "搭配：「看清」的对象是可见的情况或物，「声音」不可看，「看清声音」不成立。"}, "sentence_index": 6, "correct_answer": "事实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天吃一个事实。", "explanation": "这里应该用〈苹果〉。「吃」的对象是食物，「事实」是客观情况，不能吃。"}, {"text": "他昨天穿上了一个事实，去参加了婚礼。", "explanation": "这里应该用〈西装〉。「穿」的对象是衣服，「事实」不能穿。"}, {"text": "他在晚会上唱了一个事实，大家都笑了。", "explanation": "这里应该用〈歌〉。「唱」的对象是歌，「事实」不能被唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只事实，大家都承认。", "corrected_sentence": "这是一个事实，大家都承认。", "error_description": "量词错误：应为「一个事实」。「只」用于动物，「事实」应用「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要承认这个的事实。", "corrected_sentence": "我们要承认这个事实。", "error_description": "助词错误：应为「这个事实」。指示词「这个」已直接修饰名词，中间不需要「的」，多加的「的」使句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "歉收", "is_correct": true, "explanation": "正确。“歉收”指农作物收成不好，与“丰收”相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“丰收”无反义关系，“睡觉”是休息的行为。"}, {"text": "跑步", "is_correct": false, "explanation": "与“丰收”无反义关系，“跑步”是一种体育运动。"}, {"text": "画画", "is_correct": false, "explanation": "与“丰收”无反义关系，“画画”指用笔或颜料作画。"}], "correct_answer": "歉收", "explanations": {"歉收": "正确。“歉收”指农作物收成不好，与“丰收”相反。", "睡觉": "与“丰收”无反义关系，“睡觉”是休息的行为。", "跑步": "与“丰收”无反义关系，“跑步”是一种体育运动。", "画画": "与“丰收”无反义关系，“画画”指用笔或颜料作画。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "歉收", "is_correct": true, "explanation": "正确。“歉收”指农作物收成不好，与“丰收”相反。"}, {"text": "跳舞", "is_correct": false, "explanation": "与“丰收”无反义关系，“跳舞”是一种身体活动。"}, {"text": "读书", "is_correct": false, "explanation": "与“丰收”无反义关系，“读书”指阅读书籍。"}, {"text": "洗澡", "is_correct": false, "explanation": "与“丰收”无反义关系，“洗澡”是清洁身体的行为。"}], "correct_answer": "歉收", "explanations": {"歉收": "正确。“歉收”指农作物收成不好，与“丰收”相反。", "跳舞": "与“丰收”无反义关系，“跳舞”是一种身体活动。", "读书": "与“丰收”无反义关系，“读书”指阅读书籍。", "洗澡": "与“丰收”无反义关系，“洗澡”是清洁身体的行为。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "农民伯伯种的东西都收回家了，有很多。", "primary_collocate": null, "pronunciation": "fēng shōu", "ipa": "fɤŋ˥ ʂoʊ˥", "syllable_count": 2, "sentences": [{"text": "农民伯伯今年丰收了。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天到了，田里的玉米丰收了。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷种的菜丰收了，吃不完。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "稻子丰收，农民伯伯很高兴。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年苹果丰收，树上挂满了红苹果。", "target_word": "丰收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丰收以后，大家一起吃新米饭。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，今年我们家的地丰收了。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下过雨，小麦长得好，一定会丰收。", "target_word": "丰收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天田里金黄一片，今年又丰收了。", "target_word": "丰收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们帮农民伯伯庆祝丰收，一起收玉米。", "target_word": "丰收", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "丰收了", "label": "体标"}, {"form": "豐收", "label": "繁体"}], "register": "通用", "sense_fingerprint": "农民种的东西收回家，收成很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182b4525-1f74-4af1-84a7-3fc5eae249e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丰收", "is_correct": true, "explanation": "正确。“农民伯伯今年丰收了”是描述农事的结果，符合句意。"}, {"text": "开花", "is_correct": false, "explanation": "语义：“开花”指植物开出花朵，主语不能是人。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能以“农民伯伯”为主语。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属被氧化，不用于人。"}], "explanations": {"丰收": "正确。“农民伯伯今年丰收了”是描述农事的结果，符合句意。", "开花": "语义：“开花”指植物开出花朵，主语不能是人。", "下雨": "语义：“下雨”是天气现象，不能以“农民伯伯”为主语。", "生锈": "语义：“生锈”指金属被氧化，不用于人。"}, "sentence_index": 0, "correct_answer": "丰收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试考得很丰收。", "explanation": "这里应该用〈好〉。丰收用于农作物的收成，考试成绩要说“好”。"}, {"text": "这个孩子长得很丰收。", "explanation": "这里应该用〈健壮〉。丰收用于收成，不说人长得丰收，应说“健壮”。"}, {"text": "这座城市这几年丰收得很快。", "explanation": "这里应该用〈发展〉。丰收指农作物或成果的收成，城市的变化要说“发展”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丰收", "is_correct": true, "explanation": "正确。“今年我们家的地丰收了”描述农作物的收成，符合句意。"}, {"text": "搬家", "is_correct": false, "explanation": "搭配：“地”不能主动搬家，与“地”作主语的搭配不当。"}, {"text": "装修", "is_correct": false, "explanation": "语义：“装修”指房屋的修饰，不能用来说地的结果。"}, {"text": "出嫁", "is_correct": false, "explanation": "语义：“出嫁”指女子结婚，与“地”不相符。"}], "explanations": {"丰收": "正确。“今年我们家的地丰收了”描述农作物的收成，符合句意。", "搬家": "搭配：“地”不能主动搬家，与“地”作主语的搭配不当。", "装修": "语义：“装修”指房屋的修饰，不能用来说地的结果。", "出嫁": "语义：“出嫁”指女子结婚，与“地”不相符。"}, "sentence_index": 6, "correct_answer": "丰收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的能力很丰收，工作很出色。", "explanation": "这里应该用〈强〉。丰收只用于农作物或成果的收成，形容能力要说“强”，不能说“很丰收”。"}, {"text": "这个节日，大家都很丰收。", "explanation": "这里应该用〈快乐〉。丰收用于农作物或成果，不能描述人的心情。"}, {"text": "运动员们训练得很丰收。", "explanation": "这里应该用〈辛苦〉。丰收不描述训练的状态，训练的艰苦要说“辛苦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的稻子丰收着，农民都很开心。", "corrected_sentence": "今年的稻子丰收了，农民都很开心。", "error_description": "体标错误：表示收成已经完成要用“了”，说“丰收了”，不能用“着”说“丰收着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年我们村的玉米把丰收了。", "corrected_sentence": "今年我们村的玉米丰收了。", "error_description": "多余的“把”：“丰收”是不及物动词，不能用于“把”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
