INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24550, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "叫来用。", "primary_collocate": null, "pronunciation": "diào yòng", "ipa": "tjɑʊ̯˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "经理调用了三个人去帮忙。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总部调用了十辆车来运货。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察调用附近的人手去找孩子。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出差要用车，可以调用公司的车。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队长调用了几个队员守在门口。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校调用了全部老师来照顾学生。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院调用了附近的医生来帮忙。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司从仓库调用了一批材料运到工地。", "target_word": "调用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灾区需要帮助，政府调用了军队。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房人手不够，老板调用了服务员。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "调用了", "label": "体标"}, {"form": "调用过", "label": "体标"}, {"form": "調用", "label": "繁体"}], "register": "中性", "sense_fingerprint": "调用：把人员、车辆、物资叫来使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182b4525-1f74-4af1-84a7-3fc5eae249e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "调用", "is_correct": true, "explanation": "正确：“调用”表示调派人员，符合“经理……三个人去帮忙”的语境，只有它能填入空格。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：“辞退”是解雇，与“去帮忙”的意思相矛盾。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器或物品，不能用于人。"}, {"text": "收购", "is_correct": false, "explanation": "搭配：“收购”用于物资或产业，不能用于人。"}], "explanations": {"调用": "正确：“调用”表示调派人员，符合“经理……三个人去帮忙”的语境，只有它能填入空格。", "辞退": "语义：“辞退”是解雇，与“去帮忙”的意思相矛盾。", "修理": "搭配：“修理”用于机器或物品，不能用于人。", "收购": "搭配：“收购”用于物资或产业，不能用于人。"}, "sentence_index": 0, "correct_answer": "调用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察调用了案件的经过。", "explanation": "这里应该用〈调查〉。调用指叫来人员或车辆等供自己使用，查看案件情况要说“调查”。"}, {"text": "他把旧衣服调用了。", "explanation": "这里应该用〈扔〉。调用不表示丢弃，丢掉东西要说“扔”。"}, {"text": "他调用了一件礼物。", "explanation": "这里应该用〈挑选〉。调用指调配已有的人员或物资，选择物品要说“挑选”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调用", "is_correct": true, "explanation": "正确：“调用”表示调派人员，符合“医院……医生来帮忙”的语境，只有它能填入空格。"}, {"text": "逮捕", "is_correct": false, "explanation": "语义：“逮捕”是抓人，与“来帮忙”的意思相矛盾。"}, {"text": "宣传", "is_correct": false, "explanation": "搭配：“宣传”用于事物或观念，不能说“宣传医生”来帮忙。"}, {"text": "解剖", "is_correct": false, "explanation": "语义：“解剖”指剖开研究，与“来帮忙”的意思不相符。"}], "explanations": {"调用": "正确：“调用”表示调派人员，符合“医院……医生来帮忙”的语境，只有它能填入空格。", "逮捕": "语义：“逮捕”是抓人，与“来帮忙”的意思相矛盾。", "宣传": "搭配：“宣传”用于事物或观念，不能说“宣传医生”来帮忙。", "解剖": "语义：“解剖”指剖开研究，与“来帮忙”的意思不相符。"}, "sentence_index": 6, "correct_answer": "调用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他调用了一首歌。", "explanation": "这里应该用〈唱〉。调用指把人员、车辆、物资叫来使用，唱歌要说“唱”。"}, {"text": "他向老板调用了工作进度。", "explanation": "这里应该用〈报告〉。调用不表示汇报，汇报情况要说“报告”。"}, {"text": "他调用了一封信。", "explanation": "这里应该用〈写〉。调用不表示书写，写信要说“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理昨天调用着三个人去帮忙。", "corrected_sentence": "经理昨天调用了三个人去帮忙。", "error_description": "体标错误：“昨天”指已完成的过去，“调用”的动作已经完成，应用“了”，不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂昨天从仓库调用着一批零件。", "corrected_sentence": "工厂昨天从仓库调用了一批零件。", "error_description": "体标错误：“调用”指已经完成的动作，应用“了”；用“着”表示动作正在进行，与句意不符，应说“调用了一批零件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4819464-416e-4052-8c8c-9c8a2454a004') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24552, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "口头", "is_correct": true, "explanation": "反义：书面指用写下来的话表示，口头指用说出来的话表示，两者相对。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“书面”没有反义关系，形容山坡或坡度很陡。"}, {"text": "柔和", "is_correct": false, "explanation": "与“书面”没有反义关系，形容光线或声音温和。"}, {"text": "湿润", "is_correct": false, "explanation": "与“书面”没有反义关系，形容含有水分。"}], "correct_answer": "口头", "explanations": {"口头": "反义：书面指用写下来的话表示，口头指用说出来的话表示，两者相对。", "陡峭": "与“书面”没有反义关系，形容山坡或坡度很陡。", "柔和": "与“书面”没有反义关系，形容光线或声音温和。", "湿润": "与“书面”没有反义关系，形容含有水分。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
