INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24552, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用写下来的话表示的", "primary_collocate": null, "pronunciation": "shū miàn", "ipa": "ʂu˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "经理要我们提交书面材料。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书面通知已经发给每个人了。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这件事做了书面说明。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板同意了我的书面请假申请。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "口头说不清楚，请写成书面的。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有书面证明吗？", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要求家长书面同意。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把规定写成书面文件。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前要先交书面报名表。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写了一封书面道歉信。", "target_word": "书面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "书面语", "label": "复合"}, {"form": "書面", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "用写下来的话表示的（书面材料、书面证明）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4da4f6c8-6bbf-4c97-a4e8-ea8e0f7f3746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书面", "is_correct": true, "explanation": "正确：书面指用写下来的话表示，修饰“材料”，与句意相符。"}, {"text": "勇敢", "is_correct": false, "explanation": "搭配：“勇敢”形容人的品质，不能修饰“材料”。"}, {"text": "寂静", "is_correct": false, "explanation": "搭配：“寂静”多形容环境或声音，不能修饰“材料”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体型，不能修饰“材料”。"}], "explanations": {"书面": "正确：书面指用写下来的话表示，修饰“材料”，与句意相符。", "勇敢": "搭配：“勇敢”形容人的品质，不能修饰“材料”。", "寂静": "搭配：“寂静”多形容环境或声音，不能修饰“材料”。", "高大": "体貌：“高大”形容体型，不能修饰“材料”。"}, "sentence_index": 0, "correct_answer": "书面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他书面地打断了老师的讲话。", "explanation": "这里应该用〈当面〉。打断讲话是当面进行的口头动作，“书面”指写下来的，两者矛盾。"}, {"text": "这块蛋糕很书面。", "explanation": "这里应该用〈精致〉。书面指用文字表达，不能形容蛋糕；蛋糕的精美要用“精致”。"}, {"text": "这场婚礼很书面。", "explanation": "这里应该用〈正式〉。书面指写下的，不指庄重；婚礼的庄重要用“正式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书面", "is_correct": true, "explanation": "正确：书面同意指用写下来的方式表示同意，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能修饰“同意”。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”形容味道，与“同意”无关。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”多形容水或食物的温度，不能修饰“同意”。"}], "explanations": {"书面": "正确：书面同意指用写下来的方式表示同意，符合句意。", "漂亮": "体貌：“漂亮”形容外貌，不能修饰“同意”。", "辛辣": "语义：“辛辣”形容味道，与“同意”无关。", "滚烫": "搭配：“滚烫”多形容水或食物的温度，不能修饰“同意”。"}, "sentence_index": 6, "correct_answer": "书面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他书面地和我握了手。", "explanation": "这里应该用〈热情〉。书面指写下来，不能修饰握手这样的身体动作；握手的态度要用“热情”。"}, {"text": "这辆车很书面。", "explanation": "这里应该用〈高级〉。书面指文字形式，不能形容车的档次；车的档次要用“高级”。"}, {"text": "她的笑容很书面。", "explanation": "这里应该用〈灿烂〉。书面指写下来的文字，不能形容笑容；笑容的样子要用“灿烂”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经交了一书面材料。", "corrected_sentence": "他已经交了一份书面材料。", "error_description": "量词缺失：数量短语“一”后要加量词，“材料”应用“份”计量，应说“一份书面材料”，不能直接说“一书面材料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我收到了一份的书面通知。", "corrected_sentence": "我收到了一份书面通知。", "error_description": "结构助词错误：“一份”后不能直接加“的”，应说“一份书面通知”，“的”不能插在数量短语与修饰语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
