INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24556, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "存放过去事情记录的地方，比如文件或纸。", "primary_collocate": null, "pronunciation": "dàng àn", "ipa": "tɑŋ˥˩ ɑn˥˩", "syllable_count": 2, "sentences": [{"text": "这些旧档案放在二楼的柜子里。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把老档案收在大箱子里。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去查一查当年的档案。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "档案里写着这座城市的历史。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在这里整理旧档案。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份档案已经有五十年了。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能帮我找一下那份档案吗？", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "馆里的档案按年份放好了。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些纸质档案都变黄了。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在档案里找到了老照片。", "target_word": "档案", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份档案", "label": "量词"}, {"form": "档案室", "label": "复合"}, {"form": "檔案", "label": "繁体"}], "register": "中性", "sense_fingerprint": "保存过去记录的文件或纸（旧档案、历史档案）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4da4f6c8-6bbf-4c97-a4e8-ea8e0f7f3746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24556, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "档案", "is_correct": true, "explanation": "正确：档案指保存过去记录的文件或纸，旧档案可以放在柜子里，符合句意。"}, {"text": "脸庞", "is_correct": false, "explanation": "体貌：脸庞是人的面部，不是可以放进柜子里的纸或文件。"}, {"text": "月光", "is_correct": false, "explanation": "配价：“放”需要可以搬动的具体物品作宾语，月光无法放进柜子。"}, {"text": "白天", "is_correct": false, "explanation": "语义：白天指时间，不是保存过去记录的文件，放进柜子不合理。"}], "explanations": {"档案": "正确：档案指保存过去记录的文件或纸，旧档案可以放在柜子里，符合句意。", "脸庞": "体貌：脸庞是人的面部，不是可以放进柜子里的纸或文件。", "月光": "配价：“放”需要可以搬动的具体物品作宾语，月光无法放进柜子。", "白天": "语义：白天指时间，不是保存过去记录的文件，放进柜子不合理。"}, "sentence_index": 0, "correct_answer": "档案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天用档案打电话。", "explanation": "这里应该用〈手机〉。打电话要用手机，档案是存放过去记录的文件或地方，不能用来打电话。"}, {"text": "我们去档案吃午饭。", "explanation": "这里应该用〈食堂〉。吃午饭要去食堂，档案是存放过去记录的地方，不是用餐的场所。"}, {"text": "老人常常给我唱她的档案。", "explanation": "这里应该用〈歌〉。唱的是歌曲，档案是存放过去记录的文件或地方，不能唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "档案", "is_correct": true, "explanation": "正确：档案指保存过去记录的文件，句中要找的正是这份旧文件，符合句意。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水不是可以找到的文件，“那份雨水”与句中的要求不符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体型，不能用“找一下”寻找，与句中的文件不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是大气状况，不是可以找到的文件，句中指向一份档案。"}], "explanations": {"档案": "正确：档案指保存过去记录的文件，句中要找的正是这份旧文件，符合句意。", "雨水": "语义：雨水不是可以找到的文件，“那份雨水”与句中的要求不符。", "身材": "体貌：身材指人的体型，不能用“找一下”寻找，与句中的文件不符。", "天气": "语义：天气是大气状况，不是可以找到的文件，句中指向一份档案。"}, "sentence_index": 6, "correct_answer": "档案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶给我讲了一个老档案。", "explanation": "这里应该用〈故事〉。档案是保存的文件，不能用来讲述；讲过去的事要用“故事”。"}, {"text": "我每天早上喝档案。", "explanation": "这里应该用〈牛奶〉。早上喝的是牛奶，档案是存放过去记录的文件或地方，不能喝。"}, {"text": "妈妈在厨房里煮档案。", "explanation": "这里应该用〈面条〉。煮的是食物，档案是存放过去记录的文件或地方，不能煮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷把这条旧档案整理好了。", "corrected_sentence": "爷爷把这份旧档案整理好了。", "error_description": "量词错误：档案应用“份”计量，“条”用于细长的东西，应说“这份旧档案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想请你帮我找一份的旧档案。", "corrected_sentence": "我想请你帮我找一份旧档案。", "error_description": "结构助词错误：“一份”与后面的修饰语“旧”之间不能加“的”，应说“一份旧档案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
