INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24566, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24566, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西，比如水、石头、木头，都是物质。", "primary_collocate": null, "pronunciation": "wù zhì", "ipa": "u⁵¹ ʈʂʅ⁵¹", "syllable_count": 2, "sentences": [{"text": "水、石头和木头都是物质。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上的一切东西都是物质。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气看不见，但它也是物质。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁是一种很硬的物质。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种物质放在水里会变软。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们说出三种物质的名字。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰和水是同一种物质。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盐是一种可以溶在水里的物质。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上看了几种不同的物质。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子是用木头做的，木头是一种物质。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "物质文明", "label": "复合"}, {"form": "物質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "构成世界的各种东西，如水、石头、木头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c7f2601-5d41-4e78-8d42-413e02a40644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24566, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物质", "is_correct": true, "explanation": "物质（wù zhì）指构成世界的各种东西，如水、石头、木头。"}, {"text": "务实", "is_correct": false, "explanation": "务实（wù shí）与物质（wù zhì）的第二音节声母不同（shí 为 sh，zhì 为 zh），意思是注重实际。"}, {"text": "物资", "is_correct": false, "explanation": "物资（wù zī）第二音节 zī 与 zhì 的声母和声调都不同，意思是生产生活所需的物品。"}, {"text": "无知", "is_correct": false, "explanation": "无知（wú zhī）第一音节 wú 为第二声，与 wù（第四声）声调不同，意思是缺乏知识。"}, {"text": "误事", "is_correct": false, "explanation": "误事（wù shì）第二音节 shì 与 zhì 声母不同（sh 与 zh），意思是耽误事情。"}], "explanations": {"物质": "物质（wù zhì）指构成世界的各种东西，如水、石头、木头。", "务实": "务实（wù shí）与物质（wù zhì）的第二音节声母不同（shí 为 sh，zhì 为 zh），意思是注重实际。", "物资": "物资（wù zī）第二音节 zī 与 zhì 的声母和声调都不同，意思是生产生活所需的物品。", "无知": "无知（wú zhī）第一音节 wú 为第二声，与 wù（第四声）声调不同，意思是缺乏知识。", "误事": "误事（wù shì）第二音节 shì 与 zhì 声母不同（sh 与 zh），意思是耽误事情。"}, "sentence_index": null, "correct_answer": "物质"}, "level_3": {"options": [{"text": "物质", "is_correct": true, "explanation": "物质：指构成世界的各种东西，与“水、石头和木头”的类别相合。"}, {"text": "动物", "is_correct": false, "explanation": "语义：水、石头和木头不是动物。"}, {"text": "节日", "is_correct": false, "explanation": "语义：水、石头和木头不是节日。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：“面容”只指人的脸，不能用于水、石头这类东西。"}], "explanations": {"物质": "物质：指构成世界的各种东西，与“水、石头和木头”的类别相合。", "动物": "语义：水、石头和木头不是动物。", "节日": "语义：水、石头和木头不是节日。", "面容": "体貌：“面容”只指人的脸，不能用于水、石头这类东西。"}, "sentence_index": 0, "correct_answer": "物质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "床边放着一个小物质，摸起来很硬。", "explanation": "这里应该用〈物体〉。“物质”指构成东西的种类，不指一个具体的物件，数个体要用“物体”。"}, {"text": "这批救灾物质已经运到灾区。", "explanation": "这里应该用〈物资〉。“物质”指构成东西的种类，不指成批运送的救灾用品，救灾用品要说“物资”。"}, {"text": "我在路上捡到一个物质，是一把钥匙。", "explanation": "这里应该用〈东西〉。“物质”指构成世界的某一类东西，不指一件具体的物品，捡到的钥匙要说“东西”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24566, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "物质", "is_correct": true, "explanation": "物质（wù zhì）指构成世界的各种东西，如水、石头、木头。"}, {"text": "武士", "is_correct": false, "explanation": "武士（wǔ shì）第一音节为第三声，第二音节声母为 sh（zhì 为 zh），意思是古代的战士。"}, {"text": "污渍", "is_correct": false, "explanation": "污渍（wū zì）第一音节为第一声，第二音节声母为 z（zhì 为 zh），意思是污迹。"}, {"text": "舞姿", "is_correct": false, "explanation": "舞姿（wǔ zī）两个音节的声调都与物质不同，第二音节声母为 z，意思是舞蹈的姿态。"}], "explanations": {"物质": "物质（wù zhì）指构成世界的各种东西，如水、石头、木头。", "武士": "武士（wǔ shì）第一音节为第三声，第二音节声母为 sh（zhì 为 zh），意思是古代的战士。", "污渍": "污渍（wū zì）第一音节为第一声，第二音节声母为 z（zhì 为 zh），意思是污迹。", "舞姿": "舞姿（wǔ zī）两个音节的声调都与物质不同，第二音节声母为 z，意思是舞蹈的姿态。"}, "sentence_index": null, "correct_answer": "物质"}, "level_3": {"options": [{"text": "物质", "is_correct": true, "explanation": "物质：指构成世界的各种东西，冰和水属于同一类物质。"}, {"text": "季节", "is_correct": false, "explanation": "语义：冰和水不是季节。"}, {"text": "体态", "is_correct": false, "explanation": "体貌：“体态”指人的身材姿态，不能用于冰和水。"}, {"text": "花卉", "is_correct": false, "explanation": "语义：冰和水不是花卉。"}], "explanations": {"物质": "物质：指构成世界的各种东西，冰和水属于同一类物质。", "季节": "语义：冰和水不是季节。", "体态": "体貌：“体态”指人的身材姿态，不能用于冰和水。", "花卉": "语义：冰和水不是花卉。"}, "sentence_index": 6, "correct_answer": "物质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书包里的物质都拿了出来，有书和笔。", "explanation": "这里应该用〈东西〉。“物质”指构成世界的某一类东西，书包里的具体物品要说“东西”。"}, {"text": "这个物质很精致，是他送的礼物。", "explanation": "这里应该用〈物件〉。“物质”指构成东西的种类，不指一件精致的礼物，这里要说“物件”。"}, {"text": "书架上放着一个小物质，很硬。", "explanation": "这里应该用〈物件〉。“物质”指构成东西的种类，不指一个具体的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "氧气也是一只物质。", "corrected_sentence": "氧气也是一种物质。", "error_description": "量词错误：“物质”指一类东西，应该用量词“种”，不能用“只”。正确说法是“一种物质”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们过学很多种物质。", "corrected_sentence": "我们学过很多种物质。", "error_description": "“过”的位置错误：动态助词“过”应紧跟动词，应说“学过”，不能放在动词之前。正确说法是“学过很多种物质”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51d8e2bc-0184-4abe-ade1-561b8f69190c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
