INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24570, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个人或东西当成另一个人或东西。", "primary_collocate": null, "pronunciation": "shì zuò", "ipa": "ʂʐ̩˥˩ tsuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "他把这本书视作最好的朋友。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人把工作视作生活的一部分。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把每个学生视作自己的孩子。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能把小错误视作大问题。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把这次比赛视作一次学习的机会。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把老邻居视作家人。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把客人视作最重要的人。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把我的话视作批评。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这只小狗视作家里的一员。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人把钱视作最重要的东西。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "视作了", "label": "完成体"}, {"form": "视作过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "把甲当作乙来看待", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eb6ea89-b4e2-487f-9034-a8829d8e7345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "视作", "is_correct": true, "explanation": "“把这本书视作最好的朋友”表示把书当成朋友，符合句意。"}, {"text": "等于", "is_correct": false, "explanation": "配价：“等于”后接的是数量或判断，不能用“把……等于……朋友”这样的结构表达认定。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：“推翻”指颠覆，与“最好的朋友”的褒义评价不符。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护最好的朋友”说的是护着朋友，与“把这本书”的认定结构不符。"}], "explanations": {"视作": "“把这本书视作最好的朋友”表示把书当成朋友，符合句意。", "等于": "配价：“等于”后接的是数量或判断，不能用“把……等于……朋友”这样的结构表达认定。", "推翻": "语义：“推翻”指颠覆，与“最好的朋友”的褒义评价不符。", "保护": "语义：“保护最好的朋友”说的是护着朋友，与“把这本书”的认定结构不符。"}, "sentence_index": 0, "correct_answer": "视作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把窗外晾着的衣服视作了一个人，还跟它打了招呼。", "explanation": "这里应该用〈误认成〉。“视作”表示有意识地认定，不用于把衣服错看成人的情况。"}, {"text": "天太黑了，他把路边的石头视作了一只小狗。", "explanation": "这里应该用〈看成〉。“视作”是有意识的认定，不表示因为看不清而看错。"}, {"text": "他把小偷视作了民警。", "explanation": "这里应该用〈误认成〉。“视作”是有意识的认定，不表示误认身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视作", "is_correct": true, "explanation": "“公司把客人视作最重要的人”表示把客人看作最重要的人，符合句意。"}, {"text": "拖延", "is_correct": false, "explanation": "配价：“拖延”的对象是时间或事情，不能直接接“人”作宾语。"}, {"text": "访问", "is_correct": false, "explanation": "语义：“访问最重要的人”表示去拜访，与“把客人”的认定结构不符。"}, {"text": "摆放", "is_correct": false, "explanation": "语义：“摆放最重要的人”说的是摆放人，句意不通。"}], "explanations": {"视作": "“公司把客人视作最重要的人”表示把客人看作最重要的人，符合句意。", "拖延": "配价：“拖延”的对象是时间或事情，不能直接接“人”作宾语。", "访问": "语义：“访问最重要的人”表示去拜访，与“把客人”的认定结构不符。", "摆放": "语义：“摆放最重要的人”说的是摆放人，句意不通。"}, "sentence_index": 6, "correct_answer": "视作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把厨房的水龙头视作了门铃，按了好几次。", "explanation": "这里应该用〈误认〉。“视作”是有意识的认定，不用于把水龙头错当成门铃的情况。"}, {"text": "屋里太暗，我把墙上的影子视作了小偷，吓了一跳。", "explanation": "这里应该用〈误当成〉。“视作”是有意识的认定，不用于看错东西、吓一跳的情况。"}, {"text": "他把鸡蛋视作了石头。", "explanation": "这里应该用〈错当〉。“视作”不用于错当东西的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把这个想法的视作一个机会。", "corrected_sentence": "我们把这个想法视作一个机会。", "error_description": "结构错误：“的”不能插在把字结构中的动词“视作”前，应为“把这个想法视作一个机会”。错误形式：想法的视作；正确形式：想法视作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这份合同的视作一项承诺。", "corrected_sentence": "他把这份合同视作一项承诺。", "error_description": "结构错误：“的”不能插在动词“视作”前，应为“把这份合同视作一项承诺”。错误形式：合同的视作；正确形式：合同视作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '563d4160-02a3-4e8c-b5c0-0b1913a44586') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
