INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24572, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "没有办法做到。", "primary_collocate": null, "pronunciation": "wú fǎ", "ipa": "u˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "钥匙丢了，我无法进家门。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多作业，我今晚无法做完。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我无法想象没有你的生活。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病太重，医生也无法治好。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音太小了，后面的人无法听见。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车坏在半路，我们无法按时到达。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太生气了，无法冷静下来。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间不够，我无法把书看完。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走得太远，我无法再看到他。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我无法一个人决定。", "target_word": "无法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無法", "label": "繁体"}], "register": "中性", "sense_fingerprint": "无法：没有办法做到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd85b7b25-3bf8-4da1-af69-47b35a3d9947') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24572, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无法", "is_correct": true, "explanation": "正确：「无法」表示没有办法做到，钥匙丢了正说明进不了门。"}, {"text": "能", "is_correct": false, "explanation": "语义：「能」表示能够做到，与「钥匙丢了」的情况相矛盾。"}, {"text": "可以", "is_correct": false, "explanation": "语义：「可以」表示许可或可能，说钥匙丢了还「可以进家门」，与句意相悖。"}, {"text": "必须", "is_correct": false, "explanation": "语义：「必须」表示必要或义务，与「钥匙丢了」所说的困难不符，句意不通。"}], "explanations": {"无法": "正确：「无法」表示没有办法做到，钥匙丢了正说明进不了门。", "能": "语义：「能」表示能够做到，与「钥匙丢了」的情况相矛盾。", "可以": "语义：「可以」表示许可或可能，说钥匙丢了还「可以进家门」，与句意相悖。", "必须": "语义：「必须」表示必要或义务，与「钥匙丢了」所说的困难不符，句意不通。"}, "sentence_index": 0, "correct_answer": "无法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈劝了很久，他却无法去医院。", "explanation": "这里应该用〈不肯〉。「无法」表示没有能力或条件，而句子说的是他拒绝去，并非做不到。"}, {"text": "这件事不用着急，他无法着急。", "explanation": "这里应该用〈不必〉。「无法」说做不到，而句子要表达的是没有必要着急。"}, {"text": "他故意无法回答我的问题。", "explanation": "这里应该用〈不愿〉。「无法」表示没有能力，而「故意」表示主动选择，两者矛盾；句子实际是他不愿回答。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无法", "is_correct": true, "explanation": "正确：「无法」表示没有办法做到，「太生气了」正说明她冷静不下来。"}, {"text": "发火", "is_correct": false, "explanation": "语义：「发火」是发脾气，与「冷静下来」意思相反，句子不通。"}, {"text": "大笑", "is_correct": false, "explanation": "语义：「大笑」是开心地笑出声，与「太生气了」矛盾，句子不通。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：「吵闹」指喧哗，不能与「冷静下来」连用，句子不通。"}], "explanations": {"无法": "正确：「无法」表示没有办法做到，「太生气了」正说明她冷静不下来。", "发火": "语义：「发火」是发脾气，与「冷静下来」意思相反，句子不通。", "大笑": "语义：「大笑」是开心地笑出声，与「太生气了」矛盾，句子不通。", "吵闹": "搭配：「吵闹」指喧哗，不能与「冷静下来」连用，句子不通。"}, "sentence_index": 6, "correct_answer": "无法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我决定不回家，所以无法回家。", "explanation": "这里应该用〈不打算〉。「无法」表示客观上做不到，而句子说的是我自己决定不回家。"}, {"text": "他不喜欢吃鱼，所以无法吃鱼。", "explanation": "这里应该用〈不愿意〉。「无法」表示客观上做不到，而句子说的是他不喜欢、自己不想吃，并非做不到。"}, {"text": "这些作业我懒得写，无法写完。", "explanation": "这里应该用〈懒得〉。「无法」说没有能力，而句子说的是我不愿意动笔，并非做不到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨太大了，我无法能骑车回家。", "corrected_sentence": "雨太大了，我无法骑车回家。", "error_description": "错误形式：「无法能」；正确形式：「无法」。「无法」本身已表示没有能力或条件，再加「能」意思重复，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "时间太紧，我们无法了按时完成工作。", "corrected_sentence": "时间太紧，我们无法按时完成工作。", "error_description": "错误形式：「无法了按时完成工作」；正确形式：「无法按时完成工作」。「无法」是情态动词，后面不能加「了」，「了」只能跟在动词之后表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
