INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "文化遗产是过去的人们留下的好东西，比如有名的建筑和故事。", "primary_collocate": null, "pronunciation": "wén huà yí chǎn", "ipa": "wən³⁵ xwa⁵¹ i³⁵ ʈʂʰan²¹⁴", "syllable_count": 4, "sentences": [{"text": "长城是中国的文化遗产。", "target_word": "文化遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护文化遗产。", "target_word": "文化遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老桥是一项文化遗产。", "target_word": "文化遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去参观了那里的文化遗产。", "target_word": "文化遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有三项文化遗产。", "target_word": "文化遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故宫是世界有名的文化遗产。", "target_word": "文化遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文化遗产能让人了解过去。", "target_word": "文化遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上学习本地的文化遗产。", "target_word": "文化遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷讲的故事也是文化遗产。", "target_word": "文化遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的文化遗产吸引了很多人。", "target_word": "文化遗产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "世界文化遗产", "label": "复合"}, {"form": "非物质文化遗产", "label": "复合"}, {"form": "文化遺產", "label": "繁体"}], "register": "书面", "sense_fingerprint": "前人留下的有价值的建筑、故事等文化财富", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe847b-453c-49ae-ad59-f1b51c9b852b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”指冷暖晴雨等气象状况，不能作为建筑长城的所属对象。"}, {"text": "文化遗产", "is_correct": true, "explanation": "正确答案。长城是前人留下的文化遗产，符合句意。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“生日”指人或事件的诞辰，不能与“中国的”组成对建筑长城的描述。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指人的数量，长城是建筑，不能说是中国的人口。"}], "explanations": {"天气": "语义：“天气”指冷暖晴雨等气象状况，不能作为建筑长城的所属对象。", "文化遗产": "正确答案。长城是前人留下的文化遗产，符合句意。", "生日": "搭配：“生日”指人或事件的诞辰，不能与“中国的”组成对建筑长城的描述。", "人口": "语义：“人口”指人的数量，长城是建筑，不能说是中国的人口。"}, "sentence_index": 0, "correct_answer": "文化遗产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里有三只文化遗产。", "explanation": "量词用错。这里应该用〈项〉，“文化遗产”常用“项”计量；“只”多用于动物。"}, {"text": "他去银行存了很多文化遗产。", "explanation": "这里应该用〈财产〉。文化遗产指前人留下的文化财富，不是个人可以存进银行的财产。"}, {"text": "他去纪念品店买了很多文化遗产。", "explanation": "这里应该用〈礼物〉。文化遗产指前人留下的历史与文化，不是可以买卖的商品；买的应是礼物之类的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心跳", "is_correct": false, "explanation": "语义：“心跳”反映人当下的生理状态，与“了解过去”无关。"}, {"text": "速度", "is_correct": false, "explanation": "语义：“速度”描述运动的快慢，与“了解过去”无关。"}, {"text": "文化遗产", "is_correct": true, "explanation": "正确答案。前人留下的文化遗产能让人了解过去，语义通顺。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”只反映当下的身体状况，不与“了解过去”搭配。"}], "explanations": {"心跳": "语义：“心跳”反映人当下的生理状态，与“了解过去”无关。", "速度": "语义：“速度”描述运动的快慢，与“了解过去”无关。", "文化遗产": "正确答案。前人留下的文化遗产能让人了解过去，语义通顺。", "体温": "搭配：“体温”只反映当下的身体状况，不与“了解过去”搭配。"}, "sentence_index": 6, "correct_answer": "文化遗产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在厨房里煮了一锅文化遗产。", "explanation": "这里应该用〈饭菜〉。文化遗产不是能煮的食物，烹饪的对象不能是它。"}, {"text": "这位工程师喝光了文化遗产。", "explanation": "这里应该用〈咖啡〉。文化遗产不是饮品，不能被喝。"}, {"text": "这家饭店的文化遗产很好吃。", "explanation": "这里应该用〈食物〉。文化遗产不是食物，不能用“好吃”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个博物馆里有五本文化遗产。", "corrected_sentence": "这个博物馆里有五项文化遗产。", "error_description": "量词用错：“文化遗产”应用“项”计量，“本”用于书籍，“五本文化遗产”是量词搭配错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些文化遗产们都很重要。", "corrected_sentence": "这些文化遗产都很重要。", "error_description": "词尾用错：“们”只加在指人的名词后面，“文化遗产”是事物，不能说“文化遗产们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
