INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24576, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人在那个地方。", "primary_collocate": null, "pronunciation": "zài chǎng", "ipa": "tsaɪ̯˥˩ ʈʂʰaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他昨天不在场，没看到比赛。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师在场的时候，同学们都很安静。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在场的朋友们一起鼓掌。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出事时我不在场，所以不清楚。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次聚会，大家都在场。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "有你在场，我就放心了。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在场的时候，没有人说话。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好多记者都在场，等着拍照。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子打针时，妈妈一直在场。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你当时在场吗？", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "在场的", "label": "定语形式"}, {"form": "不在场", "label": "否定形式"}], "register": "口语", "sense_fingerprint": "在场：人就在那个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18071dd5-44bf-44c0-9410-71b353ae85d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24576, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指人处在那个地方。"}, {"text": "在唱", "is_correct": false, "explanation": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）声调不同，意思是正在唱歌。"}, {"text": "再长", "is_correct": false, "explanation": "“再长”的第二音节是 zhǎng，与 chǎng 的声母不同（zh 与 ch），意思是继续生长。"}, {"text": "在上", "is_correct": false, "explanation": "“在上”的第二音节是 shàng，与 chǎng 不同，意思是在上面。"}, {"text": "在做", "is_correct": false, "explanation": "“在做”的第二音节是 zuò，与 chǎng 不同，意思是正在做事。"}], "explanations": {"在场": "正确：在场指人处在那个地方。", "在唱": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）声调不同，意思是正在唱歌。", "再长": "“再长”的第二音节是 zhǎng，与 chǎng 的声母不同（zh 与 ch），意思是继续生长。", "在上": "“在上”的第二音节是 shàng，与 chǎng 不同，意思是在上面。", "在做": "“在做”的第二音节是 zuò，与 chǎng 不同，意思是正在做事。"}, "sentence_index": null, "correct_answer": "在场"}, "level_3": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指人处在那个地方，这里指没有到比赛现场，与“没看到比赛”一致。"}, {"text": "缺席", "is_correct": false, "explanation": "语义：“不缺席”表示人到了，与“没看到比赛”自相矛盾。"}, {"text": "投票", "is_correct": false, "explanation": "语义：投票与看比赛无关，句意不通。"}, {"text": "作曲", "is_correct": false, "explanation": "搭配：“没看到比赛”的原因应与比赛相关，“作曲”与之没有搭配关系。"}], "explanations": {"在场": "正确：在场指人处在那个地方，这里指没有到比赛现场，与“没看到比赛”一致。", "缺席": "语义：“不缺席”表示人到了，与“没看到比赛”自相矛盾。", "投票": "语义：投票与看比赛无关，句意不通。", "作曲": "搭配：“没看到比赛”的原因应与比赛相关，“作曲”与之没有搭配关系。"}, "sentence_index": 0, "correct_answer": "在场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河在场，把两岸隔开了。", "explanation": "这里应该用〈横在〉。在场只用于人，河流不能“在场”，应说“横在”。"}, {"text": "那台电脑在场，一直开着。", "explanation": "这里应该用〈放着〉。在场只用于人；电脑是物品，应说“放着”。"}, {"text": "那棵大树在场，挡住了阳光。", "explanation": "这里应该用〈立着〉。在场只用于人；大树是植物，应说“立着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24576, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指人处在那个地方。"}, {"text": "再说", "is_correct": false, "explanation": "“再说”的第二音节是 shuō，与 chǎng 不同，意思是之后再讲。"}, {"text": "在家", "is_correct": false, "explanation": "“在家”的第二音节是 jiā，与 chǎng 不同，意思是待在家里。"}, {"text": "在学", "is_correct": false, "explanation": "“在学”的第二音节是 xué，与 chǎng 不同，意思是正在学习。"}, {"text": "在写", "is_correct": false, "explanation": "“在写”的第二音节是 xiě，与 chǎng 不同，意思是正在书写。"}, {"text": "在唱", "is_correct": false, "explanation": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）声调不同，意思是正在唱歌。"}], "explanations": {"在场": "正确：在场指人处在那个地方。", "再说": "“再说”的第二音节是 shuō，与 chǎng 不同，意思是之后再讲。", "在家": "“在家”的第二音节是 jiā，与 chǎng 不同，意思是待在家里。", "在学": "“在学”的第二音节是 xué，与 chǎng 不同，意思是正在学习。", "在写": "“在写”的第二音节是 xiě，与 chǎng 不同，意思是正在书写。", "在唱": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）声调不同，意思是正在唱歌。"}, "sentence_index": null, "correct_answer": "在场"}, "level_3": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指人处在那个地方，这里说他在场时没有人说话，符合句意。"}, {"text": "开幕", "is_correct": false, "explanation": "搭配：“开幕”用于活动、展览等，不能说“他开幕的时候”，句子不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语法：“桌子”是名词，不能说“他桌子的时候”，句子不通。"}, {"text": "苹果", "is_correct": false, "explanation": "语法：“苹果”是名词，不能说“他苹果的时候”，句子不通。"}], "explanations": {"在场": "正确：在场指人处在那个地方，这里说他在场时没有人说话，符合句意。", "开幕": "搭配：“开幕”用于活动、展览等，不能说“他开幕的时候”，句子不通。", "桌子": "语法：“桌子”是名词，不能说“他桌子的时候”，句子不通。", "苹果": "语法：“苹果”是名词，不能说“他苹果的时候”，句子不通。"}, "sentence_index": 6, "correct_answer": "在场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那张桌子也在场，看着大家吵架。", "explanation": "这里不能用〈在场〉。在场只用于人，指人亲身处在某地；桌子是物品，应说“放在”。"}, {"text": "这盆花昨天一直在场。", "explanation": "这里不能用〈在场〉。在场只用于人；花是植物，不能亲身处在某地，应说“摆在”。"}, {"text": "这块石头在场，没人注意到。", "explanation": "这里不能用〈在场〉。在场只用于人；石头是物品，应说“落在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹那天很在场，错过了表演。", "corrected_sentence": "我妹妹那天不在场，错过了表演。", "error_description": "否定词错误：“很在场”应改为“不在场”。“在场”不能用程度副词“很”修饰；表示人没有到场，要用否定词“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "开庭那天，律师和证人都在场上。", "corrected_sentence": "开庭那天，律师和证人都在场。", "error_description": "多余的方位词：“在场上”指在场地或球场上，开庭的场合应说“在场”，不加“上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24578, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24578, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24578, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "摸起来的感觉。", "primary_collocate": null, "pronunciation": "zhì gǎn", "ipa": "ʈʂɻ̩˥˩ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这条毛巾摸起来，质感又软又厚。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这本书纸张的质感，摸着很舒服。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮沙发的质感比布沙发硬一点。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手摸了摸桌子，想知道木头的质感。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种塑料的质感很差，摸起来很滑。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婴儿的衣服要选质感软的布。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭着眼睛，用手指感受石头的质感。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块丝巾的质感很细，像水一样。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机壳的质感粗粗的，不容易滑掉。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天我爱穿羊毛衫，它的质感很暖。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "質感", "label": "繁体"}, {"form": "一种质感", "label": "量词"}], "register": "中性", "sense_fingerprint": "用手触摸物体时的软硬粗细等感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18071dd5-44bf-44c0-9410-71b353ae85d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "质感", "is_correct": true, "explanation": "「质感」指摸起来的感觉，与「摸起来」「又软又厚」相呼应，说的是毛巾的触感。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：「颜色」是视觉上的色彩，不能用手摸出来，也不能说「又软又厚」。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：「亮度」指光线的明暗，与「摸起来」所指的触觉不符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「价格」不能和「软」「厚」搭配，句中说的是毛巾的触感，不是价钱。"}], "explanations": {"质感": "「质感」指摸起来的感觉，与「摸起来」「又软又厚」相呼应，说的是毛巾的触感。", "颜色": "体貌：「颜色」是视觉上的色彩，不能用手摸出来，也不能说「又软又厚」。", "亮度": "语义：「亮度」指光线的明暗，与「摸起来」所指的触觉不符。", "价格": "搭配：「价格」不能和「软」「厚」搭配，句中说的是毛巾的触感，不是价钱。"}, "sentence_index": 0, "correct_answer": "质感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台收音机的质感很大，隔壁都听得见。", "explanation": "这里应该用〈音量〉。「质感」指摸起来的感觉，不能用来说声音的大小；声音的大小要用「音量」。"}, {"text": "这杯水的质感很高，要小心烫。", "explanation": "这里应该用〈温度〉。「质感」指摸起来的感觉，不能用来说水的冷热，「温度」才是。"}, {"text": "这个箱子的质感很大，搬起来很费力。", "explanation": "这里应该用〈重量〉。「质感」指表面的感觉，不能用来说物体的轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "质感", "is_correct": true, "explanation": "「质感」指摸起来的软硬粗细等感觉，闭着眼睛用手指去感受，正好对应触觉。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」靠口和鼻子感知，用手指感受不到味道。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：「寿命」指存在的年限，不能用手指去感受。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：「感受」后面接「数量」说不通，石头的数量不能靠手指感受。"}], "explanations": {"质感": "「质感」指摸起来的软硬粗细等感觉，闭着眼睛用手指去感受，正好对应触觉。", "味道": "语义：「味道」靠口和鼻子感知，用手指感受不到味道。", "寿命": "语义：「寿命」指存在的年限，不能用手指去感受。", "数量": "搭配：「感受」后面接「数量」说不通，石头的数量不能靠手指感受。"}, "sentence_index": 6, "correct_answer": "质感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件羊毛衫的质感很鲜艳，我很喜欢。", "explanation": "这里应该用〈颜色〉。「质感」指摸起来的感觉，不能用来形容颜色鲜不鲜艳。"}, {"text": "这件羊毛衫的质感很长，穿了三年也没坏。", "explanation": "这里应该用〈寿命〉。「质感」不能用来说衣服能穿多久，「寿命」才是。"}, {"text": "这碗汤的质感很鲜，我喝了两碗。", "explanation": "这里应该用〈味道〉。「质感」指摸起来的感觉，不能用来说食物的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条毛巾有一颗很软的质感，摸起来很舒服。", "corrected_sentence": "这条毛巾有一种很软的质感，摸起来很舒服。", "error_description": "「质感」是抽象名词，量词应用「种」。「颗」用于圆形的小东西，用来计量「质感」是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张桌子有一颗光滑的质感，摸起来很舒服。", "corrected_sentence": "这张桌子有一种光滑的质感，摸起来很舒服。", "error_description": "量词错误：「质感」是抽象名词，量词应用「种」，不能用「颗」。「颗」用于圆形的小东西，不能用来计量「质感」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
