INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24580, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "桥是架在河上让人走的路。", "primary_collocate": null, "pronunciation": "qiáo liáng", "ipa": "tɕʰjɑʊ˧˥ ljɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这条河上新建了一座桥梁。", "target_word": "桥梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥梁很长，走过去要十分钟。", "target_word": "桥梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在河上修一座桥梁。", "target_word": "桥梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨以后，桥梁不能让车通过。", "target_word": "桥梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老桥梁已经有一百年了。", "target_word": "桥梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥梁下面的水很深，孩子别靠近。", "target_word": "桥梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是做桥梁设计的工程师。", "target_word": "桥梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了过河，村里人建了一座桥梁。", "target_word": "桥梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，桥梁上的灯亮了，很漂亮。", "target_word": "桥梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这座桥梁走过去就是学校。", "target_word": "桥梁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "橋梁", "label": "繁体"}, {"form": "一座桥梁", "label": "量词"}], "register": "中性", "sense_fingerprint": "架在河流上供人车通行的实际建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18071dd5-44bf-44c0-9410-71b353ae85d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "船", "is_correct": false, "explanation": "搭配：量词“座”不用于船，船应说“艘”或“条”，“一座船”搭配不当。"}, {"text": "公路", "is_correct": false, "explanation": "搭配：量词“座”不用于公路，公路应说“条”，“一座公路”搭配不当。"}, {"text": "桥梁", "is_correct": true, "explanation": "桥梁：量词“座”与建筑相符，且“河上新建”合乎桥的特点。"}, {"text": "隧道", "is_correct": false, "explanation": "语义：隧道在地下穿行，句中说的是“河上”，二者不相符。"}], "explanations": {"船": "搭配：量词“座”不用于船，船应说“艘”或“条”，“一座船”搭配不当。", "公路": "搭配：量词“座”不用于公路，公路应说“条”，“一座公路”搭配不当。", "桥梁": "桥梁：量词“座”与建筑相符，且“河上新建”合乎桥的特点。", "隧道": "语义：隧道在地下穿行，句中说的是“河上”，二者不相符。"}, "sentence_index": 0, "correct_answer": "桥梁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村口的桥梁挡住了河水，村民的田地没有被淹。", "explanation": "这里应该用〈堤坝〉。堤坝用于拦挡河水；桥梁是供人走的建筑，不能用来挡水。"}, {"text": "他的鼻子上有一座桥梁，显得很高。", "explanation": "这里应该用〈鼻梁〉。桥梁是架在河上供人车通行的建筑，鼻子上高起的部分叫鼻梁。"}, {"text": "这里的桥梁每天接送乘客。", "explanation": "这里应该用〈渡船〉。渡船能载人过河，桥梁是固定的建筑，不能接送乘客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诗歌", "is_correct": false, "explanation": "语义：工程师一般不做诗歌设计，句意不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是人可以设计的对象，与工程师的身份不符。"}, {"text": "桥梁", "is_correct": true, "explanation": "桥梁：“设计桥梁”搭配自然，与工程师的职业相符。"}, {"text": "秘密", "is_correct": false, "explanation": "搭配：“设计”搭配的是建筑、产品等，不说“设计秘密”。"}], "explanations": {"诗歌": "语义：工程师一般不做诗歌设计，句意不通。", "月亮": "语义：月亮不是人可以设计的对象，与工程师的身份不符。", "桥梁": "桥梁：“设计桥梁”搭配自然，与工程师的职业相符。", "秘密": "搭配：“设计”搭配的是建筑、产品等，不说“设计秘密”。"}, "sentence_index": 6, "correct_answer": "桥梁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上游的桥梁蓄满了水，附近的农田有了保障。", "explanation": "这里应该用〈水库〉。水库用于蓄水；桥梁是供人走的建筑，不能用来蓄水。"}, {"text": "这座桥梁把两家院子隔开了。", "explanation": "这里应该用〈围墙〉。围墙用于隔开两块地；桥梁是供人走的建筑，不能用来隔开院子。"}, {"text": "这座桥梁穿过山底，很安全。", "explanation": "这里应该用〈隧道〉。穿过山底的是隧道，桥梁架在水面或空中，不能穿山。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府决定在河上修建一只桥梁。", "corrected_sentence": "政府决定在河上修建一座桥梁。", "error_description": "量词错误：桥梁是大型建筑，量词应用“座”；“只”用于小动物或小件东西，不能用于桥梁。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片桥梁已经建成三年了。", "corrected_sentence": "这座桥梁已经建成三年了。", "error_description": "量词错误：桥梁是大型建筑，量词用“座”；“片”用于树林、草地等平而广的东西，不用于桥梁。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f839809-6c26-42b4-8b7f-0dcce5f051c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
