INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24588, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "增加和删除（文字、项目等）。", "primary_collocate": null, "pronunciation": "zēng shān", "ipa": "tsəŋ˥˥ ʂan˥˥", "syllable_count": 2, "sentences": [{"text": "公司每年都会增删一些课程。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜单每个月都增删几种菜。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆根据读者的需要，增删书的种类。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表格里的人名，你可以自己增删。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份名单你可以根据情况增删。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店会按季节增删商品。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文章写好以后，他又增删了几句话。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每学期都会增删几门选修课。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班的名单老是变，老师要不停增删。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里的软件，你想增删都可以。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "增删了", "label": "体标"}, {"form": "增删过", "label": "体标"}, {"form": "增刪", "label": "繁体"}], "register": "书面", "sense_fingerprint": "对文字、名单、项目等加进一些、删去一些", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b69fe6f-45ff-4aa8-b887-4f71b2511eeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修建", "is_correct": false, "explanation": "搭配：“修建”用于房屋、道路等建筑，不能说修建课程。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”用于房间、房屋，课程不能装修。"}, {"text": "增删", "is_correct": true, "explanation": "“增删”指加入或删去，“公司每年都会增删一些课程”符合句意。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉已有的建筑或设施，与课程的增减不符。"}], "explanations": {"修建": "搭配：“修建”用于房屋、道路等建筑，不能说修建课程。", "装修": "搭配：“装修”用于房间、房屋，课程不能装修。", "增删": "“增删”指加入或删去，“公司每年都会增删一些课程”符合句意。", "拆除": "语义：“拆除”指拆掉已有的建筑或设施，与课程的增减不符。"}, "sentence_index": 0, "correct_answer": "增删"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人增删了一条新路。", "explanation": "这里应该用〈修建〉。增删针对内容、项目等，道路要修建，不能增删。"}, {"text": "他增删了那块石头。", "explanation": "这里应该用〈粉碎〉。增删用于可以逐项加减的项目，石头被打碎要用粉碎。"}, {"text": "天上增删了一场雨。", "explanation": "这里应该用〈下〉。增删用于可以逐项加减的项目，下雨不能增删。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于花草树木，不能种植句子。"}, {"text": "烹调", "is_correct": false, "explanation": "语义：“烹调”指做菜，与修改文章无关。"}, {"text": "增删", "is_correct": true, "explanation": "“增删”指加进或删去文字，“又增删了几句话”符合句意。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”用于房屋、道路，不能修建句子。"}], "explanations": {"种植": "搭配：“种植”用于花草树木，不能种植句子。", "烹调": "语义：“烹调”指做菜，与修改文章无关。", "增删": "“增删”指加进或删去文字，“又增删了几句话”符合句意。", "修建": "搭配：“修建”用于房屋、道路，不能修建句子。"}, "sentence_index": 6, "correct_answer": "增删"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "师傅增删了那辆旧汽车。", "explanation": "这里应该用〈修理〉。增删用于内容、项目，旧汽车要修理，不能增删。"}, {"text": "她增删了一片花园。", "explanation": "这里应该用〈浇灌〉。增删针对可以逐项加减的项目，花园要浇灌，不能增删。"}, {"text": "他增删了整面墙。", "explanation": "这里应该用〈粉刷〉。增删用于内容、项目，墙要粉刷，不能说增删。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们又增删着几次课程。", "corrected_sentence": "他们又增删过几次课程。", "error_description": "体标应用“过”而非“着”：“增删过几次”表示已完成的几次动作，“增删着几次”表示持续状态，与句意不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他增删的很快。", "corrected_sentence": "他增删得很快。", "error_description": "补语标记应用“得”，不能用“的”；正确为“增删得很快”，“增删的很快”错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f88e5b91-3552-487a-ba1c-b5943daea384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
