INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "影像就是拍下来的画面，比如照片或电视上的图。", "primary_collocate": null, "pronunciation": "yǐng xiàng", "ipa": "iŋ˨˩˦ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "电视上的影像很清楚。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这段旧影像里，奶奶还是个年轻姑娘。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段影像拍得有点晃，画面不稳定。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕坏了，影像一直在闪。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手机留下了孩子的影像。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院的大屏幕影像特别大。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着旧影像，想起了老家。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "影像和声音没有同步，看着很别扭。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这些影像发给我。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用相机拍下了湖面上月亮的影像。", "target_word": "影像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段影像", "label": "量词"}, {"form": "影像资料", "label": "复合"}], "register": "中性", "sense_fingerprint": "拍下来的画面，照片或电视上的图（电视影像、旧影像）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4da4f6c8-6bbf-4c97-a4e8-ea8e0f7f3746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24590, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "影像", "is_correct": true, "explanation": "正确：影像，指拍下来的画面。"}, {"text": "印象", "is_correct": false, "explanation": "yìn xiàng 与 yǐng xiàng 第一音节韵母不同（n 与 ng），声调也不同，意思是给人留下的感受。"}, {"text": "影响", "is_correct": false, "explanation": "xiǎng 与 xiàng 声调不同（第三声与第四声），意思是对事物产生的作用。"}, {"text": "引向", "is_correct": false, "explanation": "yǐn 与 yǐng 韵母不同（in 与 ing），意思是引导朝某个方向。"}, {"text": "迎向", "is_correct": false, "explanation": "yíng 与 yǐng 声调不同（第二声与第三声），意思是迎着某个方向。"}], "explanations": {"影像": "正确：影像，指拍下来的画面。", "印象": "yìn xiàng 与 yǐng xiàng 第一音节韵母不同（n 与 ng），声调也不同，意思是给人留下的感受。", "影响": "xiǎng 与 xiàng 声调不同（第三声与第四声），意思是对事物产生的作用。", "引向": "yǐn 与 yǐng 韵母不同（in 与 ing），意思是引导朝某个方向。", "迎向": "yíng 与 yǐng 声调不同（第二声与第三声），意思是迎着某个方向。"}, "sentence_index": null, "correct_answer": "影像"}, "level_3": {"options": [{"text": "影像", "is_correct": true, "explanation": "正确：影像指电视上播放的画面，可以说“很清楚”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是嗅觉感受，不能在电视上呈现，也谈不上清楚与否。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“清楚”形容画面等可见的内容，不能修饰温度。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是数值，与电视画面无关，“电视上的体重很清楚”说不通。"}], "explanations": {"影像": "正确：影像指电视上播放的画面，可以说“很清楚”。", "味道": "语义：味道是嗅觉感受，不能在电视上呈现，也谈不上清楚与否。", "温度": "搭配：“清楚”形容画面等可见的内容，不能修饰温度。", "体重": "语义：体重是数值，与电视画面无关，“电视上的体重很清楚”说不通。"}, "sentence_index": 0, "correct_answer": "影像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在电影院看了一部很好看的影像。", "explanation": "这里应该用〈影片〉。影像指拍下的画面，在电影院看的整部作品要用〈影片〉，量词“部”也搭配〈影片〉。"}, {"text": "这件事对他的成长有很大影像。", "explanation": "这里应该用〈影响〉。影像指画面，“有很大……”说的是作用，要用〈影响〉。"}, {"text": "我每天早上用影像刷牙。", "explanation": "这里应该用〈牙膏〉。刷牙要用牙膏，影像是拍下来的画面，不能用来刷牙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24590, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "影像", "is_correct": true, "explanation": "正确：影像，指拍下来的画面。"}, {"text": "景象", "is_correct": false, "explanation": "jǐng 与 yǐng 声母不同（j 与零声母），声调相同，意思是景色、场面。"}, {"text": "影响", "is_correct": false, "explanation": "xiǎng 与 xiàng 声调不同（第三声与第四声），意思是对事物产生的作用。"}, {"text": "引线", "is_correct": false, "explanation": "yǐn xiàn 与 yǐng xiàng 第一音节韵尾不同（n 与 ng），第二音节 xiàn 与 xiàng 韵母不同，意思是导线或引火的线。"}], "explanations": {"影像": "正确：影像，指拍下来的画面。", "景象": "jǐng 与 yǐng 声母不同（j 与零声母），声调相同，意思是景色、场面。", "影响": "xiǎng 与 xiàng 声调不同（第三声与第四声），意思是对事物产生的作用。", "引线": "yǐn xiàn 与 yǐng xiàng 第一音节韵尾不同（n 与 ng），第二音节 xiàn 与 xiàng 韵母不同，意思是导线或引火的线。"}, "sentence_index": null, "correct_answer": "影像"}, "level_3": {"options": [{"text": "影像", "is_correct": true, "explanation": "正确：影像指拍下的旧画面，“看着”的对象是可见的画面。"}, {"text": "旋律", "is_correct": false, "explanation": "语义：旋律是听觉的，不能用“看着”。"}, {"text": "声音", "is_correct": false, "explanation": "配价：“看着”的对象应是可见的事物，“声音”不能被看。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味不能被看到，与“看着”搭配不当。"}], "explanations": {"影像": "正确：影像指拍下的旧画面，“看着”的对象是可见的画面。", "旋律": "语义：旋律是听觉的，不能用“看着”。", "声音": "配价：“看着”的对象应是可见的事物，“声音”不能被看。", "气味": "语义：气味不能被看到，与“看着”搭配不当。"}, "sentence_index": 6, "correct_answer": "影像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把影像倒进杯子里喝了。", "explanation": "这里应该用〈果汁〉。影像是拍下来的画面，不是可以倒进杯子里喝的饮料。"}, {"text": "他用影像搭了一张桌子。", "explanation": "这里应该用〈木板〉。影像是拍下来的画面，不能用来搭桌子。"}, {"text": "他把影像放进冰箱里冻成了冰。", "explanation": "这里应该用〈水〉。影像是拍下来的画面，不能放进冰箱冻成冰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看了一张很长的影像。", "corrected_sentence": "我看了一段很长的影像。", "error_description": "“一张影像”量词错误：有长度的影像用“段”计量，应为“一段很长的影像”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这只影像删掉了。", "corrected_sentence": "我把这段影像删掉了。", "error_description": "“这只影像”量词错误：影像的量词是“段”，“只”不能用于影像，应为“这段影像”，即“我把这段影像删掉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54ba7f5d-a0b0-46b1-8110-2a1fda43a544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
