INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24594, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "小鸟住在树上叫栖居。", "primary_collocate": null, "pronunciation": "qī jū", "ipa": "tɕʰi˥ tɕy˥", "syllable_count": 2, "sentences": [{"text": "小鸟栖居在高高的树上。", "target_word": "栖居", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天，一对麻雀栖居在我家窗外的树上。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小鸟喜欢栖居在安静的树林里。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树上栖居着一群灰色的小鸟。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟们栖居在树枝上，天黑后不再叫了。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老树上栖居着几只小鸟，孩子们常来看。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨的时候，小鸟都栖居在树叶下面。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在树上放了小房子，让小鸟栖居。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵大树上栖居过很多只小鸟。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "傍晚，小鸟飞回来，栖居在同一棵树上。", "target_word": "栖居", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "棲居", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "小鸟住在树上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62f285c-3fff-4d83-96f3-aac2e819e030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24594, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "栖居", "is_correct": true, "explanation": "正确：栖居 qī jū 指居住、停留，与听到的读音一致。"}, {"text": "七局", "is_correct": false, "explanation": "qī jú 与 qī jū 只有末字声调不同，意思是比赛的第七局。"}, {"text": "器具", "is_correct": false, "explanation": "qì jù 与 qī jū 声调不同，意思是器械、用具。"}, {"text": "契据", "is_correct": false, "explanation": "qì jù 与 qī jū 声调不同，意思是契约和字据。"}], "explanations": {"栖居": "正确：栖居 qī jū 指居住、停留，与听到的读音一致。", "七局": "qī jú 与 qī jū 只有末字声调不同，意思是比赛的第七局。", "器具": "qì jù 与 qī jū 声调不同，意思是器械、用具。", "契据": "qì jù 与 qī jū 声调不同，意思是契约和字据。"}, "sentence_index": null, "correct_answer": "栖居"}, "level_3": {"options": [{"text": "栖居", "is_correct": true, "explanation": "正确：栖居指小鸟停留居住，与“小鸟……在高高的树上”的场景相合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳指在水中运动，小鸟不能在高高的树上游泳，与句意相悖。"}, {"text": "潜水", "is_correct": false, "explanation": "语义：潜水指在水下活动，与高高的树上的场景完全不合。"}, {"text": "停泊", "is_correct": false, "explanation": "搭配：“停泊”多用于船只，不能说“小鸟停泊在高高的树上”。"}], "explanations": {"栖居": "正确：栖居指小鸟停留居住，与“小鸟……在高高的树上”的场景相合。", "游泳": "语义：游泳指在水中运动，小鸟不能在高高的树上游泳，与句意相悖。", "潜水": "语义：潜水指在水下活动，与高高的树上的场景完全不合。", "停泊": "搭配：“停泊”多用于船只，不能说“小鸟停泊在高高的树上”。"}, "sentence_index": 0, "correct_answer": "栖居"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小鸟在天空中栖居。", "explanation": "这里应该用〈飞翔〉。飞翔是在空中移动，栖居指停留居住，不能用于描述在天空中飞行。"}, {"text": "这张桌子在墙角栖居。", "explanation": "这里应该用〈摆放〉。栖居只用于生物住在某处，桌子不能栖居，应说摆放。"}, {"text": "这辆汽车栖居在车库里。", "explanation": "这里应该用〈停放〉。栖居指鸟类在某处居住，汽车不能栖居，应说停放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24594, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "栖居", "is_correct": true, "explanation": "正确：栖居 qī jū 指居住、停留，与听到的读音一致。"}, {"text": "起居", "is_correct": false, "explanation": "qǐ jū（第三声）与 qī jū（第一声）声调不同，意思是日常生活起居。"}, {"text": "棋局", "is_correct": false, "explanation": "qí jú 与 qī jū 两个音节的声调都不同，意思是下棋时的局面。"}, {"text": "齐聚", "is_correct": false, "explanation": "qí jù 与 qī jū 只有声调不同，意思是聚集在一起。"}], "explanations": {"栖居": "正确：栖居 qī jū 指居住、停留，与听到的读音一致。", "起居": "qǐ jū（第三声）与 qī jū（第一声）声调不同，意思是日常生活起居。", "棋局": "qí jú 与 qī jū 两个音节的声调都不同，意思是下棋时的局面。", "齐聚": "qí jù 与 qī jū 只有声调不同，意思是聚集在一起。"}, "sentence_index": null, "correct_answer": "栖居"}, "level_3": {"options": [{"text": "栖居", "is_correct": true, "explanation": "正确：栖居指居住、停留，与“下雨的时候，小鸟都……在树叶下面”的停留语境相合。"}, {"text": "漂浮", "is_correct": false, "explanation": "语义：漂浮指浮在液体或空中，小鸟不会漂浮在树叶下面，与句意不合。"}, {"text": "晾晒", "is_correct": false, "explanation": "语义：晾晒是把东西摊开让风和阳光干燥，不能用来描述小鸟。"}, {"text": "停车", "is_correct": false, "explanation": "搭配：“停车”的主语是车辆，不能说“小鸟停车在树叶下面”。"}], "explanations": {"栖居": "正确：栖居指居住、停留，与“下雨的时候，小鸟都……在树叶下面”的停留语境相合。", "漂浮": "语义：漂浮指浮在液体或空中，小鸟不会漂浮在树叶下面，与句意不合。", "晾晒": "语义：晾晒是把东西摊开让风和阳光干燥，不能用来描述小鸟。", "停车": "搭配：“停车”的主语是车辆，不能说“小鸟停车在树叶下面”。"}, "sentence_index": 6, "correct_answer": "栖居"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头栖居在河底。", "explanation": "这里应该用〈沉〉。栖居只指小鸟住在树上，石头沉在河底应说沉。"}, {"text": "小鸟在我的书包里栖居。", "explanation": "这里应该用〈藏身〉。栖居指小鸟住在树上，躲进书包应说藏身。"}, {"text": "这本书栖居在书架上。", "explanation": "这里应该用〈放〉。栖居指鸟类在某处居住，书不是生物，应说放在书架上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "树洞里栖居一只小鸟。", "corrected_sentence": "树洞里栖居着一只小鸟。", "error_description": "“栖居”描述处所里存在小鸟时，后面要带“着”，应说“栖居着一只小鸟”，漏掉“着”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵老树是一个适合小鸟栖居地方。", "corrected_sentence": "这棵老树是一个适合小鸟栖居的地方。", "error_description": "“栖居”修饰“地方”时要加“的”，应说“适合小鸟栖居的地方”，漏掉“的”后修饰关系不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
