INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24598, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24598, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "存在论是哲学的一个分支，研究「存在」本身，追问事物是否真的存在。", "primary_collocate": null, "pronunciation": "cún zài lùn", "ipa": "tsʰuən˧˥ tsaɪ˥˩ luən˥˩", "syllable_count": 3, "sentences": [{"text": "存在论会问：桌子是不是真的在这里？", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用存在论的办法，问月亮是不是真的存在。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "存在论想知道，梦里的东西算不算真的有。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问鬼是不是真的有，这是存在论的问题。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "存在论关心的是：这个东西到底在不在？", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用存在论的问题让我们想了很久。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了存在论以后，他常问自己周围的东西是真的吗。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个存在论的问题很简单：房间里有没有人？", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上用存在论讨论过独角兽。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "存在论只问一件事：它是不是真的在那里。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "存在論", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "追问一个东西是否真的存在的思考方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62f285c-3fff-4d83-96f3-aac2e819e030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存在论", "is_correct": true, "explanation": "正确：存在论是追问事物是否真的存在的思考方式，可以“会问”桌子是否真的在这里。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单列出可以点的菜，不会问桌子是不是真的在这里。"}, {"text": "天气预报", "is_correct": false, "explanation": "语义：天气预报报告天气情况，不能提出“桌子是不是真的在这里”的问题。"}, {"text": "身高", "is_correct": false, "explanation": "配价：“会问”要求能提问的主体，“身高”不能作“会问”的主语。"}], "explanations": {"存在论": "正确：存在论是追问事物是否真的存在的思考方式，可以“会问”桌子是否真的在这里。", "菜单": "语义：菜单列出可以点的菜，不会问桌子是不是真的在这里。", "天气预报": "语义：天气预报报告天气情况，不能提出“桌子是不是真的在这里”的问题。", "身高": "配价：“会问”要求能提问的主体，“身高”不能作“会问”的主语。"}, "sentence_index": 0, "correct_answer": "存在论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "存在论研究人如何获得可靠的知识。", "explanation": "这里应该用〈认识论〉。存在论追问事物是否真的存在，获得可靠知识的方式属于认识论。"}, {"text": "存在论研究人的情绪和行为。", "explanation": "这里应该用〈心理学〉。情绪和行为属于心理学，存在论追问的是事物是否存在。"}, {"text": "存在论研究古代王朝的兴衰。", "explanation": "这里应该用〈历史学〉。古代王朝的兴衰属于历史学，存在论追问的是事物是否真的存在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存在论", "is_correct": true, "explanation": "正确：存在论是可以学习的哲学思考方式，与“学了……以后，他常问自己周围的东西是真的吗”相合。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“学”后面接知识或技能，不能说“学了食堂”。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是可以学习的内容，也不会引出这种哲学式的追问。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的温度，不是学习的对象，与“常问自己周围的东西是真的吗”的意思无关。"}], "explanations": {"存在论": "正确：存在论是可以学习的哲学思考方式，与“学了……以后，他常问自己周围的东西是真的吗”相合。", "食堂": "搭配：“学”后面接知识或技能，不能说“学了食堂”。", "感冒": "语义：感冒是一种疾病，不是可以学习的内容，也不会引出这种哲学式的追问。", "体温": "语义：体温是身体的温度，不是学习的对象，与“常问自己周围的东西是真的吗”的意思无关。"}, "sentence_index": 6, "correct_answer": "存在论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "存在论研究人与社会的关系。", "explanation": "这里应该用〈社会学〉。人与社会的关系属于社会学，存在论追问的是事物是否真的存在。"}, {"text": "存在论研究国家与权力的运行。", "explanation": "这里应该用〈政治学〉。国家与权力的运行属于政治学，存在论只问事物是否真的存在。"}, {"text": "存在论研究植物如何生长。", "explanation": "这里应该用〈植物学〉。植物如何生长属于植物学，存在论研究的是「存在」本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我读了一本关于存在论书。", "corrected_sentence": "我读了一本关于存在论的书。", "error_description": "“关于存在论”修饰“书”时要加“的”，应说“关于存在论的书”，漏掉“的”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我过学存在论。", "corrected_sentence": "我学过存在论。", "error_description": "表示经历的“过”应紧跟动词“学”，说“学过存在论”，不能放在动词前说“过学存在论”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24600, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24600, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24600, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "考古是挖出很久以前的东西，看看人们以前怎么生活。", "primary_collocate": null, "pronunciation": "kǎo gǔ", "ipa": "kʰɑʊ˨˩˦ ku˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们在山上考古。", "target_word": "考古", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "专家在这里考古已经三年了。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带学生去河边考古。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "挖地时发现了旧陶器，专家决定在这里考古。", "target_word": "考古", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在古城里考古，挖出了很多罐子。", "target_word": "考古", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想长大后去沙漠考古。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考古的人每天都要挖土。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天太热，今天不能去考古了。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们一边考古，一边写记录。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下个月我们要去西安考古。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "考古学", "label": "复合"}, {"form": "考古学家", "label": "复合"}], "register": "中性", "sense_fingerprint": "挖掘古代东西来了解古人生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f270e504-0a47-4d31-b06d-9aa60be4a027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乘地铁", "is_correct": false, "explanation": "语义：地铁是城市交通，不能在山上「乘地铁」。"}, {"text": "逛超市", "is_correct": false, "explanation": "语义：超市是城镇的商业场所，「在山上逛超市」与场所不合。"}, {"text": "考古", "is_correct": true, "explanation": "正确：「在山上考古」指在山区挖掘古物，符合句意。"}, {"text": "考古学", "is_correct": false, "explanation": "语法：「考古学」是学科名词，不能直接作「在山上」后的谓语。"}], "explanations": {"乘地铁": "语义：地铁是城市交通，不能在山上「乘地铁」。", "逛超市": "语义：超市是城镇的商业场所，「在山上逛超市」与场所不合。", "考古": "正确：「在山上考古」指在山区挖掘古物，符合句意。", "考古学": "语法：「考古学」是学科名词，不能直接作「在山上」后的谓语。"}, "sentence_index": 0, "correct_answer": "考古"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在院子里考古了一根水管。", "explanation": "这里应该用〈挖〉。「考古」指挖掘古代遗存，挖水管等现代物件要用「挖」。"}, {"text": "专家去山区考古地质情况。", "explanation": "这里应该用〈考察〉。「考古」的对象是古代遗存，不能用来考察地质。"}, {"text": "他把弟弟考古了一下。", "explanation": "这里应该用〈观察〉。「考古」只用于挖掘古代遗存，不能用于人，这里的意思是「观察」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写作", "is_correct": false, "explanation": "语义：写作与挖土无关，「写作的人每天都要挖土」不合常理。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：下棋不需要挖土，句意不通。"}, {"text": "考古", "is_correct": true, "explanation": "正确：「考古的人」指从事挖掘研究的人，每天都要挖土，符合句意。"}, {"text": "撰著", "is_correct": false, "explanation": "语域：「撰著」是书面语，与口语句的语域不合，且与挖土无关。"}], "explanations": {"写作": "语义：写作与挖土无关，「写作的人每天都要挖土」不合常理。", "下棋": "语义：下棋不需要挖土，句意不通。", "考古": "正确：「考古的人」指从事挖掘研究的人，每天都要挖土，符合句意。", "撰著": "语域：「撰著」是书面语，与口语句的语域不合，且与挖土无关。"}, "sentence_index": 6, "correct_answer": "考古"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们下个月打算考古这条马路。", "explanation": "这里应该用〈修建〉。「考古」指挖掘古代遗存，不能用来指修建现代马路。"}, {"text": "他们在超市考古。", "explanation": "考古要在遗址、古墓等地方进行，超市不是考古的场所，这是场所用错了。"}, {"text": "我们正在考古古代的哲学思想。", "explanation": "这里应该用〈研究〉。「考古」指挖掘古代遗存，不能用来指研究抽象的哲学思想。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们昨天在山上考古着。", "corrected_sentence": "他们昨天在山上考古了。", "error_description": "体标错误：「昨天」表示动作已经完成，「考古」后面应该用「了」，不能用表示持续的「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们去年考古了三个次。", "corrected_sentence": "他们去年考古了三次。", "error_description": "量词错误：「次」是动词「考古」的动量词，不能与「个」叠用，应说「考古了三次」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
