INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24602, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24602, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每个人心里都有的那种感觉和想法，就像你会开心也会难过一样。", "primary_collocate": null, "pronunciation": "rén xìng", "ipa": "ɻən˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "开心和难过都是人性的一部分。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有人性，会笑也会哭。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到别人哭，我们会难过，这是人性。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的人性很简单，开心就笑，难过就哭。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的人性里，都有喜怒哀乐。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，爱和害怕都是人性。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友生病了，我很担心，这就是人性。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事让我们想到人性里的温暖。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人没有人性，不会难过。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人性让我们高兴时想笑，难过时想哭。", "target_word": "人性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "每个人都有的感觉和想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62f285c-3fff-4d83-96f3-aac2e819e030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人性", "is_correct": true, "explanation": "正确：「人性」指每个人都有的感受，可以作「一部分」的整体。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有开心和难过，不是这两种感受的一部分。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会开心或难过，不能包含这两种感受。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：「开心」「难过」是人的感受，树木不能与之搭配。"}], "explanations": {"人性": "正确：「人性」指每个人都有的感受，可以作「一部分」的整体。", "石头": "语义：石头没有开心和难过，不是这两种感受的一部分。", "颜色": "语义：颜色不会开心或难过，不能包含这两种感受。", "树木": "搭配：「开心」「难过」是人的感受，树木不能与之搭配。"}, "sentence_index": 0, "correct_answer": "人性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天的人性很低落。", "explanation": "这里应该用〈情绪〉。「人性」指每个人都有的共同感受，说某人某天的心情要用「情绪」。"}, {"text": "猫喜欢夜里活动，这是它的人性。", "explanation": "这里应该用〈习性〉。「人性」只指人的共同感受，猫的习性要用「习性」。"}, {"text": "这台机器的人性很稳定。", "explanation": "这里应该用〈性能〉。「人性」指人共有的感受，机器的稳定程度要用「性能」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人性", "is_correct": true, "explanation": "正确：「这就是」后接的是人共有的感受，「人性」符合语境。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字不是人的感受，不能说「这就是数字」。"}, {"text": "钟表", "is_correct": false, "explanation": "语义：钟表没有担心这种感受，不能概括这里的情况。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：「这就是」后接感受，窗户不能概括担心这种情绪。"}], "explanations": {"人性": "正确：「这就是」后接的是人共有的感受，「人性」符合语境。", "数字": "语义：数字不是人的感受，不能说「这就是数字」。", "钟表": "语义：钟表没有担心这种感受，不能概括这里的情况。", "窗户": "搭配：「这就是」后接感受，窗户不能概括担心这种情绪。"}, "sentence_index": 6, "correct_answer": "人性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥的人性很牢固。", "explanation": "这里应该用〈质量〉。「人性」指人共有的感受，桥的牢固程度要用「质量」。"}, {"text": "这次考试他的人性很高。", "explanation": "这里应该用〈分数〉。「人性」指每个人共有的感受，考试的成绩要用「分数」。"}, {"text": "他对音乐很有人性。", "explanation": "这里应该用〈兴趣〉。「人性」指人共有的感受，说对某事的喜好要用「兴趣」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只很常见的人性。", "corrected_sentence": "这是一种很常见的人性。", "error_description": "「人性」是抽象名词，应用量词「种」；「只」用于动物等具体事物，不能修饰人性。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部电影让我们看到了人性得温暖。", "corrected_sentence": "这部电影让我们看到了人性的温暖。", "error_description": "「人性」作定语修饰「温暖」时要用「的」，应说「人性的温暖」；「得」用于动词或形容词后引出补语，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24604, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "提问", "is_correct": true, "explanation": "“提问”与“回答”一问一答，是反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "与“回答”在任何义项上都没有反义或近义关系。"}, {"text": "煮饭", "is_correct": false, "explanation": "与“回答”在任何义项上都没有反义或近义关系。"}, {"text": "栽种", "is_correct": false, "explanation": "与“回答”在任何义项上都没有反义或近义关系。"}], "correct_answer": "提问", "explanations": {"提问": "“提问”与“回答”一问一答，是反义关系。", "游泳": "与“回答”在任何义项上都没有反义或近义关系。", "煮饭": "与“回答”在任何义项上都没有反义或近义关系。", "栽种": "与“回答”在任何义项上都没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
